#include <stdio.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    double weighted_sum;
} Transaction;

typedef struct {
    int count;
    double max_weighted_sum;
    int max_transaction_id;
} Metrics;

Metrics filter_transactions(Transaction* transactions, int num_transactions, time_t current_time, double min_weighted_sum, int* transaction_count) {
    Metrics metrics = {0, 0.0, -1};
    *transaction_count = 0;

    for (int i = 0; i < num_transactions; i++) {
        Transaction t = transactions[i];
        time_t age = current_time - t.timestamp;

        if (age <= 3) {
            (*transaction_count)++;
            if (t.weighted_sum > min_weighted_sum) {
                if (t.weighted_sum > metrics.max_weighted_sum) {
                    metrics.max_weighted_sum = t.weighted_sum;
                    metrics.max_transaction_id = t.id;
                }
            }
        }
    }

    return metrics;
}

int main() {
    Transaction transactions[] = {
        {1, time(NULL) - 1, 10.5},
        {2, time(NULL) - 2, 15.0},
        {3, time(NULL) - 4, 20.0},
        {4, time(NULL) - 1, 25.0}
    };
    int transaction_count = 0;
    Metrics metrics = filter_transactions(transactions, 4, time(NULL), 5.0, &transaction_count);

    printf("Transaction Count: %d\n", transaction_count);
    printf("Max Weighted Sum: %.2f, Transaction ID: %d\n", metrics.max_weighted_sum, metrics.max_transaction_id);

    return 0;
}
