#include <stdio.h>
#include <stdlib.h>

#define ERROR_FILE_NOT_FOUND -1
#define ERROR_MEMORY_ALLOCATION -2

struct resource_item {
    char *key;
    char *value;
};

struct resource_bundle {
    struct resource_item *items;
    size_t count;
};

int load_resource_bundle(const char *path, struct resource_bundle **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        return ERROR_FILE_NOT_FOUND;
    }

    struct resource_bundle *new_bundle = malloc(sizeof(struct resource_bundle));
    if (!new_bundle) {
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }

    new_bundle->items = NULL;
    new_bundle->count = 0;

    size_t capacity = 10;
    new_bundle->items = malloc(capacity * sizeof(struct resource_item));
    if (!new_bundle->items) {
        free(new_bundle);
        fclose(file);
        return ERROR_MEMORY_ALLOCATION;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (new_bundle->count >= capacity) {
            capacity *= 2;
            struct resource_item *temp = realloc(new_bundle->items, capacity * sizeof(struct resource_item));
            if (!temp) {
                free(new_bundle->items);
                free(new_bundle);
                fclose(file);
                return ERROR_MEMORY_ALLOCATION;
            }
            new_bundle->items = temp;
        }

        // Assuming the line format is "key=value"
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        new_bundle->items[new_bundle->count].key = strdup(key);
        new_bundle->items[new_bundle->count].value = strdup(value);
        new_bundle->count++;
    }

    fclose(file);
    *bundle = new_bundle;
    return new_bundle->count;
}
