#include <stdlib.h>

typedef struct BSTNode {
    int offset;
    struct BSTNode *left;
    struct BSTNode *right;
} BSTNode;

BSTNode* bst_insert(BSTNode *root, int offset) {
    if (root == NULL) {
        BSTNode *newNode = (BSTNode *)malloc(sizeof(BSTNode));
        if (newNode == NULL) {
            return NULL; // Memory allocation failed
        }
        newNode->offset = offset;
        newNode->left = NULL;
        newNode->right = NULL;
        return newNode;
    }

    if (offset < root->offset) {
        root->left = bst_insert(root->left, offset);
    } else if (offset > root->offset) {
        root->right = bst_insert(root->right, offset);
    }

    return root; // Return the unchanged node pointer
}

BSTNode* insert_offset(BSTNode **root, int offset) {
    if (root == NULL) {
        return NULL; // Invalid root pointer
    }
    *root = bst_insert(*root, offset);
    return *root;
}
