    // Get the bits per sample
    TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    // Get the extra samples
    TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples, sampleInfo);

    // Validate bits per sample
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 &&
        bitsPerSample != 8 && bitsPerSample != 16) {
        TIFFClose(tiff);
        return "Unsupported bits per sample.";
    }

    // Fill the info struct
    info->bitsPerSample = bitsPerSample;
    info->samplesPerPixel = samplesPerPixel;
    info->extraSamples = extraSamples;

    // Prepare sample information string
    snprintf(info->sampleInfo, sizeof(info->sampleInfo), "Extra Samples: %d", extraSamples);
    for (uint16_t i = 0; i < extraSamples; i++) {
        snprintf(info->sampleInfo + strlen(info->sampleInfo), sizeof(info->sampleInfo) - strlen(info->sampleInfo), " %d", sampleInfo[i]);
    }

    TIFFClose(tiff);
    return NULL; // No error
}
