static int dns_resolve(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    // Perform the DNS resolution
    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return (status == EAI_AGAIN) ? DNS_RESOLUTION_TRY_AGAIN : DNS_RESOLUTION_FAIL;
    }

    // Copy the first resolved address to the output buffer
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), sizeof(struct in_addr));
    } else if (res->ai_family == AF_INET6) {
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        memcpy(ip_address, &(ipv6->sin6_addr), sizeof(struct in6_addr));
    } else {
        freeaddrinfo(res);
        return DNS_RESOLUTION_FAIL;
    }

    freeaddrinfo(res);
    return DNS_RESOLUTION_SUCCESS;
}
