#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define INITIAL_CAPACITY 10

typedef struct {
    char **strings;
    int count;
} StringArray;

static StringArray process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        StringArray result = {NULL, 0};
        return result; // File could not be opened
    }

    StringArray result;
    result.strings = malloc(INITIAL_CAPACITY * sizeof(char *));
    result.count = 0;
    int capacity = INITIAL_CAPACITY;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Ignore empty lines and comment lines
        if (line[0] == '\n' || line[0] == '#') {
            continue;
        }

        // Check for strings
        if (line[0] == '\'') {
            if (result.count >= capacity) {
                capacity *= 2;
                result.strings = realloc(result.strings, capacity * sizeof(char *));
            }
            result.strings[result.count] = strdup(line + 1); // Store string without leading quote
            result.strings[result.count][strcspn(result.strings[result.count], "\n")] = '\0'; // Remove newline
            result.count++;
        }

        // Check for string counts
        if (line[0] == '!') {
            if (result.count >= capacity) {
                capacity *= 2;
                result.strings = realloc(result.strings, capacity * sizeof(char *));
            }
            result.strings[result.count] = strdup(line + 1); // Store count without leading exclamation mark
            result.strings[result.count][strcspn(result.strings[result.count], "\n")] = '\0'; // Remove newline
            result.count++;
        }
    }

    fclose(file);
    return result;
}

void free_string_array(StringArray *array) {
    for (int i = 0; i < array->count; i++) {
        free(array->strings[i]);
    }
    free(array->strings);
}

int main() {
    StringArray result = process_file("example.txt");
    for (int i = 0; i < result.count; i++) {
        printf("%s\n", result.strings[i]);
    }
    free_string_array(&result);
    return 0;
}
