typedef struct {
    char config_file_path[256];
    char log_file_path[256];
    char service_root_dir[256];
    char network_address[256];
} Context;

void initialize_context(Context *ctx, const char *config_path, const char *log_path, const char *service_root, const char *network_addr) {
    strncpy(ctx->config_file_path, config_path, sizeof(ctx->config_file_path) - 1);
    ctx->config_file_path[sizeof(ctx->config_file_path) - 1] = '\0';

    strncpy(ctx->log_file_path, log_path, sizeof(ctx->log_file_path) - 1);
    ctx->log_file_path[sizeof(ctx->log_file_path) - 1] = '\0';

    strncpy(ctx->service_root_dir, service_root, sizeof(ctx->service_root_dir) - 1);
    ctx->service_root_dir[sizeof(ctx->service_root_dir) - 1] = '\0';

    if (network_addr) {
        strncpy(ctx->network_address, network_addr, sizeof(ctx->network_address) - 1);
        ctx->network_address[sizeof(ctx->network_address) - 1] = '\0';
    } else {
        ctx->network_address[0] = '\0'; // Set to empty if not provided
    }
}

int main(int argc, char *argv[]) {
    Context ctx;

    const char *config_path = "default_config.conf";
    const char *log_path = "default_log.log";
    const char *service_root = "/usr/local/service";

    if (argc > 1) {
        initialize_context(&ctx, config_path, log_path, service_root, argv[1]);
    } else {
        initialize_context(&ctx, config_path, log_path, service_root, NULL);
    }

    printf("Configuration File Path: %s\n", ctx.config_file_path);
    printf("Log File Path: %s\n", ctx.log_file_path);
    printf("Service Root Directory: %s\n", ctx.service_root_dir);
    printf("Network Address: %s\n", ctx.network_address[0] ? ctx.network_address : "Not provided");

    return 0;
}
