#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define LEX_EOF 0
#define LEX_ID 1
#define LEX_INT 2
#define LEX_FLOAT 3
#define LEX_STR 4
#define LEX_OPERATOR_START 128
#define LEX_OPERATOR_END 255

int getToken(const char *input) {
    int token = -1;
    bool tokenFound = false;
    const char *ptr = input;

    while (*ptr != '\0') {
        switch (*ptr) {
            case ' ':
            case '\n':
            case '\t':
                ptr++;
                continue;
            case '0': case '1': case '2': case '3':
            case '4': case '5': case '6': case '7':
            case '8': case '9':
                token = LEX_INT;
                tokenFound = true;
                break;
            case '"':
                token = LEX_STR;
                tokenFound = true;
                break;
            case '+': case '-': case '*': case '/':
                token = LEX_OPERATOR_START + (*ptr - '+');
                tokenFound = true;
                break;
            default:
                if (isalpha(*ptr)) {
                    token = LEX_ID;
                    tokenFound = true;
                }
                break;
        }

        if (tokenFound) {
            return token;
        }
        ptr++;
    }
    return LEX_EOF;
}

int main() {
    const char *testInput = "int x = 10;";
    int token;

    const char *ptr = testInput;
    while ((token = getToken(ptr)) != LEX_EOF) {
        printf("Token: %d\n", token);
        ptr++;
    }

    return 0;
}
