int compressTIFFImage(TIFF* inputTiff, TIFF* outputTiff, uint8* buffer) {
    uint32 imageWidth, imageLength;
    uint32 scanlineSize;
    tdata_t obuf;
    uint8* bufp;
    uint32 row;

    // Get image dimensions
    TIFFGetField(inputTiff, TIFFTAG_IMAGEWIDTH, &imageWidth);
    TIFFGetField(inputTiff, TIFFTAG_IMAGELENGTH, &imageLength);
    scanlineSize = TIFFScanlineSize(inputTiff);

    obuf = _TIFFmalloc(scanlineSize);
    if (obuf == NULL) {
        return 0; // Memory allocation failed
    }

    bufp = buffer;

    for (row = 0; row < imageLength; row++) {
        // Reverse the order of pixels in the scanline
        for (uint32 col = 0; col < imageWidth; col++) {
            ((uint8*)obuf)[col] = bufp[(row * imageWidth) + (imageWidth - 1 - col)];
        }

        // Write the compressed scanline to the new TIFF file
        if (TIFFWriteScanline(outputTiff, obuf, row, 0) < 0) {
            TIFFError(TIFFFileName(outputTiff), "Error, can't write scanline at %lu", (unsigned long)row);
            _TIFFfree(obuf);
            return 0; // Write error
        }
    }

    _TIFFfree(obuf);
    return 1; // Success
}
