void parse_ip_options(const uint8_t *packet, int length) {
    if (length < 20) { // Minimum IP header length
        printf("Packet too short to contain options\n");
        return;
    }

    const uint8_t *p = packet + 20; // Start after the IP header
    int remaining_length = length - 20;

    while (remaining_length > 0) {
        uint8_t option_type = *p;
        uint8_t option_length = *(p + 1);

        if (option_length == 0) {
            // End of options
            printf("End of options\n");
            break;
        }

        if (option_type == 1) { // No-operation option
            printf("No-operation option (0x%02x), length %u\n", option_type, option_length);
            p += 1; // Move to the next option
            remaining_length -= 1;
            continue;
        }

        if (option_length > remaining_length) {
            printf("Option length %u exceeds remaining length %u\n", option_length, remaining_length);
            break;
        }

        printf("Option (0x%02x), length %u\n", option_type, option_length);

        // Print option data if applicable
        if (option_length > 2) {
            printf("  Data: ");
            for (int i = 2; i < option_length; i++) {
                printf("%02x ", *(p + i));
            }
            printf("\n");
        }

        p += option_length; // Move to the next option
        remaining_length -= option_length;
    }
}
