                &p_out.ai_socktype,
                &p_out.ai_protocol,
                p_out.ai_addrlen,
                &p_out.ai_addrlen,
                NULL,
                canonnamelen_in,
                &canonnamelen_out,
                NULL) != OE_OK)
        {
            ret = OE_EAI_SYSTEM;
            OE_RAISE_ERRNO(OE_EINVAL);
        }

        /* If this is the final element in the enumeration. */
        if (retval == 1)
            break;

