            *port_token = '\0'; // Split hostname and ports
            port_token++;
            sscanf(port_token, "%d:%d", &host.data_port, &host.health_port);
            strncpy(host.hostname, token, sizeof(host.hostname) - 1);
            host.hostname[sizeof(host.hostname) - 1] = '\0'; // Ensure null-termination

            result.hosts = realloc(result.hosts, sizeof(struct downstream_host) * (result.count + 1));
            if (!result.hosts) {
                free(input_copy);
                return result; // Memory allocation failed
            }

            result.hosts[result.count] = host;
            result.count++;
        }
        token = strtok(NULL, ",");
    }

    free(input_copy);
    return result;
}
