void analyze_sentence(const char *sentence, int *vowel_count, int *uppercase_count, int *lowercase_count) {
    *vowel_count = 0;
    *uppercase_count = 0;
    *lowercase_count = 0;

    for (const char *p = sentence; *p != '\0'; p++) {
        char ch = tolower(*p);
