        printf("Vowels: %d\n", vowel_count);
        printf("Uppercase letters: %d\n", uppercase_count);
        printf("Lowercase letters: %d\n", lowercase_count);
        exit(0);
    } else {
        // Parent process
        waitpid(pid, NULL, 0);
    }

    return 0;
}
