static void log_message(char *buffer, size_t buffer_size, const char *format, ...) {
    if (buffer == NULL || buffer_size == 0) {
        return; // No buffer to log to
    }

    va_list ap;
    va_start(ap, format);

    // Format the message into a temporary buffer
    char temp_buffer[MAX_BUFFER_SIZE];
    vsnprintf(temp_buffer, sizeof(temp_buffer), format, ap);

    // Trim the message if it exceeds the buffer size
    size_t msg_length = strlen(temp_buffer);
    if (msg_length >= buffer_size) {
        msg_length = buffer_size - 1; // Leave space for null terminator
    }

    // Copy the trimmed message to the provided buffer
    strncpy(buffer, temp_buffer, msg_length);
    buffer[msg_length] = '\0'; // Null-terminate the string

    va_end(ap);
}
