int isEmpty(StringStack *stack) {
    return stack->top == -1;
}

void push(StringStack *stack, const char *str) {
    if (stack->top == stack->capacity - 1) {
        // Stack is full, handle overflow if necessary
        return;
    }
    char *new_str = (char *)malloc(strlen(str) + 1);
    strcpy(new_str, str);
    if (isEmpty(stack)) {
        stack->push_count++;
    }
    stack->stack[++stack->top] = new_str;
}

void freeStringStack(StringStack *stack) {
    for (int i = 0; i <= stack->top; i++) {
        free(stack->stack[i]);
    }
    free(stack->stack);
    free(stack);
}
