    memset(&s, 0, sizeof(s));
    if (inet_pton(AF_INET6, hostname_or_ip,
                &s.in6.sin6_addr) == 1) {
        s.in6.sin6_family = AF_INET6;

        return new_address_sa(&s.a, sizeof(s.in6));
    }

