char* replace_substrings(const char* input, const char* formatted) {
    if (!input || !formatted) {
        return NULL;
    }

    size_t input_len = strlen(input);
    size_t formatted_len = strlen(formatted);
    size_t output_len = input_len; // Start with the length of the input string
    char* output = malloc(output_len + 1);
    if (!output) {
        return NULL; // Memory allocation failed
    }

    const char* pos = input;
    char* out_ptr = output;
    const char* next_pos;

    while ((next_pos = strstr(pos, "SUBSTR")) != NULL) {
        // Copy the part before the substring
        size_t len_before = next_pos - pos;
        memcpy(out_ptr, pos, len_before);
        out_ptr += len_before;

        // Copy the formatted string
        memcpy(out_ptr, formatted, formatted_len);
        out_ptr += formatted_len;

        // Move past the substring
        pos = next_pos + strlen("SUBSTR");
        output_len += formatted_len - strlen("SUBSTR");
        output = realloc(output, output_len + 1);
        if (!output) {
            return NULL; // Memory allocation failed
        }
        out_ptr = output + (out_ptr - output); // Update out_ptr to the new output location
    }

    // Copy the remaining part of the input string
    strcpy(out_ptr, pos);
    return output;
}
