    if (size == 0) {
        return strdup(ERROR_MSG);
    }

    // Check if the address is valid
    if (address == NULL) {
        return strdup(ERROR_MSG);
    }

    // Allocate a buffer for the output string
    char* result = (char*)malloc(1024); // Adjust size as needed
    if (result == NULL) {
        return strdup(ERROR_MSG);
    }

    if (strcmp(data_type, "int") == 0) {
        int* data = (int*)address;
        if (size < sizeof(int)) {
            free(result);
            return strdup(ERROR_MSG);
        }
        if (strcmp(format, "text") == 0) {
            snprintf(result, 1024, "%d", *data);
        } else if (strcmp(format, "binary") == 0) {
            for (int i = sizeof(int) * 8 - 1; i >= 0; i--) {
                strcat(result, ((*data & (1 << i)) ? "1" : "0"));
            }
        }
    } else if (strcmp(data_type, "float") == 0) {
        float* data = (float*)address;
        if (size < sizeof(float)) {
            free(result);
            return strdup(ERROR_MSG);
        }
        if (strcmp(format, "text") == 0) {
            snprintf(result, 1024, "%f", *data);
        } else if (strcmp(format, "binary") == 0) {
            uint32_t temp;
            memcpy(&temp, data, sizeof(float));
            for (int i = sizeof(float) * 8 - 1; i >= 0; i--) {
                strcat(result, ((temp & (1 << i)) ? "1" : "0"));
            }
        }
    } else {
        free(result);
        return strdup(ERROR_MSG);
    }

    return result;
}
