void convert_to_octal(struct in_addr addr, char *octal_ip) {
    unsigned char *bytes = (unsigned char *)&addr;
    sprintf(octal_ip, "%03o.%03o.%03o.%03o", bytes[0], bytes[1], bytes[2], bytes[3]);
}

int dns_lookup(const char *dns_name, char *octal_ip) {
    struct addrinfo hints, *res;
    struct in_addr addr;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(dns_name, NULL, &hints, &res);
    if (status != 0) {
        return -1; // DNS lookup failed
    }

    for (struct addrinfo *p = res; p != NULL; p = p->ai_next) {
        addr = ((struct sockaddr_in *)p->ai_addr)->sin_addr;
        convert_to_octal(addr, octal_ip);
        break; // Get the first valid IP address
    }

    freeaddrinfo(res);
    return 0; // Success
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <DNS name>\n", argv[0]);
        return 1;
    }

    char octal_ip[16];
    if (dns_lookup(argv[1], octal_ip) == 0) {
        printf("IP Address in octal format: %s\n", octal_ip);
    } else {
        fprintf(stderr, "Failed to resolve DNS name: %s\n", argv[1]);
    }

    return 0;
}
