#define MAX_LINE_LENGTH 1024

char* read_line() {
    char *line = malloc(MAX_LINE_LENGTH);
    if (!line) {
        return NULL; // Memory allocation failed
    }

    fd_set read_fds;
    struct timeval timeout;
    int retval;
    size_t index = 0;

    while (index < MAX_LINE_LENGTH - 1) {
        FD_ZERO(&read_fds);
        FD_SET(STDIN_FILENO, &read_fds);

        timeout.tv_sec = 5; // 5 seconds timeout
        timeout.tv_usec = 0;

        retval = select(STDIN_FILENO + 1, &read_fds, NULL, NULL, &timeout);
        if (retval == -1) {
            free(line);
            return NULL; // Error occurred
        } else if (retval == 0) {
            free(line);
            return NULL; // Timeout occurred
        }

        if (FD_ISSET(STDIN_FILENO, &read_fds)) {
            ssize_t bytes_read = read(STDIN_FILENO, line + index, 1);
            if (bytes_read < 0) {
                free(line);
                return NULL; // Read error
            } else if (bytes_read == 0) {
                break; // EOF reached
            }

            if (line[index] == '\n') {
                line[index] = '\0'; // Null-terminate the string
                return line;
            }

            index++;
        }
    }

    line[index] = '\0'; // Null-terminate in case of line length limit
    return line;
}
