struct record {
    int data;
    // Other fields can be added as needed
};

struct knode {
    struct record *rec;
    struct knode *next;
};

struct queue {
    struct knode *front;
    struct knode *rear;
};

struct queue *create_queue(int size, int order) {
    int max_nodes = size * order; // Calculate maximum number of nodes
    struct queue *q = (struct queue *)malloc(sizeof(struct queue));
    if (!q) {
        perror("Failed to allocate memory for queue");
        return NULL;
    }

    q->front = NULL;
    q->rear = NULL;

    for (int i = 0; i < max_nodes; i++) {
        struct knode *new_node = (struct knode *)kmalloc(sizeof(struct knode));
        if (!new_node) {
            perror("Failed to allocate memory for knode");
            free(q); // Clean up previously allocated queue
            return NULL;
        }

        new_node->rec = (struct record *)malloc(sizeof(struct record));
        if (!new_node->rec) {
            perror("Failed to allocate memory for record");
            kfree(new_node); // Clean up knode
            free(q); // Clean up previously allocated queue
            return NULL;
        }

        new_node->next = NULL;

        // Enqueue the root node (first node)
        if (q->rear == NULL) {
            q->front = new_node;
            q->rear = new_node;
        } else {
            q->rear->next = new_node;
            q->rear = new_node;
        }
    }

    return q;
}
