void init_line_buffer(LineBuffer *line_buffer) {
    line_buffer->buffer = (char *)malloc(BUFFER_SIZE);
    line_buffer->size = BUFFER_SIZE;
    line_buffer->length = 0;
}

void free_line_buffer(LineBuffer *line_buffer) {
    free(line_buffer->buffer);
    line_buffer->buffer = NULL;
    line_buffer->size = 0;
    line_buffer->length = 0;
}

int read_line(FILE *file, LineBuffer *line_buffer) {
    if (line_buffer->length > 0) {
        // If there's already data in the buffer, return it
        return 1;
    }

    line_buffer->length = fread(line_buffer->buffer, 1, line_buffer->size - 1, file);
    if (line_buffer->length == 0) {
        return 0; // End of file or error
    }

    line_buffer->buffer[line_buffer->length] = '\0'; // Null-terminate the string

    // Check for newline character
    char *newline = strchr(line_buffer->buffer, '\n');
    if (newline) {
        *newline = '\0'; // Replace newline with null terminator
        line_buffer->length = newline - line_buffer->buffer; // Update length
    }

    return 1; // Successfully read a line
}

void push_back_line(LineBuffer *line_buffer, const char *line) {
    size_t line_length = strlen(line);
    if (line_length + 1 > line_buffer->size) {
        // Resize buffer if necessary
        line_buffer->buffer = (char *)realloc(line_buffer->buffer, line_length + 1);
        line_buffer->size = line_length + 1;
    }
    strcpy(line_buffer->buffer, line);
    line_buffer->length = line_length;
}

const char *get_line(LineBuffer *line_buffer) {
