std::string concatenateWithWideChar(const std::string& input) {
    int wideCharSize = MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, NULL, 0);
    if (wideCharSize <= 0) {
        return input; // Return original string if conversion fails
    }

    WCHAR* wideCharStr = (WCHAR*)alloca(wideCharSize * sizeof(WCHAR));
    MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, wideCharStr, wideCharSize);

    std::wstring wideString(wideCharStr);
    return input + std::string(wideString.begin(), wideString.end());
}
