char **create_http_request(const char *verb, const char *path, const char *http_version) {
    // Allocate space for the array of string pointers (4 elements: verb, path, version, and NULL)
    char **request = malloc(4 * sizeof(char *));
    if (!request) {
        return NULL; // Allocation failed
    }

    // Allocate and copy the verb
