#include <stdlib.h>
#include <assert.h>

typedef struct {
    void *(*fn_malloc)(size_t size);
    void *(*fn_realloc)(void *ptr, size_t size);
    void (*fn_free)(void *ptr);
} custom_allocator_t;

void *custom_allocator_malloc(custom_allocator_t *allocator, size_t size) {
    assert(allocator);
    assert(allocator->fn_malloc);

    if (size == 0) {
        return NULL;
    }

    return allocator->fn_malloc(size);
}

void custom_allocator_free(custom_allocator_t *allocator, void *ptr) {
    assert(allocator);
    assert(allocator->fn_free);

    allocator->fn_free(ptr);
}

void *custom_allocator_realloc(custom_allocator_t *allocator, void *ptr, size_t new_size) {
    assert(allocator);
    assert(allocator->fn_realloc);

    if (new_size == 0) {
        custom_allocator_free(allocator, ptr);
        return NULL;
    }

    return allocator->fn_realloc(ptr, new_size);
}
