#define AES_KEY_LENGTH 32  // 256 bits
#define AES_IV_LENGTH 16   // 128 bits

EVP_CIPHER_CTX* initialize_aes_256_cbc(const char* password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char key[AES_KEY_LENGTH];
    unsigned char iv[AES_IV_LENGTH];
    unsigned char hash[SHA_DIGEST_LENGTH];

    // Derive key using SHA-1
    SHA1((unsigned char*)password, strlen(password), hash);
    memcpy(key, hash, AES_KEY_LENGTH);

    // Set IV to a fixed value (can be randomized in a real application)
    memset(iv, 0, AES_IV_LENGTH); // Example IV, should be random in production

    // Initialize the cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL; // Initialization failed
    }

    return ctx;
}

void cleanup_aes(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
