    int arr[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    int rows = 3;
    int cols = 3;

    int** matrix = create_2d_matrix(arr, rows, cols);

    // Print the matrix
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }

    // Free the allocated memory
    free_2d_matrix(matrix, rows);

    return 0;
}
