        mysql_stmt_close(stmt);
        return 0;
    }

    va_start(args, num_params);
    for (i = 0; i < num_params; i++) {
        bind[i].buffer_type = MYSQL_TYPE_STRING; // Adjust type as needed
        bind[i].buffer = va_arg(args, char *);
        bind[i].buffer_length = strlen(bind[i].buffer);
        bind[i].is_null = 0;
        bind[i].length = 0;
