#define MAX_FDS 10

int configure_non_blocking_fds(const char *file_paths[], int count) {
    int fd, flags;

    for (int i = 0; i < count; i++) {
        fd = open(file_paths[i], O_RDONLY);
        if (fd == -1) {
            perror("Failed to open file");
            return -errno;
        }

        flags = fcntl(fd, F_GETFL);
        if (flags == -1) {
            perror("Failed to get file descriptor flags");
            close(fd);
            return -errno;
