#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

struct dir_entry {
    char name[256];
    struct dir_entry *subdirs;
    int subdir_count;
};

struct dir_entry *traverse_directory(const char *path, struct dir_entry *parent) {
    struct dir_entry *current_dir = malloc(sizeof(struct dir_entry));
    if (current_dir == NULL) {
        perror("Failed to allocate memory for directory entry");
        return NULL;
    }

    strncpy(current_dir->name, path, sizeof(current_dir->name) - 1);
    current_dir->name[sizeof(current_dir->name) - 1] = '\0';
    current_dir->subdirs = NULL;
    current_dir->subdir_count = 0;

    DIR *dir = opendir(path);
    if (dir == NULL) {
        free(current_dir);
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char full_path[512];
        snprintf(full_path, sizeof(full_path), "%s/%s", path, entry->d_name);

        struct stat statbuf;
        if (stat(full_path, &statbuf) == 0 && S_ISDIR(statbuf.st_mode)) {
            current_dir->subdirs = realloc(current_dir->subdirs, 
                                            (current_dir->subdir_count + 1) * sizeof(struct dir_entry));
            if (current_dir->subdirs == NULL) {
                perror("Failed to allocate memory for subdirectories");
                closedir(dir);
                free(current_dir);
                return NULL;
            }
            current_dir->subdirs[current_dir->subdir_count] = *traverse_directory(full_path, current_dir);
            current_dir->subdir_count++;
        }
    }

    closedir(dir);
    return current_dir;
}

struct dir_entry *get_directory_entry(const char *path) {
    char *resolved_path = realpath(path, NULL);
    if (resolved_path == NULL) {
        return NULL;
    }

    struct dir_entry *root_entry = traverse_directory(resolved_path, NULL);
    free(resolved_path);
    return root_entry;
}
