int socket_connect(const char *protocol, const char *path, const char *name, int timeout_sec) {
    int sockfd = -1;
    struct sockaddr_in server_addr;
    struct timeval timeout;

    if (strcmp(protocol, "TCP") == 0) {
        sockfd = socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);
    } else if (strcmp(protocol, "UDP") == 0) {
        sockfd = socket(PF_INET, SOCK_DGRAM, IPPROTO_UDP);
    } else {
        fprintf(stderr, "Unsupported protocol: %s\n", protocol);
        return -1;
    }

    if (sockfd < 0) {
        perror("socket()");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(name)); // Assuming 'name' contains the port number
    if (inet_pton(AF_INET, path, &server_addr.sin_addr) <= 0) {
        perror("inet_pton()");
        close(sockfd);
        return -1;
    }

    timeout.tv_sec = timeout_sec;
    timeout.tv_usec = 0;

    if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, (const char*)&timeout, sizeof(timeout)) < 0) {
        perror("setsockopt(SO_SNDTIMEO)");
        close(sockfd);
        return -1;
    }

    if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&timeout, sizeof(timeout)) < 0) {
        perror("setsockopt(SO_RCVTIMEO)");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect()");
        close(sockfd);
        return -1;
    }

    return sockfd;
}
