void traverse_directory(const char *dirPath, FileCallback callback, int recurse) {
    struct dirent *entry;
    DIR *dp = opendir(dirPath);

    if (dp == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dp)) != NULL) {
        // Skip the special entries "." and ".."
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char fullPath[PATH_MAX];
        snprintf(fullPath, sizeof(fullPath), "%s/%s", dirPath, entry->d_name);

        // Call the user-provided callback function
        callback(fullPath);

        // If the entry is a directory and recursion is enabled, traverse it
        if (recurse && entry->d_type == DT_DIR) {
            traverse_directory(fullPath, callback, recurse);
        }
    }

    closedir(dp);
}
