#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Blob {
    int x;
    int y;
    int lifetime;
    struct Blob *next;
} Blob;

Blob *CreateBlob(int x, int y, int lifetime) {
    Blob *new_blob = (Blob *)malloc(sizeof(Blob));
    if (new_blob == NULL) {
        perror("Failed to allocate memory for new blob");
        return NULL;
    }
    new_blob->x = x;
    new_blob->y = y;
    new_blob->lifetime = lifetime;
    new_blob->next = NULL;
    return new_blob;
}

void UpdateBlobs(Blob **head) {
    Blob *current = *head;
    Blob *prev = NULL;

    while (current != NULL) {
        current->lifetime--;
        if (current->lifetime <= 0) {
            Blob *to_delete = current;
            if (prev == NULL) {
                *head = current->next; // Update head if needed
            } else {
                prev->next = current->next; // Bypass the current blob
            }
            current = current->next; // Move to the next blob
            free(to_delete); // Free the memory of the deleted blob
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void AddRandomBlob(Blob **head) {
    int x = rand() % 100; // Random x position
    int y = rand() % 100; // Random y position
    int lifetime = rand() % 10 + 1; // Random lifetime between 1 and 10

    Blob *new_blob = CreateBlob(x, y, lifetime);
    if (new_blob == NULL) return;

    new_blob->next = *head; // Insert at the beginning
    *head = new_blob;
}

void PrintBlobs(Blob *head) {
    Blob *current = head;
    while (current != NULL) {
        printf("Blob at (%d, %d) with lifetime %d\n", current->x, current->y, current->lifetime);
        current = current->next;
    }
}

void FreeBlobs(Blob *head) {
    Blob *current = head;
    while (current != NULL) {
        Blob *to_delete = current;
        current = current->next;
        free(to_delete);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    Blob *blobs = NULL;

    // Add random blobs
    for (int i = 0; i < 5; i++) {
        AddRandomBlob(&blobs);
    }

    printf("Initial blobs:\n");
    PrintBlobs(blobs);

    // Update blobs
    UpdateBlobs(&blobs);

    printf("\nBlobs after update:\n");
    PrintBlobs(blobs);

    // Free remaining blobs
    FreeBlobs(blobs);
    return 0;
}
