int evp_cipher_crypt(EVP_CIPHER_CTX *ctx, const unsigned char *key, const unsigned char *iv,
                     unsigned char *data, int data_len, int *out_len, int encrypt) {
    int len;
    int ret;

    // Initialize the context
    if (encrypt) {
        ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    } else {
        ret = EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    }
    if (ret != 1) {
        return -1; // Initialization failed
    }

    // Encrypt or decrypt the data
    ret = encrypt ? EVP_EncryptUpdate(ctx, data, &len, data, data_len) :
                    EVP_DecryptUpdate(ctx, data, &len, data, data_len);
    if (ret != 1) {
        return -1; // Update failed
    }
    *out_len = len;

    // Finalize the encryption/decryption
    ret = encrypt ? EVP_EncryptFinal_ex(ctx, data + len, &len) :
                    EVP_DecryptFinal_ex(ctx, data + *out_len, &len);
    if (ret != 1) {
        return -1; // Finalization failed
    }
    *out_len += len;

    return 0; // Success
}

