#define ERROR -1

int retrieve_file(const char *filename, const char *ip_address, const char *mode) {
    int sock;
    struct sockaddr_in server_addr;
    char buffer[BUFFER_SIZE];
    ssize_t bytes;
    FILE *file;

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return ERROR;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // Assuming server listens on port 8080
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return ERROR;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return ERROR;
    }

    // Open file for writing or reading
    if (strcmp(mode, "write") == 0) {
        file = fopen(filename, "wb");
        if (!file) {
            perror("File open failed");
            close(sock);
            return ERROR;
        }

        // Send request to server
        send(sock, "GET", strlen("GET"), 0);

        // Receive file data
        while ((bytes = recv(sock, buffer, BUFFER_SIZE, 0)) > 0) {
            fwrite(buffer, sizeof(char), bytes, file);
        }

        if (bytes < 0) {
            perror("Receive failed");
            fclose(file);
            close(sock);
            return ERROR;
        }

        fclose(file);
    } else if (strcmp(mode, "read") == 0) {
        file = fopen(filename, "rb");
        if (!file) {
            perror("File open failed");
            close(sock);
            return ERROR;
        }

        // Send file data to server
        while ((bytes = fread(buffer, sizeof(char), BUFFER_SIZE, file)) > 0) {
            send(sock, buffer, bytes, 0);
        }

        fclose(file);
    } else {
        fprintf(stderr, "Invalid mode. Use 'read' or 'write'.\n");
        close(sock);
        return ERROR;
    }

    // Clean up
    close(sock);
    return SUCCESS;
}
