#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    char *key;
    char *value;
    int active; // 1 if active, 0 if inactive
} pair_t;

typedef struct {
    pair_t **buckets;
    size_t order;
} hashtable_t;

size_t hash_str(const char *str);
size_t hashmask(size_t order);
pair_t *hashtable_find_pair(hashtable_t *hashtable, size_t hash, const char *key);

int hashtable_lookup(hashtable_t *hashtable, const char *key, char **value) {
    size_t hash = hash_str(key);
    size_t index = hash & hashmask(hashtable->order);
    pair_t *pair = hashtable_find_pair(hashtable, index, key);
    int collisions = 0;

    if (!pair) {
        *value = NULL;
        return collisions; // Key not found
    }

    // Count collisions
    while (pair) {
        if (strcmp(pair->key, key) == 0) {
            if (pair->active) {
                *value = pair->value;
                return collisions; // Found active value
            } else {
                *value = NULL; // Value is inactive
                return collisions; // Return with inactive value
            }
        }
        collisions++;
        pair = pair->next; // Assuming pair_t has a next pointer for chaining
    }

    *value = NULL; // Key not found
    return collisions;
}
