char* generate_random_uuid() {
    const char *uuid_format = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx";
    char *uuid = malloc(37); // UUID is 36 characters + null terminator
    if (!uuid) {
        return NULL; // Memory allocation failed
    }

    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        free(uuid);
        return NULL; // Failed to open /dev/urandom
    }

    unsigned char random_bytes[16];
    if (read(fd, random_bytes, sizeof(random_bytes)) != sizeof(random_bytes)) {
        close(fd);
        free(uuid);
        return NULL; // Failed to read random bytes
    }
    close(fd);

    for (int i = 0; i < 36; i++) {
        if (uuid_format[i] == 'x') {
            sprintf(&uuid[i], "%x", random_bytes[i / 2] >> ((i % 2) * 4) & 0x0F);
        } else if (uuid_format[i] == 'y') {
            sprintf(&uuid[i], "%x", (random_bytes[i / 2] & 0x3) | 0x8); // y is 8, 9, A, or B
        } else {
            uuid[i] = uuid_format[i];
        }
    }
    uuid[36] = '\0'; // Null-terminate the string

    return uuid;
}
