#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef enum {
    JSON_TYPE_INTEGER,
    JSON_TYPE_FLOAT,
    JSON_TYPE_NULL,
    JSON_TYPE_INVALID
} JsonValueType;

typedef struct {
    void *value;
    JsonValueType type;
} ParsedValue;

ParsedValue parseNumber(const char *input) {
    ParsedValue result;
    char *endptr;

    // Check for null input
    if (input == NULL || *input == '\0') {
        result.value = NULL;
        result.type = JSON_TYPE_NULL;
        return result;
    }

    // Check if the input is an integer
    long intValue = strtol(input, &endptr, 10);
    if (endptr != input && *endptr == '\0') {
        result.value = malloc(sizeof(long));
        if (result.value) {
            *(long *)result.value = intValue;
        }
        result.type = JSON_TYPE_INTEGER;
        return result;
    }

    // Check if the input is a float
    double floatValue = strtod(input, &endptr);
    if (endptr != input && *endptr == '\0') {
        result.value = malloc(sizeof(double));
        if (result.value) {
            *(double *)result.value = floatValue;
        }
        result.type = JSON_TYPE_FLOAT;
        return result;
    }

    // If neither, return invalid type
    result.value = NULL;
    result.type = JSON_TYPE_INVALID;
    return result;
}

void freeParsedValue(ParsedValue *parsed) {
    if (parsed->value) {
        free(parsed->value);
    }
}

int main() {
    const char *testInput = "123.456";
    ParsedValue parsed = parseNumber(testInput);

    if (parsed.type == JSON_TYPE_INTEGER) {
        printf("Parsed Integer: %ld\n", *(long *)parsed.value);
    } else if (parsed.type == JSON_TYPE_FLOAT) {
        printf("Parsed Float: %f\n", *(double *)parsed.value);
    } else if (parsed.type == JSON_TYPE_NULL) {
        printf("Parsed Null\n");
    } else {
        printf("Parsed Invalid\n");
    }

    freeParsedValue(&parsed);
    return 0;
}
