import base64

class SymmetricEncryption:
    def __init__(self, key):
        self.key = key

    def encrypt_ecb(self, message):
        cipher = AES.new(self.key, AES.MODE_ECB)
        padded_message = pad(message.encode(), AES.block_size)
        return base64.b64encode(cipher.encrypt(padded_message)).decode()

    def decrypt_ecb(self, encrypted_message):
        cipher = AES.new(self.key, AES.MODE_ECB)
        decrypted = unpad(cipher.decrypt(base64.b64decode(encrypted_message)), AES.block_size)
        return decrypted.decode()

    def encrypt_cbc(self, message):
        cipher = AES.new(self.key, AES.MODE_CBC)
        iv = get_random_bytes(AES.block_size)
        padded_message = pad(message.encode(), AES.block_size)
        encrypted_message = iv + cipher.encrypt(padded_message)
        return base64.b64encode(encrypted_message).decode()

    def decrypt_cbc(self, encrypted_message):
        encrypted_message = base64.b64decode(encrypted_message)
        iv = encrypted_message[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CBC, iv)
        decrypted = unpad(cipher.decrypt(encrypted_message[AES.block_size:]), AES.block_size)
        return decrypted.decode()

    def encrypt_cfb64(self, message):
        iv = get_random_bytes(AES.block_size)
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        encrypted_message = iv + cipher.encrypt(message.encode())
        return base64.b64encode(encrypted_message).decode()

    def decrypt_cfb64(self, encrypted_message):
        encrypted_message = base64.b64decode(encrypted_message)
        iv = encrypted_message[:AES.block_size]
        cipher = AES.new(self.key, AES.MODE_CFB, iv)
        decrypted = cipher.decrypt(encrypted_message[AES.block_size:])
        return decrypted.decode()

