#define DENSITY_FACTOR 2 // Example factor for density-based compression

char* compress_data(const char *file_path, size_t *compressed_size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t original_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Calculate safe size for compressed data
    *compressed_size = original_size / DENSITY_FACTOR;
    char *compressed_data = (char *)malloc(*compressed_size);
    if (!compressed_data) {
        fclose(file);
        perror("Failed to allocate memory for compressed data");
        return NULL;
    }

    size_t bytes_read = fread(compressed_data, 1, original_size, file);
    if (bytes_read != original_size) {
        free(compressed_data);
        fclose(file);
        perror("Failed to read the entire file");
        return NULL;
    }

    // Simple density-based compression using rand() and bitwise operations
    for (size_t i = 0; i < original_size; i++) {
        compressed_data[i % *compressed_size] ^= (compressed_data[i] ^ (rand() % 256));
    }

    fclose(file);
    return compressed_data;
}
