    const char* subKey = "SOFTWARE\\JavaSoft\\Java Runtime Environment";
    char* jrePath = NULL;
    DWORD pathSize = 0;
    DWORD type;

    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, subKey, 0, KEY_READ, &hKey) == ERROR_SUCCESS) {
        // Query the current version
        char currentVersion[256];
        DWORD currentVersionSize = sizeof(currentVersion);
        if (RegQueryValueExA(hKey, "CurrentVersion", NULL, &type, (LPBYTE)currentVersion, &currentVersionSize) == ERROR_SUCCESS) {
            // Construct the subkey for the current version
            char versionKey[256];
            sprintf(versionKey, "%s\\%s", subKey, currentVersion);

            // Open the subkey for the current version
            if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, versionKey, 0, KEY_READ, &hKey) == ERROR_SUCCESS) {
                // Query the JRE installation path
                pathSize = 0;
                if (RegQueryValueExA(hKey, "JavaHome", NULL, &type, NULL, &pathSize) == ERROR_SUCCESS) {
                    jrePath = (char*)malloc(pathSize);
                    if (RegQueryValueExA(hKey, "JavaHome", NULL, &type, (LPBYTE)jrePath, &pathSize) != ERROR_SUCCESS) {
                        free(jrePath);
                        jrePath = NULL;
                    }
                }
                RegCloseKey(hKey);
            }
        }
        RegCloseKey(hKey);
    }

    return jrePath;
}
