#include <limits>

std::vector<int> findBestCombination(const std::vector<std::pair<int, bool>>& pairs, int target) {
    std::vector<int> bestCombination;
    int bestSum = std::numeric_limits<int>::max();
    size_t n = pairs.size();

    for (size_t i = 0; i < (1 << n); ++i) {
        std::vector<int> currentCombination;
        int currentSum = 0;
        int selectedCount = 0;

        for (size_t j = 0; j < n; ++j) {
            if (i & (1 << j) && !pairs[j].second) { // Check if the j-th pair is selected and not previously selected
                currentCombination.push_back(pairs[j].first);
                currentSum += pairs[j].first;
                selectedCount++;
            }
        }

        if (currentSum <= target) {
            if (currentSum > bestSum || (currentSum == bestSum && selectedCount < bestCombination.size())) {
                bestSum = currentSum;
                bestCombination = currentCombination;
            }
        }
    }

    return bestCombination;
}
