#include <cstring>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

class RobotClient {
public:
    RobotClient(const std::string& ip, int port) : server_ip(ip), server_port(port), sock(-1) {}

    bool initialize() {
        sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) {
            std::cerr << "Error creating socket." << std::endl;
            return false;
        }

        sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(server_port);
        if (inet_pton(AF_INET, server_ip.c_str(), &server_addr.sin_addr) <= 0) {
            std::cerr << "Invalid address/ Address not supported." << std::endl;
            return false;
        }

        if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
            std::cerr << "Connection failed." << std::endl;
            return false;
        }

        return true;
    }

    void sendCommand(const std::string& command) {
        if (send(sock, command.c_str(), command.length(), 0) < 0) {
            std::cerr << "Error sending command." << std::endl;
        }
    }

    std::string receiveResponse() {
        char buffer[1024] = {0};
        int bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            std::cerr << "Error receiving response." << std::endl;
            return "";
        }
        buffer[bytes_received] = '\0';
        return std::string(buffer);
    }

    void closeConnection() {
        if (sock != -1) {
            close(sock);
            sock = -1;
        }
    }

    ~RobotClient() {
        closeConnection();
    }

private:
    std::string server_ip;
    int server_port;
    int sock;
};

int main() {
    std::string ip;
    int port;

    std::cout << "Enter robot IP address: ";
    std::cin >> ip;
    std::cout << "Enter robot port: ";
    std::cin >> port;

    RobotClient client(ip, port);
    if (!client.initialize()) {
        return 1;
    }

    std::string command;
    while (true) {
        std::cout << "Enter command (or 'exit' to quit): ";
        std::cin >> command;
        if (command == "exit") {
            break;
        }
        client.sendCommand(command);
        std::string response = client.receiveResponse();
        std::cout << "Response from robot: " << response << std::endl;
    }

    client.closeConnection();
    return 0;
}
