            if (val != external_data[i]) {
                std::cerr << "External data is incorrect at index " << i << std::endl;
            }
        }
    }

    // Check the length of the external data
    if (obj->GetIndexedPropertiesExternalArrayDataLength() != length) {
        std::cerr << "Length is incorrect" << std::endl;
    }

    // Free the external data
    delete[] external_data;
