Tile** loadMapFromString(const std::string& mapString, int& rows, int& cols) {
    std::istringstream stream(mapString);
    std::string line;
    std::vector<std::vector<Tile>> map;

    while (std::getline(stream, line)) {
        std::vector<Tile> row;
        std::istringstream lineStream(line);
        std::string tileStr;
        while (std::getline(lineStream, tileStr, ' ')) {
            if (tileStr.empty()) continue;
            Tile tile = charToTile(tileStr[0]);
            if (tile == INVALID) {
                throw std::invalid_argument("Invalid tile character in map string.");
            }
            row.push_back(tile);
        }
        map.push_back(row);
    }

    rows = map.size();
    if (rows == 0) return nullptr;

    cols = map[0].size();
    Tile** mapArray = new Tile*[rows];
    for (int i = 0; i < rows; ++i) {
        mapArray[i] = new Tile[cols];
        for (int j = 0; j < cols; ++j) {
            mapArray[i][j] = map[i][j];
        }
    }

    return mapArray;
}

