        return static_cast<int>(std::round(estimatedStorage / MB));
    } else if (estimatedStorage < TB) {
        return static_cast<int>(std::round(estimatedStorage / GB));
    } else {
        return static_cast<int>(std::round(estimatedStorage / TB));
    }
}
