void DrawCurve(const std::vector<std::pair<double, double>>& controlPoints, 
               float lineWidth, 
               float r, float g, float b, 
               int segments) {
    if (controlPoints.size() < 2) return;

    glLineWidth(lineWidth);
    glColor3f(r, g, b);
    glBegin(GL_LINE_STRIP);

    for (int i = 0; i < segments; ++i) {
        double t = static_cast<double>(i) / (segments - 1);
        double x = 0.0;
        double y = 0.0;
        int n = controlPoints.size() - 1;

        for (int j = 0; j <= n; ++j) {
            double binomialCoeff = 1;
            for (int k = 0; k < j; ++k) {
                binomialCoeff *= (n - k) / static_cast<double>(k + 1);
            }
            double basis = binomialCoeff * pow(t, j) * pow(1 - t, n - j);
            x += basis * controlPoints[j].first;
            y += basis * controlPoints[j].second;
        }

        glVertex2d(x, y);
    }

    glEnd();

    // Draw tail if the last control point is not the same as the first
    if (controlPoints.front() != controlPoints.back()) {
        glBegin(GL_LINES);
        glVertex2d(controlPoints.back().first, controlPoints.back().second);
        glVertex2d(controlPoints.front().first, controlPoints.front().second);
        glEnd();
    }
