    uint16_t rows, cols;
    float **array;

    // Open the binary file
    file = fopen("data.bin", "rb");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    // Read the dimensions of the array
    if (fread(&rows, sizeof(uint16_t), 1, file) != 1 || 
        fread(&cols, sizeof(uint16_t), 1, file) != 1) {
        perror("Failed to read dimensions");
        fclose(file);
        return EXIT_FAILURE;
    }

    // Allocate memory for the 2D array
    array = malloc(rows * sizeof(float *));
    if (!array) {
        perror("Failed to allocate memory for rows");
        fclose(file);
        return EXIT_FAILURE;
    }

    for (uint16_t i = 0; i < rows; i++) {
        array[i] = malloc(cols * sizeof(float));
        if (!array[i]) {
            perror("Failed to allocate memory for columns");
            for (uint16_t j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            fclose(file);
            return EXIT_FAILURE;
        }
    }

    // Read the float values into the array
    if (fread(&array[0][0], sizeof(float), rows * cols, file) != rows * cols) {
        perror("Failed to read array data");
        for (uint16_t i = 0; i < rows; i++) {
            free(array[i]);
        }
        free(array);
        fclose(file);
        return EXIT_FAILURE;
    }

    // Print the dimensions of the array
    printf("Array dimensions: %d x %d\n", rows, cols);

    // Free the allocated memory
    for (uint16_t i = 0; i < rows; i++) {
        free(array[i]);
    }
    free(array);
    fclose(file);

