#include <iostream>
#include <cstdlib>
#include <cufft.h>

#define NX 256  // Size of the FFT in x dimension
#define NY 256  // Size of the FFT in y dimension

int main() {
    cufftHandle plan;
    cufftComplex *h_data, *d_data;
    size_t size = sizeof(cufftComplex) * NX * NY;

    // Allocate host memory
    h_data = (cufftComplex*)malloc(size);
    if (h_data == nullptr) {
        std::cerr << "Failed to allocate host memory" << std::endl;
        return EXIT_FAILURE;
    }

    // Initialize host memory with random values
    for (int i = 0; i < NX * NY; i++) {
        h_data[i].x = static_cast<float>(rand()) / RAND_MAX;  // Real part
        h_data[i].y = static_cast<float>(rand()) / RAND_MAX;  // Imaginary part
    }

    // Allocate device memory
    cudaMalloc((void**)&d_data, size);

    // Copy data from host to device
    cudaMemcpy(d_data, h_data, size, cudaMemcpyHostToDevice);

    // Create a 2D FFT plan
    cufftPlan2d(&plan, NX, NY, CUFFT_C2C);

    // Execute the FFT on the device
    cufftExecC2C(plan, d_data, d_data, CUFFT_FORWARD);

    // Copy the result back to host
    cudaMemcpy(h_data, d_data, size, cudaMemcpyDeviceToHost);

    // Clean up
    cufftDestroy(plan);
    cudaFree(d_data);
    free(h_data);

    return EXIT_SUCCESS;
}
