int split_unicode_string(const UChar *input, UChar ***substrings, int **lengths) {
    if (!input || !substrings || !lengths) {
        return 0;
    }

    int count = 0;
    int capacity = 10;
    *substrings = (UChar **)uprv_malloc(capacity * sizeof(UChar *));
    *lengths = (int *)uprv_malloc(capacity * sizeof(int));

    if (!*substrings || !*lengths) {
        return 0;
    }

    const UChar *start = input;
    const UChar *current = input;

    while (*current != 0) {
        if (isCanonSegmentStarter(*current)) {
            if (current > start) {
                int len = current - start;
                if (count >= capacity) {
                    capacity *= 2;
                    *substrings = (UChar **)uprv_realloc(*substrings, capacity * sizeof(UChar *));
                    *lengths = (int *)uprv_realloc(*lengths, capacity * sizeof(int));
                }
                (*substrings)[count] = (UChar *)uprv_malloc((len + 1) * sizeof(UChar));
                memcpy((*substrings)[count], start, len * sizeof(UChar));
                (*substrings)[count][len] = 0; // Null-terminate
                (*lengths)[count] = len;
                count++;
            }
            start = current + 1; // Move to the next character
        }
        current++;
    }

    // Handle the last segment if it exists
    if (current > start) {
        int len = current - start;
        if (count >= capacity) {
            capacity *= 2;
            *substrings = (UChar **)uprv_realloc(*substrings, capacity * sizeof(UChar *));
            *lengths = (int *)uprv_realloc(*lengths, capacity * sizeof(int));
