	// length of the payload.
	replylen = 0;
	for (d = alldevs; d != NULL; d = d->next)
	{
		nif++;

		if (d->description)
			replylen += strlen(d->description);
		if (d->name)
			replylen += strlen(d->name);

		replylen += sizeof(struct rpcap_findalldevs_if);

