int parse_and_transform_text(const char *input_text) {
    if (input_text == NULL) {
        return 0;
    }

    // Allocate memory for the parsed text
    char *parsed_text = (char *)malloc(strlen(input_text) + 1);
    if (parsed_text == NULL) {
        return 0; // Memory allocation failed
    }

    int paragraph_count = 0;
    int in_paragraph = 0;
    size_t j = 0;

    for (size_t i = 0; input_text[i] != '\0'; i++) {
        char c = input_text[i];

        // Transform rules: example rule to replace multiple spaces with a single space
        if (c == ' ' && (j > 0 && parsed_text[j - 1] == ' ')) {
            continue; // Skip this space
        }

        // Count paragraphs based on new lines
        if (c == '\n') {
            if (in_paragraph) {
                paragraph_count++;
                in_paragraph = 0;
            }
            continue; // Skip new line in parsed text
        } else if (c != ' ' && c != '\t') {
            in_paragraph = 1; // We are in a paragraph
        }

        // Store the transformed character
        parsed_text[j++] = c;
    }

    // If the last paragraph was not followed by a new line, count it
    if (in_paragraph) {
        paragraph_count++;
    }

    // Null-terminate the parsed text
    parsed_text[j] = '\0';

    // Free the allocated memory for parsed text
    free(parsed_text);

    return paragraph_count;
}
