#include <stdlib.h>

void* reverse_args(int count, ...) {
    va_list args;
    va_start(args, count);

    // Allocate memory for the reversed arguments
    void** reversed = malloc(count * sizeof(void*));
    if (reversed == NULL) {
        return NULL; // Memory allocation failed
    }

    // Store the arguments in reverse order
    for (int i = 0; i < count; i++) {
        reversed[i] = va_arg(args, void*);
    }

    // Reverse the order
    for (int i = 0; i < count / 2; i++) {
        void* temp = reversed[i];
        reversed[i] = reversed[count - 1 - i];
        reversed[count - 1 - i] = temp;
    }

    va_end(args);
    return reversed; // Return pointer to the allocated memory
}
