void verifyFramebufferPixels(GLuint framebuffer, int width, int height, unsigned char* expectedPixels, GLenum format, GLenum type) {
    glBindFramebuffer(GL_FRAMEBUFFER, framebuffer);
    unsigned char* pixels = new unsigned char[width * height * 4]; // Assuming RGBA format

    glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, pixels);

    // Compare the read pixels with the expected output
    bool match = true;
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            int index = (y * width + x) * 4;
            if (std::memcmp(&pixels[index], &expectedPixels[index], 4) != 0) {
                match = false;
                std::cout << "Mismatch at (" << x << ", " << y << "): "
                          << "Expected (" << (int)expectedPixels[index] << ", "
                          << (int)expectedPixels[index + 1] << ", "
                          << (int)expectedPixels[index + 2] << ", "
                          << (int)expectedPixels[index + 3] << "), "
                          << "Got (" << (int)pixels[index] << ", "
                          << (int)pixels[index + 1] << ", "
                          << (int)pixels[index + 2] << ", "
                          << (int)pixels[index + 3] << ")\n";
            }
        }
    }

    if (match) {
        std::cout << "All pixels match the expected output.\n";
    } else {
        std::cout << "Some pixels do not match the expected output.\n";
    }

    delete[] pixels;
    glBindFramebuffer(GL_FRAMEBUFFER, 0);
}
