public class ImageGenerator {

    public static byte[] generatePPMImage(PageDocument document, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        // Retrieve the page as a BufferedImage
        BufferedImage pageImage = document.getPageAsImage(pageNumber);

        // Scale the image to fit the specified display size
        BufferedImage scaledImage = new BufferedImage(displayWidth, displayHeight, BufferedImage.TYPE_INT_RGB);
        scaledImage.getGraphics().drawImage(pageImage, 0, 0, displayWidth, displayHeight, null);

        // Write the image data to a byte array
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(scaledImage, "ppm", baos);
        return baos.toByteArray();
    }
}
