void saveData(const std::vector<std::string>& dataCollection, const std::string& filename, const std::string& format) {
    std::ofstream file;

    if (format == "XML") {
        file.open(filename);
        if (file.is_open()) {
            file << "<data>\n";
            for (const auto& item : dataCollection) {
                file << "  <item>" << item << "</item>\n";
            }
            file << "</data>\n";
            file.close();
            std::cout << "Saved to " << filename << " in XML format." << std::endl;
        }
    } else if (format == "binary") {
        file.open(filename, std::ios::binary);
        if (file.is_open()) {
            for (const auto& item : dataCollection) {
                uint32_t length = item.size();
                file.write(reinterpret_cast<const char*>(&length), sizeof(length));
                file.write(item.c_str(), length);
            }
            file.close();
            std::cout << "Saved to " << filename << " in binary format." << std::endl;
