#include <iostream>
#include <vector>
#include <chrono>
#include <random>
#include <algorithm>

void generateRandomImage(int width, int height, std::vector<std::vector<int>>& image) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 255);

    image.resize(height, std::vector<int>(width));
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            image[y][x] = dis(gen);
        }
    }
}

double measureDirectIndexing(const std::vector<std::vector<int>>& image) {
    auto start = std::chrono::high_resolution_clock::now();
    int sum = 0;
    for (size_t y = 0; y < image.size(); ++y) {
        for (size_t x = 0; x < image[y].size(); ++x) {
            sum += image[y][x];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    return std::chrono::duration<double, std::milli>(end - start).count();
}

double measureBoundaryClamping(const std::vector<std::vector<int>>& image) {
    auto start = std::chrono::high_resolution_clock::now();
    int sum = 0;
    int height = image.size();
    int width = image[0].size();
    for (int y = -1; y <= height; ++y) {
        for (int x = -1; x <= width; ++x) {
            int clampedY = std::max(0, std::min(height - 1, y));
            int clampedX = std::max(0, std::min(width - 1, x));
            sum += image[clampedY][clampedX];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    return std::chrono::duration<double, std::milli>(end - start).count();
}

double measureScalarAccess(const std::vector<std::vector<int>>& image) {
    auto start = std::chrono::high_resolution_clock::now();
    int sum = 0;
    for (size_t y = 0; y < image.size(); ++y) {
        const int* row = image[y].data();
        for (size_t x = 0; x < image[y].size(); ++x) {
            sum += row[x];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    return std::chrono::duration<double, std::milli>(end - start).count();
}

int main() {
    int width = 800;
    int height = 600;
    std::vector<std::vector<int>> image;

    generateRandomImage(width, height, image);

    double directTime = measureDirectIndexing(image);
    double clampTime = measureBoundaryClamping(image);
    double scalarTime = measureScalarAccess(image);

    std::cout << "Direct Indexing Time: " << directTime << " ms\n";
    std::cout << "Boundary Clamping Time: " << clampTime << " ms\n";
    std::cout << "Scalar Access Time: " << scalarTime << " ms\n";

    return 0;
}
