void vertical_flip(void *pixels, size_t width, size_t height, size_t pixel_size) {
    if (pixels == NULL || width == 0 || height == 0) {
        return;
    }

    size_t stride = width * pixel_size;
    void *line_buffer = malloc(stride);
    if (line_buffer == NULL) {
        return; // Memory allocation failed
    }

    unsigned char *top = static_cast<unsigned char *>(pixels);
    unsigned char *bottom = top + (height - 1) * stride;

    for (size_t y = 0; y < height / 2; ++y) {
        memcpy(line_buffer, top, stride);
        memcpy(top, bottom, stride);
        memcpy(bottom, line_buffer, stride);
        top += stride;
        bottom -= stride;
    }

    free(line_buffer);
}
