void MatrixProjectionTest(int numSamples, int tableSize, int inputDim) {
    // Generate random matrix and vector
    std::vector<std::vector<float>> matrix(tableSize, std::vector<float>(inputDim));
    std::vector<float> vector(inputDim);

    std::mt19937 gen(42); // Fixed seed for reproducibility
    std::uniform_real_distribution<float> dis(0.0f, 1.0f);

    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < inputDim; ++j) {
            matrix[i][j] = dis(gen);
