    }

    for (int j = 0; j < inputDim; ++j) {
        vector[j] = dis(gen);
    }

    // Perform projection
    std::vector<float> projected(tableSize, 0.0f);
    for (int i = 0; i < tableSize; ++i) {
        for (int j = 0; j < inputDim; ++j) {
            projected[i] += matrix[i][j] * vector[j];
        }
