        std::cerr << "Usage: " << argv[0] << " <pid_file> <magic_number>" << std::endl;
        return 1;
    }

    std::string pid_file = argv[1];
    std::string magic_number = argv[2];

    check_process_status(pid_file, magic_number);
    return 0;
