char* generate_insert_sql(const char* table_name, const char* geometry_column, const char* fid_column, const char* values) {
    // Allocate enough memory for the SQL command
    size_t sql_length = strlen("INSERT INTO ") + strlen(table_name) + strlen(" VALUES ()") + strlen(values) + 1;
    if (geometry_column) {
        sql_length += strlen(geometry_column) + 2; // for the comma and space
    }
    if (fid_column) {
        sql_length += strlen(fid_column) + 2; // for the comma and space
    }

    char* sql_command = (char*)malloc(sql_length);
    if (!sql_command) {
        return NULL; // Memory allocation failed
    }

    // Start building the SQL command
    strcpy(sql_command, "INSERT INTO ");
    strcat(sql_command, table_name);

    // Add columns if they are specified
    if (fid_column || geometry_column) {
        strcat(sql_command, " (");
        if (fid_column) {
            strcat(sql_command, fid_column);
            if (geometry_column) {
                strcat(sql_command, ", ");
            }
        }
        if (geometry_column) {
            strcat(sql_command, geometry_column);
        }
        strcat(sql_command, ") ");
    }

    // Add the values
    strcat(sql_command, "VALUES (");
    strcat(sql_command, values);
    strcat(sql_command, ");");

    return sql_command;
}
