char* calculate_discid(CDIO_CD_ROM *cdrom) {
    if (!cdrom) {
        return NULL;
    }

    int num_tracks = cdio_cdrom_get_num_tracks(cdrom);
    uint32_t sum_lbas = 0;

    for (int i = 1; i <= num_tracks; i++) {
        lba_t lba = cdio_cdrom_get_track_lba(cdrom, i);
        sum_lbas += lba;
    }

    uint32_t discid = (sum_lbas / 0xff) << 24;

    // Print the computed DISCID to the debug log
    printf("Computed DISCID: %u\n", discid);

    // Convert to string for return
    char *discid_str = malloc(11); // Enough for uint32_t + null terminator
    if (discid_str) {
        snprintf(discid_str, 11, "%u", discid);
    }

    return discid_str;
}
