#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 100

typedef struct {
    int adjMatrix[MAX_NODES][MAX_NODES];
    int numNodes;
} Graph;

void initGraph(Graph *g, int numNodes) {
    g->numNodes = numNodes;
    for (int i = 0; i < numNodes; i++) {
        for (int j = 0; j < numNodes; j++) {
            g->adjMatrix[i][j] = 0;
        }
    }
}

void addEdge(Graph *g, int src, int dest) {
    g->adjMatrix[src][dest] = 1;
    g->adjMatrix[dest][src] = 1; // Undirected graph
}

void dfs(Graph *g, int node, int visited[]) {
    visited[node] = 1;
    for (int i = 0; i < g->numNodes; i++) {
        if (g->adjMatrix[node][i] == 1 && !visited[i]) {
            dfs(g, i, visited);
        }
    }
}

int countConnectedComponents(Graph *g) {
    int visited[MAX_NODES] = {0};
    int count = 0;

    for (int i = 0; i < g->numNodes; i++) {
        if (!visited[i]) {
            dfs(g, i, visited);
            count++;
        }
    }
    return count;
}

int buildGraphFromEdges(Graph *g, char *edges[], int edgeCount) {
    int maxNode = -1;
    for (int i = 0; i < edgeCount; i++) {
        int src, dest;
        sscanf(edges[i], "%d-%d", &src, &dest);
        if (src > maxNode) maxNode = src;
        if (dest > maxNode) maxNode = dest;
        addEdge(g, src, dest);
    }
    return maxNode + 1; // Return the number of nodes
}

int main() {
    Graph g;
    char *edges[] = {"0-1", "1-2", "3-4", "5-6", "6-7"};
    int edgeCount = sizeof(edges) / sizeof(edges[0]);

    int numNodes = buildGraphFromEdges(&g, edges, edgeCount);
    initGraph(&g, numNodes);

    int connectedComponents = countConnectedComponents(&g);
    printf("Number of connected components: %d\n", connectedComponents);

    return 0;
}
