class CIMValue {
public:
    enum Type { STRING, ARRAY, NULL_TYPE };

    CIMValue(const std::string& value) : type(STRING), strValue(value) {}
    CIMValue(const std::vector<CIMValue>& array) : type(ARRAY), arrayValue(array) {}
    CIMValue() : type(NULL_TYPE) {}

    Type getType() const { return type; }
    std::string getString() const { return strValue; }
    std::vector<CIMValue> getArray() const { return arrayValue; }

private:
    Type type;
    std::string strValue;
    std::vector<CIMValue> arrayValue;
};

void appendCIMValueToString(const CIMValue& value, std::string& output) {
    switch (value.getType()) {
        case CIMValue::STRING:
            output += value.getString();
            break;
        case CIMValue::ARRAY: {
            const auto& array = value.getArray();
            output += "[";
            for (size_t i = 0; i < array.size(); ++i) {
                appendCIMValueToString(array[i], output);
                if (i < array.size() - 1) {
                    output += ", ";
                }
            }
            output += "]";
            break;
        }
        case CIMValue::NULL_TYPE:
            output += "null";
            break;
    }
}
