    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    SoundData *sound_data = malloc(sizeof(SoundData));
    if (!sound_data) {
        fclose(file);
        snprintf(error_msg, MAX_ERROR_MSG, "Error: Memory allocation failed");
