        free(sound_data);
        snprintf(error_msg, MAX_ERROR_MSG, "Error: Memory allocation for sound data failed");
        return NULL;
    }

    size_t read_size = fread(sound_data->data, 1, file_size, file);
    fclose(file);

    if (read_size != file_size) {
        free(sound_data->data);
        free(sound_data);
        snprintf(error_msg, MAX_ERROR_MSG, "Error: File read error");
        return NULL;
    }

    sound_data->size = file_size;
    return sound_data;
