void create_and_delete_tempfile(char *tempname) {
    // Create a unique temporary file name
    char template[] = "/tmp/tempfileXXXXXX"; // Template for mkstemp
    int fd = mkstemp(template);

    if (fd == -1) {
        perror("Failed to create temporary file");
        return;
