#include <string.h>
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>

char* base64_encode(const unsigned char *input, int length) {
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);
    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(bio, input, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    char *output = (char *)malloc(bufferPtr->length + 1);
    memcpy(output, bufferPtr->data, bufferPtr->length);
    output[bufferPtr->length] = '\0';

    return output;
}

char* hmac_sha1_base64(const char *message, const char *key) {
    unsigned char *hmac_result;
    unsigned int hmac_length = 20; // SHA1 produces a 20-byte hash
    hmac_result = (unsigned char *)malloc(hmac_length);

    HMAC(EVP_sha1(), key, strlen(key), (unsigned char *)message, strlen(message), hmac_result, &hmac_length);

    char *base64_result = base64_encode(hmac_result, hmac_length);
    free(hmac_result);

    return base64_result;
}

int main() {
    const char *message = "Hello, World!";
    const char *key = "secret_key";

    char *signature = hmac_sha1_base64(message, key);
    printf("Signature: %s\n", signature);

    free(signature);
    return 0;
}
