#include <boost/python.hpp>
#include <openssl/sha.h>
#include <string>
#include <cstring>
#include <iomanip>
#include <sstream>
#include <vector>

std::string kdf2(const std::string& password, const std::string& master_key, size_t output_length) {
    const size_t hash_length = SHA_DIGEST_LENGTH;
    std::vector<unsigned char> derived_key;
    derived_key.reserve(output_length);

    unsigned int iterations = 1;
    size_t total_length = 0;

    while (total_length < output_length) {
        std::string iteration_input = password + std::to_string(iterations) + master_key;
        unsigned char hash[hash_length];
        SHA1(reinterpret_cast<const unsigned char*>(iteration_input.c_str()), iteration_input.size(), hash);

        size_t to_copy = std::min(hash_length, output_length - total_length);
        derived_key.insert(derived_key.end(), hash, hash + to_copy);
        total_length += to_copy;
        iterations++;
    }

    return std::string(derived_key.begin(), derived_key.end());
}

BOOST_PYTHON_MODULE(kdf_module) {
    using namespace boost::python;
    def("kdf2", kdf2);
}
