void* aligned_malloc(size_t size) {
    const size_t cache_line_size = 64; // Example cache line size
    size_t total_size = size + cache_line_size - 1 + sizeof(void*);
    void* ptr = malloc(total_size);
    if (!ptr) {
        return NULL;
    }

    void** aligned_ptr = (void**)(((uintptr_t)ptr + sizeof(void*) + cache_line_size - 1) & ~(cache_line_size - 1));
    aligned_ptr[-1] = ptr; // Store the original pointer just before the aligned memory

