            if (!selected[j] && values[j].second) {
                if (currentValue + values[j].first <= target) {
                    currentValue += values[j].first;
                    selected[j] = true;
                }
            }
        }

        // Update the best value if the current one is better
        if (currentValue > bestValue && currentValue <= target) {
            bestValue = currentValue;
        }
    }

