typedef std::vector<std::vector<float>> Image;

Image convolve(const Image &inputImage, const Image &filter, float bias, int stride) {
    int inputHeight = inputImage.size();
    int inputWidth = inputImage[0].size();
    int filterHeight = filter.size();
    int filterWidth = filter[0].size();

    // Calculate output dimensions
    int outputHeight = (inputHeight - filterHeight) / stride + 1;
    int outputWidth = (inputWidth - filterWidth) / stride + 1;

    // Allocate output image
    Image outputImage(outputHeight, std::vector<float>(outputWidth, 0));

