void format_double(double val, char buf[32], size_t *out_len) {
    if (isnan(val)) {
        snprintf(buf, 32, "NaN");
        *out_len = strlen(buf);
        return;
    }
    if (isinf(val)) {
        snprintf(buf, 32, (val > 0) ? "Infinity" : "-Infinity");
        *out_len = strlen(buf);
