int case_insensitive_match(const char* str1, const char* str2) {
    if (str1 == NULL || str2 == NULL) {
        return -1; // Error: one of the strings is NULL
    }

    int match_level = 0;
    while (*str1 && *str2) {
        if (tolower((unsigned char)*str1) == tolower((unsigned char)*str2)) {
            match_level++;
        }
        str1++;
        str2++;
    }

    // If one string is longer than the other, we can consider it a partial match
    if (*str1 || *str2) {
        return match_level; // Return the level of matching so far
    }

    return match_level; // Return full match level if both strings are equal
}
