#include <iostream>
#include <sstream>
#include <vector>
#include <string>
#include <stdexcept>

struct Option {
    std::string name;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    std::stringstream ss(input);
    std::string item;

    while (std::getline(ss, item, ',')) {
        size_t pos = item.find('=');
        if (pos == std::string::npos || pos == 0 || pos == item.length() - 1) {
            throw std::invalid_argument("Malformed input: each option must be a key=value pair.");
        }

        Option option;
        option.name = item.substr(0, pos);
        option.value = item.substr(pos + 1);

        if (option.name.empty() || option.value.empty()) {
            throw std::invalid_argument("Malformed input: key and value must be non-empty strings.");
        }

        options.push_back(option);
    }

    return options;
}
