void percolation_step(std::vector<int>* sites, double probability, int time_step) {
    if (sites->empty()) return;

    // Seed the random number generator
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    // Randomly select a site index
    size_t index = std::rand() % sites->size();

    // Apply percolation rule based on the site's index and time step
    if (static_cast<double>(std::rand()) / RAND_MAX < probability) {
        (*sites)[index] += time_step; // Update the site value based on the time step
    }
}
