std::vector<std::string> extract_url_components(const std::string& url) {
    std::vector<std::string> components;
    std::string protocol, host, port;

    // Extract protocol
    size_t pos = url.find("://");
    if (pos != std::string::npos) {
        protocol = url.substr(0, pos);
        pos += 3; // Move past "://"
    } else {
        pos = 0; // No protocol found
    }

    // Extract host and port
    size_t host_end = url.find('/', pos);
    size_t port_pos = url.find(':', pos);

    if (port_pos != std::string::npos && (host_end == std::string::npos || port_pos < host_end)) {
        host = url.substr(pos, port_pos - pos);
        size_t port_end = (host_end != std::string::npos) ? host_end : url.length();
        port = url.substr(port_pos + 1, port_end - port_pos - 1);
    } else {
        host = url.substr(pos, host_end - pos);
        port = "80"; // Default port
    }

    components.push_back(protocol);
    components.push_back(host);
    components.push_back(port);

    return components;
}
