    // Re-link the sorted sections
    for (size_t i = 0; i < count - 1; i++) {
        section_array[i]->next = section_array[i + 1];
    }
    section_array[count - 1]->next = NULL; // Last section points to NULL

    // Copy sorted sections back to the original array
    for (size_t i = 0; i < count; i++) {
        sections[i] = section_array[i];
    }

    free(section_array);
    return 0;
}
