class TestAllocator {
public:
    void* allocate(size_t size) {
        return std::malloc(size);
    }

    void deallocate(void* ptr) {
        std::free(ptr);
    }
};

void initialize_test_allocator(int argc, char* argv[]) {
    TestAllocator allocator;
    const int lengths[] = {10, 20, 30, 40, 50};
    const int num_arrays = sizeof(lengths) / sizeof(lengths[0]);
    bool verbose = (argc > 1 && std::strcmp(argv[1], "-v") == 0);

    for (int i = 0; i < num_arrays; ++i) {
        size_t size = lengths[i];
        char* array = static_cast<char*>(allocator.allocate(size));

        if (array) {
            if (verbose) {
                std::cout << "Allocated array of size " << size 
                          << " at address " << static_cast<void*>(array) << std::endl;
            }
            allocator.deallocate(array);
        } else {
            std::cerr << "Memory allocation failed for size " << size << std::endl;
        }
    }
}

int main(int argc, char* argv[]) {
    initialize_test_allocator(argc, argv);
    return 0;
}
