#include <stdio.h>
#include <stdlib.h>
#include <wchar.h>
#include <locale.h>

wchar_t *ReadFileAsUnicode(const char *filename)
{
    FILE *finput;
    long filesize;
    wchar_t *buffer;
    size_t num;

    // Set the locale to support Unicode
    setlocale(LC_ALL, "");

    if ((finput = fopen(filename, "rb")) == NULL) {
        fprintf(stderr, "Error: Cannot open file %s\n", filename);
        return NULL;
    }

    if (fseek(finput, 0, SEEK_END) != 0 || (filesize = ftell(finput)) < 0 || fseek(finput, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error: File error in file %s\n", filename);
        fclose(finput);
        return NULL;
    }

    // Allocate buffer for wide characters
    buffer = malloc((filesize + sizeof(wchar_t)) * sizeof(wchar_t));
    if (buffer == NULL) {
        fprintf(stderr, "Error: Error allocating %ld bytes of memory\n", filesize + sizeof(wchar_t));
        fclose(finput);
        return NULL;
    }

    // Read the file contents
    num = fread(buffer, sizeof(wchar_t), filesize / sizeof(wchar_t), finput);
    if (ferror(finput)) {
        fprintf(stderr, "Error: Error reading file %s\n", filename);
        free(buffer);
        fclose(finput);
        return NULL;
    }

    buffer[num] = L'\0'; // Null-terminate the wide string
    fclose(finput);
    return buffer;
}
