#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode *children[ALPHABET_SIZE];
} TrieNode;

TrieNode* createNode() {
    TrieNode *node = (TrieNode *)malloc(sizeof(TrieNode));
    node->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        node->children[i] = NULL;
    }
    return node;
}

void insert(TrieNode *root, const char *str) {
    while (*str) {
        unsigned char index = (unsigned char)*str;
        if (!root->children[index]) {
            root->children[index] = createNode();
        }
        root = root->children[index];
        root->count++;
        str++;
    }
}

void countOccurrences(TrieNode *node, int *occurrences) {
    if (node == NULL) return;
    occurrences[node->count]++;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        countOccurrences(node->children[i], occurrences);
    }
}

int* countCharacterOccurrences(const char *str) {
    TrieNode *root = createNode();
    insert(root, str);

    int *occurrences = (int *)calloc(ALPHABET_SIZE, sizeof(int));
    countOccurrences(root, occurrences);

    // Free the trie
    // (Memory cleanup code can be added here if needed)

    return occurrences;
}

int main() {
    const char *input = "hello world";
    int *occurrences = countCharacterOccurrences(input);

    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (occurrences[i] > 0) {
            printf("Character '%c' occurred %d times\n", (char)i, occurrences[i]);
        }
    }

    free(occurrences);
    return 0;
}
