#define MAX_LEN 100

static int memo[MAX_LEN][MAX_LEN];

int countWaysUtil(int length, int choose) {
    if (choose == 0) return 1; // One way to choose nothing
    if (length == 0) return 0;  // No letters left to choose from

    if (memo[length][choose] != -1) return memo[length][choose];

    // Choose the current letter in either case (uppercase or lowercase)
    int include = countWaysUtil(length - 1, choose - 1) * 2;
    // Do not choose the current letter
    int exclude = countWaysUtil(length - 1, choose);

    memo[length][choose] = include + exclude;
    return memo[length][choose];
}

int countWays(int length, int choose) {
    memset(memo, -1, sizeof(memo)); // Initialize memoization array
    return countWaysUtil(length, choose);
}

