#include <iostream>
#include <vector>
#include <random>
#include <cassert>

enum InputType {
    DENSE,
    SPARSE,
    SEQUENCE
};

std::vector<std::vector<float>> createRandomInputMatrix(int batchSize, int inputSize, InputType type) {
    std::vector<std::vector<float>> matrix;
    std::mt19937 generator(std::random_device{}());
    std::uniform_real_distribution<float> distribution(0.0f, 1.0f);

    if (type == DENSE) {
        matrix.resize(batchSize, std::vector<float>(inputSize));
        for (int i = 0; i < batchSize; ++i) {
            for (int j = 0; j < inputSize; ++j) {
                matrix[i][j] = distribution(generator);
            }
        }
    } else if (type == SPARSE) {
        matrix.resize(batchSize, std::vector<float>(inputSize, 0.0f));
        for (int i = 0; i < batchSize; ++i) {
            for (int j = 0; j < inputSize / 10; ++j) { // Sparse: only 10% filled
                int index = generator() % inputSize;
                matrix[i][index] = distribution(generator);
            }
        }
    } else if (type == SEQUENCE) {
        matrix.resize(batchSize, std::vector<float>(inputSize));
        for (int i = 0; i < batchSize; ++i) {
            for (int j = 0; j < inputSize; ++j) {
                matrix[i][j] = static_cast<float>(j) / inputSize; // Sequential data
            }
        }
    } else {
        throw std::invalid_argument("Invalid input type");
    }

    return matrix;
}

int main() {
    int batchSize = 5;
    int inputSize = 10;

    auto denseMatrix = createRandomInputMatrix(batchSize, inputSize, DENSE);
    auto sparseMatrix = createRandomInputMatrix(batchSize, inputSize, SPARSE);
    auto sequenceMatrix = createRandomInputMatrix(batchSize, inputSize, SEQUENCE);

    // Output the matrices for verification
    std::cout << "Dense Matrix:\n";
    for (const auto& row : denseMatrix) {
        for (const auto& val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    std::cout << "\nSparse Matrix:\n";
    for (const auto& row : sparseMatrix) {
        for (const auto& val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    std::cout << "\nSequence Matrix:\n";
    for (const auto& row : sequenceMatrix) {
        for (const auto& val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    return 0;
}
