    // Initialize sumdp and probs
    for (i = 0; i < num_words; i++) {
        (*sumdp)[i] = 0.0;
        for (j = 0; j < num_topics; j++) {
            (*probs)[i][j] = 0.0;
        }
    }

    // Calculate topic probabilities
    for (i = 0; i < num_words; i++) {
        double total_frequency = 0.0;
        for (j = 0; j < num_topics; j++) {
            total_frequency += wp[i][j];
        }

        for (j = 0; j < num_topics; j++) {
            if (total_frequency > 0) {
                (*probs)[i][j] = wp[i][j] / total_frequency;
            } else {
                (*probs)[i][j] = 0.0;
            }
            (*sumdp)[i] += (*probs)[i][j];
        }
    }
