#include <vector>
#include <iostream>
#include <cmath>

using uchar = unsigned char;

std::vector<std::vector<uchar>> gaussian_filter(const std::vector<std::vector<uchar>>& image, 
                                                int image_width, 
                                                int image_height, 
                                                const std::vector<std::vector<double>>& kernel, 
                                                int kernel_width, 
                                                int kernel_height) {
    int k_center_x = kernel_width / 2;
    int k_center_y = kernel_height / 2;
    std::vector<std::vector<uchar>> filtered_image(image_height, std::vector<uchar>(image_width, 0));

    for (int y = 0; y < image_height; ++y) {
        for (int x = 0; x < image_width; ++x) {
            double sum = 0.0;
            double weight_sum = 0.0;

            for (int ky = 0; ky < kernel_height; ++ky) {
                for (int kx = 0; kx < kernel_width; ++kx) {
                    int image_x = x + kx - k_center_x;
                    int image_y = y + ky - k_center_y;

                    if (image_x >= 0 && image_x < image_width && image_y >= 0 && image_y < image_height) {
                        sum += image[image_y][image_x] * kernel[ky][kx];
                        weight_sum += kernel[ky][kx];
                    }
                }
            }

            filtered_image[y][x] = static_cast<uchar>(std::round(sum / weight_sum));
        }
    }

    return filtered_image;
}

int main() {
    // Example usage
    std::vector<std::vector<uchar>> image = {
        {255, 255, 255, 255},
        {255, 0, 0, 255},
        {255, 0, 0, 255},
        {255, 255, 255, 255}
    };

    std::vector<std::vector<double>> kernel = {
        {1.0, 2.0, 1.0},
        {2.0, 4.0, 2.0},
        {1.0, 2.0, 1.0}
    };

    int image_width = 4;
    int image_height = 4;
    int kernel_width = 3;
    int kernel_height = 3;

    auto filtered_image = gaussian_filter(image, image_width, image_height, kernel, kernel_width, kernel_height);

    for (const auto& row : filtered_image) {
        for (const auto& pixel : row) {
            std::cout << static_cast<int>(pixel) << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
