void additiveBlitWithAA(unsigned char* srcImage, unsigned char* dstImage, int width, int height, int x, int y, const float* alphaValues) {
    int x1, y1;
    int srcIndex, dstIndex;
    unsigned char r, g, b;
    unsigned char srcR, srcG, srcB;
    float alpha;

    // Ensure the blit position is within bounds
    if (x < 0 || y < 0 || x >= width || y >= height) return;

    for (int j = 0; j < height; j++) {
        for (int i = 0; i < width; i++) {
            x1 = x + i;
            y1 = y + j;

            // Check bounds for destination
            if (x1 < 0 || y1 < 0 || x1 >= width || y1 >= height) continue;

            // Calculate source index
            srcIndex = (j * width + i) * 3; // Assuming 3 bytes per pixel (RGB)
            srcR = srcImage[srcIndex];
            srcG = srcImage[srcIndex + 1];
            srcB = srcImage[srcIndex + 2];

            // Calculate destination index
            dstIndex = (y1 * width + x1) * 3;

            // Get the alpha value for anti-aliasing
            alpha = alphaValues[j * width + i];

            // Blend the source pixel with the destination pixel using additive blending
            r = static_cast<unsigned char>(std::min(255, (dstImage[dstIndex] + static_cast<int>(srcR * alpha))));
            g = static_cast<unsigned char>(std::min(255, (dstImage[dstIndex + 1] + static_cast<int>(srcG * alpha))));
            b = static_cast<unsigned char>(std::min(255, (dstImage[dstIndex + 2] + static_cast<int>(srcB * alpha))));

            // Update the destination pixel
            dstImage[dstIndex] = r;
            dstImage[dstIndex + 1] = g;
            dstImage[dstIndex + 2] = b;
        }
    }
}
