template<typename... Types>
class Variant {
public:
    using VariantType = std::variant<Types...>;

    Variant() = default;

    template<typename T>
    Variant& operator=(T&& value) {
        using ValueType = std::decay_t<T>;
        constexpr bool isSupported = (std::is_same_v<ValueType, Types> || ...);

        if (!isSupported) {
            throw std::invalid_argument("Unsupported type for variant assignment");
        }

        variant_ = std::forward<T>(value);
        return *this;
    }

    const VariantType& get() const {
        return variant_;
    }

private:
    VariantType variant_;
};

// Example usage
int main() {
    Variant<int, double, std::string> var;

    try {
        var = 42; // Assigning an int
        std::cout << "Assigned int: " << std::get<int>(var.get()) << std::endl;

        var = 3.14; // Assigning a double
        std::cout << "Assigned double: " << std::get<double>(var.get()) << std::endl;

        var = std::string("Hello"); // Assigning a string
        std::cout << "Assigned string: " << std::get<std::string>(var.get()) << std::endl;

        var = true; // This will throw an exception
    } catch (const std::invalid_argument& e) {
        std::cerr << e.what() << std::endl;
    }

    return 0;
}
