#include <vector>
#include <unordered_map>

class DisjointSetUnion {
public:
    DisjointSetUnion(int size) {
        parent.resize(size);
        for (int i = 0; i < size; ++i) {
            parent[i] = i;
        }
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
        }
    }

private:
    std::vector<int> parent;
};

bool arePairwiseConnected(const std::vector<int>& vec1, const std::vector<int>& vec2) {
    int maxElement = 0;
    for (int num : vec1) {
        maxElement = std::max(maxElement, num);
    }
    for (int num : vec2) {
        maxElement = std::max(maxElement, num);
    }

    DisjointSetUnion dsu(maxElement + 1);

    // Assuming vec1 contains pairs to union
    for (size_t i = 0; i < vec1.size(); i += 2) {
        if (i + 1 < vec1.size()) {
            dsu.unionSets(vec1[i], vec1[i + 1]);
        }
    }

    // Check if all elements in vec2 are connected to the first element of vec1
    int root = dsu.find(vec1[0]);
    for (int num : vec2) {
        if (dsu.find(num) != root) {
            return false;
        }
    }
    return true;
}
