#define MAX_VALUE 1000 // Example maximum value
#define BUFFER_SIZE 1024

static int update_max_value(const char *index_file, int *max_value) {
    FILE *file = fopen(index_file, "r");
    if (!file) {
        return 0; // File not present or error occurred
    }

    char buffer[BUFFER_SIZE];
    size_t total_size = 0;
    char *content = NULL;

    // Read file contents
    while (fgets(buffer, sizeof(buffer), file)) {
        size_t len = strlen(buffer);
        char *new_content = realloc(content, total_size + len + 1);
        if (!new_content) {
            free(content);
            fclose(file);
            return 0; // Memory allocation error
        }
        content = new_content;
        memcpy(content + total_size, buffer, len);
        total_size += len;
        content[total_size] = '\0'; // Null-terminate the string
    }

    fclose(file);

    // Count pieces (lines) in the content
    int piece_count = 0;
    char *line = strtok(content, "\n");
    while (line) {
        piece_count++;
        line = strtok(NULL, "\n");
    }

    free(content);

    // Update max value based on the number of pieces
    if (piece_count > *max_value) {
        *max_value = piece_count;
    }

    return 1; // Success
}
