class LinearSolver {
public:
    virtual std::vector<double> solve(const std::vector<std::vector<double>>& matrix, const std::vector<double>& rhs) = 0;
};

void scaleMatrix(std::vector<std::vector<double>>& matrix, const std::vector<double>& scalingFactors) {
    for (size_t i = 0; i < matrix.size(); ++i) {
        for (size_t j = 0; j < matrix[i].size(); ++j) {
            matrix[i][j] *= scalingFactors[i];
        }
    }
}

std::vector<double> solveLinearSystem(const std::vector<std::vector<double>>& matrix, const std::vector<double>& rhs, LinearSolver& solver, const std::vector<double>& scalingFactors) {
