#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

typedef void (*callback_t)(const char *message);

void format_and_call(callback_t cb, const char *format, ...) {
    va_list ap;
    va_start(ap, format);

    size_t buffer_size = 256;
    char *buffer = (char *)malloc(buffer_size);
    if (buffer == NULL) {
        return; // Handle memory allocation failure
    }

    int len = vsnprintf(buffer, buffer_size, format, ap);
    if (len < 0) {
        free(buffer);
        return; // Handle formatting error
    }

    if (len >= buffer_size) {
        // Message is too large, allocate a larger buffer
        buffer_size = len + 1; // +1 for null terminator
        char *new_buffer = (char *)realloc(buffer, buffer_size);
        if (new_buffer == NULL) {
            free(buffer);
            return; // Handle memory allocation failure
        }
        buffer = new_buffer;
        vsnprintf(buffer, buffer_size, format, ap); // Reformat with new buffer size
    }

    cb(buffer); // Call the callback with the formatted message
    free(buffer); // Free the allocated buffer
    va_end(ap);
}
