#include <string.h>

#define KEY_LENGTH 9
#define MAX_TEXT_LENGTH 256

void encrypt(const char *text, const char *key, char *encrypted) {
    int text_length = strlen(text);
    for (int i = 0, j = 0; i < text_length; i++) {
        char current_char = text[i];
        if (current_char >= 'a' && current_char <= 'z') {
            encrypted[i] = key[(current_char - 'a') % KEY_LENGTH];
        } else if (current_char >= 'A' && current_char <= 'Z') {
            encrypted[i] = key[(current_char - 'A') % KEY_LENGTH];
        } else {
            encrypted[i] = current_char; // Non-alphabetic characters remain unchanged
        }
        j++;
    }
    encrypted[text_length] = '\0'; // Null-terminate the encrypted string
}

int main() {
    char key[KEY_LENGTH + 1];
    char text[MAX_TEXT_LENGTH];
    char encrypted[MAX_TEXT_LENGTH];

