public class XmlParser
{
    public static Dictionary<string, string> ParseXml(string xmlString, HashSet<string> ignoreElements)
    {
        var result = new Dictionary<string, string>();

        XmlReaderSettings settings = new XmlReaderSettings
        {
            IgnoreWhitespace = true,
            IgnoreComments = true
        };

        using (XmlReader reader = XmlReader.Create(new System.IO.StringReader(xmlString), settings))
        {
            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && !ignoreElements.Contains(reader.Name))
                {
                    string elementName = reader.Name;
                    if (reader.Read() && reader.NodeType == XmlNodeType.Text)
                    {
                        string elementValue = reader.Value;
                        result[elementName] = elementValue;
                    }
                }
            }
        }

        return result;
    }
}
