    public static List<int> GenerateRandomList(int count, int minValue, int maxValue)
    {
        Random random = new Random();
        List<int> list = new List<int>();
        for (int i = 0; i < count; i++)
        {
            list.Add(random.Next(minValue, maxValue));
        }
        return list;
    }

    public static List<int> ShuffleList(List<int> list)
    {
        Random random = new Random();
        for (int i = list.Count - 1; i > 0; i--)
        {
            int j = random.Next(0, i + 1);
            int temp = list[i];
            list[i] = list[j];
            list[j] = temp;
        }
        return list;
    }

    public static List<int> SortList(List<int> list)
    {
        list.Sort();
        return list;
    }

    public static bool CompareLists(List<int> original, List<int> sorted)
    {
        return original.Count == sorted.Count && original.TrueForAll(x => sorted.Contains(x));
    }
