        {
            rng.GetBytes(datagram);
        }
        return datagram;
    }

    public static void TestDatagramEqualityAndHashCode(int size, int testCount)
    {
        byte[][] datagrams = new byte[testCount][];
        for (int i = 0; i < testCount; i++)
        {
            datagrams[i] = GenerateRandomDatagram(size);
        }

        for (int i = 0; i < testCount; i++)
        {
            for (int j = i + 1; j < testCount; j++)
            {
                bool areEqual = datagrams[i].SequenceEqual(datagrams[j]);
                int hash1 = datagrams[i].GetHashCode();
                int hash2 = datagrams[j].GetHashCode();

                if (areEqual && hash1 != hash2)
                {
                    Console.WriteLine($"Datagrams {i} and {j} are equal but have different hash codes.");
                }
                else if (!areEqual && hash1 == hash2)
                {
                    Console.WriteLine($"Datagrams {i} and {j} are not equal but have the same hash code.");
                }
            }
        }
    }
}

