using System;

public class MatrixGenerator
{
    public static T[,] CreateMatrix<T>(int rows, int columns, T minValue, T maxValue) where T : IComparable
    {
        Random random = new Random();
        T[,] matrix = new T[rows, columns];

        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            {
                matrix[i, j] = GetRandomValue(random, minValue, maxValue);
            }
        }

        return matrix;
    }

    private static T GetRandomValue<T>(Random random, T minValue, T maxValue) where T : IComparable
    {
        if (typeof(T) == typeof(int))
        {
            return (T)(object)random.Next(Convert.ToInt32(minValue), Convert.ToInt32(maxValue));
        }
        else if (typeof(T) == typeof(double))
        {
            double min = Convert.ToDouble(minValue);
            double max = Convert.ToDouble(maxValue);
            return (T)(object)(random.NextDouble() * (max - min) + min);
        }
        else if (typeof(T) == typeof(float))
        {
            float min = Convert.ToSingle(minValue);
            float max = Convert.ToSingle(maxValue);
            return (T)(object)(random.NextDouble() * (max - min) + min);
        }
        else
        {
            throw new NotSupportedException($"Type {typeof(T)} is not supported.");
        }
    }
}
