    def __init__(self, environment):
        self.environment = environment  # A 3D grid representing the environment

    def is_block_free(self, x, y, z):
        return self.environment.get((x, y, z), None) is None

    def place_block(self, x, y, z, block_type):
        self.environment[(x, y, z)] = block_type

    def generate_tree(self, start_x, start_y, start_z):
        trunk_length = random.randint(4, 8)
        self.create_trunk(start_x, start_y, start_z, trunk_length)

    def create_trunk(self, x, y, z, length):
        for i in range(length):
            if self.is_block_free(x, y, z + i):
                self.place_block(x, y, z + i, 'trunk')
            else:
                break  # Stop if a block is already present

        # Create branches
        self.create_branches(x, y, z + length - 1)

    def create_branches(self, x, y, z):
        branch_count = random.randint(2, 4)
        for _ in range(branch_count):
            angle = random.uniform(0, 2 * 3.14159)  # Random angle in radians
            branch_length = random.randint(2, 5)
