using System.Security.Cryptography;
using System.Text;

public class Decryptor
{
    public static string DecryptTripleDES(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        if (string.IsNullOrEmpty(base64EncryptedMessage))
            return null;

        byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = key;
            tdes.IV = iv;
            tdes.Mode = CipherMode.CBC;
            tdes.Padding = PaddingMode.PKCS7;

            using (ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV))
            using (MemoryStream ms = new MemoryStream(encryptedBytes))
            using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            using (StreamReader sr = new StreamReader(cs))
            {
                return sr.ReadToEnd();
            }
        }
    }
}
