    static async Task Main(string[] args)
    {
        string keyFilePath = "path/to/your/keyfile"; // Replace with your key file path
        string commandTemplate = "yourCommand {0} {1}"; // Replace with your command template
        string commandLine = string.Format(commandTemplate, DateTime.Now, keyFilePath);

        await ExecuteCommandAsync(commandLine);
    }

    static async Task ExecuteCommandAsync(string commandLine)
    {
        var processStartInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe", // Use "bash" for Linux/Mac
            Arguments = $"/c {commandLine}", // Adjust for Linux/Mac if necessary
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        using (var process = new Process { StartInfo = processStartInfo })
        {
            process.OutputDataReceived += (sender, e) => 
            {
                if (!string.IsNullOrEmpty(e.Data))
                {
                    Console.WriteLine($"OUTPUT: {e.Data}");
                }
            };

            process.ErrorDataReceived += (sender, e) => 
            {
                if (!string.IsNullOrEmpty(e.Data))
                {
                    Console.WriteLine($"ERROR: {e.Data}");
                }
            };

            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            bool exited = await Task.Run(() => process.WaitForExit(60000)); // 60 seconds timeout

            if (!exited)
            {
                Console.WriteLine("Process timed out. Terminating...");
                process.Kill();
            }

            Console.WriteLine($"Process exited with code: {process.ExitCode}");
        }
    }
}
