[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly string _connectionString;

    public ResourceController(string connectionString)
    {
        _connectionString = connectionString;
    }

    [HttpPut("updateResource")]
    public IActionResult UpdateResource([FromBody] ResourceUpdateRequest request)
    {
        var jsonObject = new JObject();

        if (!ModelState.IsValid)
        {
            jsonObject["success"] = "false";
            jsonObject["error"] = "Invalid request data.";
            return BadRequest(jsonObject);
        }

        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();
                var command = new SqlCommand("UPDATE Resources SET Name = @newName, Description = @newDescription WHERE Id = @id", connection);
                command.Parameters.AddWithValue("@newName", request.NewName);
                command.Parameters.AddWithValue("@newDescription", request.NewDescription);
                command.Parameters.AddWithValue("@id", request.Id);

                int rowsAffected = command.ExecuteNonQuery();
                if (rowsAffected > 0)
                {
                    jsonObject["success"] = "true";
                    jsonObject["updatedResource"] = new JObject
                    {
                        ["id"] = request.Id,
                        ["name"] = request.NewName,
                        ["description"] = request.NewDescription
                    };
                    return Ok(jsonObject);
                }
                else
                {
                    jsonObject["success"] = "false";
                    jsonObject["error"] = "Resource not found.";
                    return NotFound(jsonObject);
                }
            }
        }
        catch (SqlException ex)
        {
            jsonObject["success"] = "false";
            jsonObject["error"] = ex.Message;
            return StatusCode(500, jsonObject);
        }
    }
}

public class ResourceUpdateRequest
{
    public int Id { get; set; }
    public string NewName { get; set; }
