using Cassandra;
using System.Collections.Generic;

public class CassandraHelper
{
    public void ExecuteBatchInsert(ISession session, string insertQuery, Dictionary<string, byte[]> outgoingPayload)
    {
        // Create a BatchStatement
        var batch = new BatchStatement();
        batch.Add(new SimpleStatement(insertQuery));

        // Set outgoing payload
        foreach (var kvp in outgoingPayload)
        {
            batch.SetOutgoingPayload(kvp.Key, kvp.Value);
        }

        // Execute the batch statement
        var result = session.Execute(batch);

        // Assert incoming payload
        var incomingPayload = result.GetOutgoingPayload();
        System.Diagnostics.Debug.Assert(incomingPayload != null, "Incoming payload should not be null.");
        System.Diagnostics.Debug.Assert(incomingPayload.Count == outgoingPayload.Count, "Incoming payload should have the same number of elements as outgoing payload.");

        // Assert contents of outgoing and incoming payload
        foreach (var kvp in outgoingPayload)
        {
            System.Diagnostics.Debug.Assert(incomingPayload.ContainsKey(kvp.Key), $"Incoming payload should contain key: {kvp.Key}");
            System.Diagnostics.Debug.Assert(incomingPayload[kvp.Key].SequenceEqual(kvp.Value), $"Contents of outgoing and incoming payload for key {kvp.Key} should be the same.");
        }
    }
}
