using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public class ProcessManager
{
    public void StartProcess(ProcessStartInfo startInfo, string trackingFolder, int timeout)
    {
        if (!Directory.Exists(trackingFolder))
        {
            throw new InvalidOperationException("Tracking folder does not exist.");
        }

        string trackingFilePath = Path.Combine(trackingFolder, "process_id.txt");
        using (var process = new Process())
        {
            process.StartInfo = startInfo;
            process.Start();

            File.WriteAllText(trackingFilePath, process.Id.ToString());

            var sentinelThread = new Thread(() =>
            {
                if (!process.WaitForExit(timeout))
                {
                    // Clean up tracking file if the process does not complete in time
                    if (File.Exists(trackingFilePath))
                    {
                        File.Delete(trackingFilePath);
                    }
                    Environment.Exit(0); // Exit sentinel process
                }
            });

            sentinelThread.Start();
        }
    }
}
