public int addTown(String townName) {
    int lastInsertedId = -1;
    Connection c = null;
    PreparedStatement ps = null;
    ResultSet rs = null;

    try {
        c = DriverManager.getConnection("jdbc:your_database_url", "username", "password");
        c.setAutoCommit(false);

        ps = c.prepareStatement("INSERT INTO Towns(name) VALUES(?);", Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, townName);
        ps.executeUpdate();

        rs = ps.getGeneratedKeys();
        if (rs.next()) {
            lastInsertedId = rs.getInt(1);
        }

        c.commit();
    } catch (Exception e) {
        if (c != null) {
            try {
                c.rollback();
            } catch (SQLException se) {
                se.printStackTrace();
            }
        }
        e.printStackTrace();
    } finally {
        try {
            if (rs != null) rs.close();
            if (ps != null) ps.close();
            if (c != null) c.close();
        } catch (SQLException se) {
            se.printStackTrace();
        }
    }
    return lastInsertedId;
}
