using System;
using System.Runtime.InteropServices;

public struct LabPixel
{
    public float L;
    public float a;
    public float b;
}

public class Matrix<T>
{
    public T[] Data;
    public int Rows;
    public int Columns;

    public Matrix(int rows, int columns)
    {
        Rows = rows;
        Columns = columns;
        Data = new T[rows * columns];
    }
}

public class MatrixGenerator
{
    public static Matrix<LabPixel> GenerateRandomLabPixelMatrix(int rows, int columns)
    {
        // Allocate memory for the LabPixel array
        IntPtr ptr = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(LabPixel)) * rows * columns);
        try
        {
            LabPixel[] labPixels = new LabPixel[rows * columns];
            Random random = new Random();

            // Generate random LabPixel elements
            for (int i = 0; i < labPixels.Length; i++)
            {
                labPixels[i] = new LabPixel
                {
                    L = (float)(random.NextDouble() * 100), // L range [0, 100]
                    a = (float)(random.NextDouble() * 255 - 128), // a range [-128, 127]
                    b = (float)(random.NextDouble() * 255 - 128)  // b range [-128, 127]
                };
            }

            // Copy the LabPixel array to the allocated memory
            for (int i = 0; i < labPixels.Length; i++)
            {
                Marshal.StructureToPtr(labPixels[i], IntPtr.Add(ptr, i * Marshal.SizeOf(typeof(LabPixel))), false);
            }

            // Create the Matrix and copy the data
            Matrix<LabPixel> matrix = new Matrix<LabPixel>(rows, columns);
            Marshal.Copy(ptr, matrix.Data, 0, labPixels.Length);
            return matrix;
        }
        finally
        {
            // Free the allocated memory
            Marshal.FreeHGlobal(ptr);
        }
    }
}
