using System.Windows.Forms;

public class ListViewShuffler
{
    public void ShuffleListView(ListView listView)
    {
        Random rng = new Random();
        int n = listView.Items.Count;

        // Fisher-Yates shuffle algorithm
        for (int i = n - 1; i > 0; i--)
        {
            int j = rng.Next(0, i + 1);
            ListViewItem temp = listView.Items[i];
            listView.Items[i] = listView.Items[j];
            listView.Items[j] = temp;
        }

        // Update the dirty flag
        listView.BeginUpdate();
        listView.EndUpdate();
    }
}
