using System;

public class PlumbingGrid
{
    private object[,] grid;
    private Random random = new Random();

    public PlumbingGrid(object[,] initialGrid)
    {
        grid = initialGrid;
    }

    public void EnsureTankOutputs()
    {
        int rows = grid.GetLength(0);
        int cols = grid.GetLength(1);

        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                if (grid[i, j] is Tank tank && !tank.HasOutput)
                {
                    ConnectTank(tank, rows, cols);
                }
            }
        }
    }

    private void ConnectTank(Tank tank, int rows, int cols)
    {
        // Randomly select a direction to connect to another tank
        int direction = random.Next(4); // 0: Up, 1: Down, 2: Left, 3: Right
        int targetRow = tank.Position.Row;
        int targetCol = tank.Position.Col;

        switch (direction)
        {
            case 0: // Up
                targetRow = Math.Max(0, tank.Position.Row - 1);
                break;
            case 1: // Down
                targetRow = Math.Min(rows - 1, tank.Position.Row + 1);
                break;
            case 2: // Left
                targetCol = Math.Max(0, tank.Position.Col - 1);
                break;
            case 3: // Right
                targetCol = Math.Min(cols - 1, tank.Position.Col + 1);
                break;
        }

        if (grid[targetRow, targetCol] is Tank targetTank)
        {
            tank.ConnectTo(targetTank);
        }
    }
}

public class Tank
{
    public Position Position { get; set; }
    public bool HasOutput { get; private set; }

    public Tank(Position position)
    {
        Position = position;
