using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class Observation
{
    public int SequenceNumber { get; set; }
    public int ProducerThreadId { get; set; }
    public TimeSpan Latency { get; set; }
}

public class DemuxProducer
{
    private static int sequenceNumber = 0;
    private static readonly Random random = new Random();
    private static readonly ConcurrentQueue<Observation> observations = new ConcurrentQueue<Observation>();

    public static void Produce(int count)
    {
        Parallel.For(0, count, _ =>
        {
            int threadId = Thread.CurrentThread.ManagedThreadId;
            int seqNum = Interlocked.Increment(ref sequenceNumber);
            int delay = random.Next(100, 1000); // Random delay between 100ms and 1000ms
            Thread.Sleep(delay);

            var observation = new Observation
            {
                SequenceNumber = seqNum,
                ProducerThreadId = threadId,
                Latency = TimeSpan.FromMilliseconds(delay)
            };

            observations.Enqueue(observation);
        });
    }

    public static void DisplayObservations()
    {
        while (observations.TryDequeue(out var observation))
        {
            Console.WriteLine($"Sequence Number: {observation.SequenceNumber}, Thread ID: {observation.ProducerThreadId}, Latency: {observation.Latency.TotalMilliseconds} ms");
        }
    }
}
