using System;
using System.Collections.Generic;
using System.Xml;

public class ViewCreator
{
    public void CreateViewsFromXml(List<object> list, XmlDocument xmlDoc)
    {
        var baseType = list.GetType().GetGenericArguments()[0];
        var views = xmlDoc.SelectNodes($"/views/view[@baseType='{baseType.Name}']");

        foreach (XmlNode viewNode in views)
        {
            string viewName = viewNode.Attributes["name"].Value;
            string viewType = viewNode.Attributes["type"].Value;
            var fields = new List<string>();

            foreach (XmlNode fieldNode in viewNode.SelectNodes("fields/field"))
            {
                fields.Add(fieldNode.InnerText);
            }

            CreateView(viewName, viewType, fields);
        }

        SetDefaultViewAndRowLimit(xmlDoc);
    }

    private void CreateView(string name, string type, List<string> fields)
    {
        // Implementation for creating a view
        Console.WriteLine($"Creating view: {name}, Type: {type}, Fields: {string.Join(", ", fields)}");
    }

    private void SetDefaultViewAndRowLimit(XmlDocument xmlDoc)
    {
        // Implementation for setting default view and row limit
        var defaultViewNode = xmlDoc.SelectSingleNode("/views/defaultView");
        if (defaultViewNode != null)
