    {
        var plants = new List<Plant>();

        try
        {
            XDocument xmlDoc = XDocument.Load(filePath);
            foreach (var element in xmlDoc.Descendants("plant"))
            {
                var commonName = element.Element("common")?.Value;
                var botanicalName = element.Element("botanical")?.Value;

