public class TokenGenerator
{
    public static async Task<string> GenerateTokenAndSendRequest(string password, string domain, int port, string url)
    {
        // Hash the password using SHA1
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
            byte[] hashedBytes = sha1.ComputeHash(passwordBytes);
            string token = BitConverter.ToString(hashedBytes).Replace("-", "").ToLowerInvariant();

            // Construct the HTTP request
            using (HttpClient client = new HttpClient())
            {
                client.BaseAddress = new Uri($"http://{domain}:{port}/");
                var content = new StringContent($"{{\"token\":\"{token}\"}}", Encoding.UTF8, "application/json");

                // Send the request
                HttpResponseMessage response = await client.PostAsync(url, content);
                response.EnsureSuccessStatusCode();

                return await response.Content.ReadAsStringAsync();
            }
        }
    }
}
