public class CassandraTestCluster
{
    private Cluster _cluster;
    private ISession _session;

    public void SetUp()
    {
        // Set up the Cassandra cluster
        _cluster = Cluster.Builder()
            .AddContactPoint("127.0.0.1")
            .Build();
        _session = _cluster.Connect();

        // Create keyspace
        CreateKeyspace("test_keyspace");

        // Create table
        CreateTable("test_keyspace", "test_table");

        // Execute query with custom payload
        ExecuteQuery("INSERT INTO test_keyspace.test_table (id, name) VALUES (?, ?)", Guid.NewGuid(), "Test Name");
    }

    private void CreateKeyspace(string keyspaceName)
    {
        var createKeyspaceQuery = $"CREATE KEYSPACE IF NOT EXISTS {keyspaceName} WITH replication = {{ 'class' : 'SimpleStrategy', 'replication_factor' : 1 }};";
        _session.Execute(createKeyspaceQuery);
    }

    private void CreateTable(string keyspaceName, string tableName)
    {
        var createTableQuery = $"CREATE TABLE IF NOT EXISTS {keyspaceName}.{tableName} (id UUID PRIMARY KEY, name text);";
        _session.Execute(createTableQuery);
    }

    private void ExecuteQuery(string query, params object[] parameters)
    {
        var preparedStatement = _session.Prepare(query);
        var boundStatement = preparedStatement.Bind(parameters);
        _session.Execute(boundStatement);
    }

    public void TearDown()
    {
        _session.Dispose();
        _cluster.Dispose();
    }
}
