{
    private static List<MyModel> _models = new List<MyModel>
    {
        new MyModel { Id = 1, Name = "Model1", Description = "Description1" },
        new MyModel { Id = 2, Name = "Model2", Description = "Description2" }
    };

    [HttpGet("{id}")]
    public ActionResult<MyModel> Get(int id)
    {
        var model = _models.FirstOrDefault(m => m.Id == id);
        if (model == null)
        {
            return NotFound();
        }
        return Ok(model);
    }

    [HttpPost]
    public ActionResult<MyModel> Post([FromBody] MyModel model)
    {
        if (model == null)
        {
            return BadRequest();
        }
        model.Id = _models.Max(m => m.Id) + 1;
        _models.Add(model);
        return CreatedAtAction(nameof(Get), new { id = model.Id }, model);
    }

    [HttpPut("{id}")]
    public ActionResult<MyModel> Put(int id, [FromBody] MyModel updatedModel)
    {
        if (updatedModel == null || updatedModel.Id != id)
        {
            return BadRequest();
        }

        var model = _models.FirstOrDefault(m => m.Id == id);
        if (model == null)
        {
            return NotFound();
        }

        model.Name = updatedModel.Name;
        model.Description = updatedModel.Description;

        return Ok(model);
    }

    [HttpGet("all")]
    public ActionResult<string> GetAll()
    {
        var jsonResponse = JsonConvert.SerializeObject(_models);
        return Ok(jsonResponse);
    }
