        if (authenticationResult == null)
        {
            return null;
        }

        var realUsername = authenticationResult.Username;
        var fullname = authenticationResult.Fullname;
        var email = authenticationResult.Email;

        // Check if user exists in the database
        var user = _userRepository.GetUserByUsername(realUsername);
        if (user == null)
        {
            // Create new user in the database
            user = new User
            {
                Username = realUsername,
                Fullname = fullname,
                Email = email,
                Role = "User" // Default role
            };
            _userRepository.AddUser(user);
        }
        else
        {
            // Update user attributes if necessary
            if (!string.IsNullOrEmpty(fullname))
            {
                user.Fullname = fullname;
            }
            if (!string.IsNullOrEmpty(email))
            {
                user.Email = email;
            }
            _userRepository.UpdateUser(user);
        }

        // Log user login event
        _authenticationService.LogUserLogin(user);

        // Return user view model
        return new UserViewModel
        {
            Username = user.Username,
            Fullname = user.Fullname,
            Email = user.Email
        };
    }
}
