using System;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Xml;
using System.Xml.Linq;

public static class XmlGenerator
{
    public static XDocument GenerateXmlFromType(Type type)
    {
        var xmlRoot = new XElement(type.Name);

        var xmlizedAttributes = type.GetCustomAttributes<XmlizedClassAttribute>();
        var sqlStringIdAttributes = type.GetCustomAttributes<XmlizedSqlstringIDClassAttribute>();

        foreach (var attribute in xmlizedAttributes)
        {
            xmlRoot.Add(new XElement("XmlizedAttribute", attribute.ToString()));
        }

        foreach (var attribute in sqlStringIdAttributes)
        {
            xmlRoot.Add(new XElement("SqlStringIdAttribute", attribute.ToString()));
        }

        return new XDocument(new XDeclaration("1.0", "utf-8", "yes"), xmlRoot);
    }
}
