using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DesEncryption
{
    private static readonly byte[] Key = Encoding.UTF8.GetBytes("12345678"); // 8-byte key for DES
    private static readonly byte[] IV = Encoding.UTF8.GetBytes("12345678"); // 8-byte IV for DES

    public static string EncryptString(string plainText)
    {
        if (string.IsNullOrEmpty(plainText))
            return plainText;

        using (var des = DES.Create())
        {
            des.Key = Key;
            des.IV = IV;

            using (var memoryStream = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(memoryStream, des.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    using (var writer = new StreamWriter(cryptoStream))
                    {
                        writer.Write(plainText);
                    }
                    return Convert.ToBase64String(memoryStream.ToArray());
                }
            }
        }
    }
}
