public int addVillain(String name, int evilnessFactor, Connection connection, Transaction transaction) {
    int lastInsertedId = -1;
    String sql = "INSERT INTO Villains(name, evilnessFactor) VALUES(?, ?);";

    try {
        PreparedStatement ps = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, name);
        ps.setInt(2, evilnessFactor);

        // Start transaction
        transaction.begin();

        ps.executeUpdate();

        // Get the last inserted ID
        ResultSet generatedKeys = ps.getGeneratedKeys();
        if (generatedKeys.next()) {
            lastInsertedId = generatedKeys.getInt(1);
        }

        // Commit transaction
        transaction.commit();
        ps.close();

        System.out.println("Villain added successfully with ID: " + lastInsertedId);
    } catch (Exception e) {
        try {
            // Rollback transaction in case of error
            transaction.rollback();
        } catch (SQLException rollbackEx) {
            rollbackEx.printStackTrace();
        }
        e.printStackTrace();
    }

    return lastInsertedId;
}
