using System;
using System.IO;
using System.Xml;
using System.Xml.Schema;

public class XmlValidator
{
    public static bool ValidateXml(string xmlContent, string schemaContent)
    {
        try
        {
            XmlSchemaSet schemaSet = new XmlSchemaSet();
            using (StringReader schemaReader = new StringReader(schemaContent))
            {
                using (XmlReader schemaXmlReader = XmlReader.Create(schemaReader))
                {
                    schemaSet.Add(null, XmlReader.Create(schemaXmlReader));
                }
            }

            XmlReaderSettings settings = new XmlReaderSettings
            {
                ValidationType = ValidationType.Schema,
                Schemas = schemaSet
            };

            settings.ValidationEventHandler += (sender, e) =>
            {
                throw new XmlSchemaValidationException(e.Message);
            };

            using (StringReader xmlReader = new StringReader(xmlContent))
            {
                using (XmlReader reader = XmlReader.Create(xmlReader, settings))
                {
                    if (reader.Read())
                    {
                        if (reader.HasAttributes)
                        {
                            reader.MoveToFirstAttribute();
                            if (string.IsNullOrEmpty(reader.Prefix))
                            {
                                return true; // Valid XML and attribute prefix is empty
                            }
                        }
                    }
                }
            }
        }
        catch (XmlSchemaValidationException ex)
        {
            Console.WriteLine($"Validation error: {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }

        return false; // Invalid XML or attribute prefix is not empty
    }
}
