using System.Diagnostics;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 2)
        {
            Console.WriteLine("Usage: <executable> <arguments> [timeout]");
            return;
        }

        string executable = args[0];
        string arguments = args[1];
        int timeout = args.Length > 2 ? int.Parse(args[2]) : 10000; // Default timeout 10 seconds

        Process process = new Process();
        process.StartInfo.FileName = executable;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        try
        {
            process.Start();
            Console.WriteLine($"Started process: {executable} {arguments}");

            if (!process.WaitForExit(timeout))
            {
                Console.WriteLine($"Process exceeded timeout of {timeout} ms. Terminating...");
                process.Kill();
                process.WaitForExit();
            }

            Console.WriteLine($"Process exited with code: {process.ExitCode}");
            string output = process.StandardOutput.ReadToEnd();
            string error = process.StandardError.ReadToEnd();

            if (!string.IsNullOrEmpty(output))
            {
                Console.WriteLine("Output:");
                Console.WriteLine(output);
            }

            if (!string.IsNullOrEmpty(error))
            {
                Console.WriteLine("Error:");
                Console.WriteLine(error);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
        finally
        {
            if (!process.HasExited)
            {
                process.Kill();
            }
            process.Dispose();
        }
    }
}
