using System.Collections.Generic;
using System.IO;
using System.Xml;

public class ConfigLoader
{
    public Dictionary<string, string> LoadSettings(string filePath)
    {
        var settings = new Dictionary<string, string>();

        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.Load(filePath);

            XmlNode configurationNode = xmlDoc.SelectSingleNode("/configuration");
            if (configurationNode != null)
            {
                foreach (XmlNode settingNode in configurationNode.ChildNodes)
                {
                    if (settingNode.NodeType == XmlNodeType.Element)
                    {
                        string key = settingNode.Name;
                        string value = settingNode.InnerText;
                        settings[key] = value;
                    }
                }
            }
