public class Resource
{
    public byte[] Hash { get; set; }
    public byte[] Data { get; set; }
    public string MimeType { get; set; }

    public Resource(byte[] hash, byte[] data, string mimeType)
    {
        Hash = hash;
        Data = data;
        MimeType = mimeType;
    }
}

public class ResourceProcessor
{
    public List<Resource> ComputeResourceHashes(List<(byte[] Data, string MimeType)> resources)
    {
        var resourceList = new List<Resource>();

        using (var md5 = MD5.Create())
        {
            foreach (var resource in resources)
            {
                var hash = md5.ComputeHash(resource.Data);
                var resourceObject = new Resource(hash, resource.Data, resource.MimeType);
                resourceList.Add(resourceObject);
            }
        }

        return resourceList;
    }
}
