public class FileCopier
{
    public void CopyFiles(string sourceDirectory, string targetDirectory, string[] includeExtensions, string[] excludeExtensions)
    {
        if (!Directory.Exists(sourceDirectory))
        {
            throw new DirectoryNotFoundException($"Source directory does not exist: {sourceDirectory}");
        }

        // Create target directory if it doesn't exist
        Directory.CreateDirectory(targetDirectory);

        foreach (var filePath in Directory.GetFiles(sourceDirectory, "*", SearchOption.AllDirectories))
        {
            string fileExtension = Path.GetExtension(filePath).ToLower();

            // Check if the file should be included or excluded
            bool isIncluded = includeExtensions.Length == 0 || Array.Exists(includeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase));
            bool isExcluded = Array.Exists(excludeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase));

            if (isIncluded && !isExcluded)
            {
                string relativePath = Path.GetRelativePath(sourceDirectory, filePath);
                string targetFilePath = Path.Combine(targetDirectory, relativePath);

                // Create directory for the target file
                string targetFileDirectory = Path.GetDirectoryName(targetFilePath);
                if (targetFileDirectory != null)
                {
                    Directory.CreateDirectory(targetFileDirectory);
                }

                // Copy the file
                File.Copy(filePath, targetFilePath, true);
            }
        }
    }
}
