using System;
using System.Security.Cryptography;
using System.Text;

public class DesDecryptor
{
    private static readonly byte[] Key = Encoding.ASCII.GetBytes("12345678"); // Fixed key (must be 8 bytes for DES)
    private static readonly byte[] IV = Encoding.ASCII.GetBytes("12345678"); // Initialization vector (must be 8 bytes for DES)

    public static string Decrypt(string hexInput)
    {
        try
        {
            // Convert hex string to byte array
            byte[] encryptedBytes = HexStringToByteArray(hexInput);

            using (var des = DES.Create())
            {
                des.Key = Key;
                des.IV = IV;

                using (var decryptor = des.CreateDecryptor(des.Key, des.IV))
                {
                    byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                    return Encoding.ASCII.GetString(decryptedBytes);
                }
            }
        }
        catch (FormatException)
        {
            return "Invalid hexadecimal string.";
        }
        catch (CryptographicException)
        {
            return "Decryption failed. Invalid key or data.";
        }
    }

    private static byte[] HexStringToByteArray(string hex)
    {
        if (hex.Length % 2 != 0)
            throw new FormatException("Invalid hexadecimal string.");

        byte[] bytes = new byte[hex.Length / 2];
        for (int i = 0; i < hex.Length; i += 2)
        {
            bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
        }
        return bytes;
    }
}
