                {
                    artistAlbumCount[artistName] += albumCount;
                }
                else
                {
                    artistAlbumCount[artistName] = albumCount;
                }
            }
        }

        // Output the results
        foreach (var entry in artistAlbumCount)
        {
            Console.WriteLine($"Artist: {entry.Key}, Album Count: {entry.Value}");
        }
    }
}
