using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESEncryption
{
    public static string EncryptString(string plainText, Guid key1, Guid key2)
    {
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            // Combine the two Guids to create a key
            byte[] key = CombineGuids(key1, key2);
            tdes.Key = key;
            tdes.Mode = CipherMode.ECB; // Using ECB mode for simplicity
            tdes.Padding = PaddingMode.PKCS7;

            ICryptoTransform encryptor = tdes.CreateEncryptor(tdes.Key, null);

            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    byte[] input = Encoding.UTF8.GetBytes(plainText);
                    cs.Write(input, 0, input.Length);
                    cs.FlushFinalBlock();
                    return Convert.ToBase64String(ms.ToArray());
                }
            }
        }
    }

    private static byte[] CombineGuids(Guid key1, Guid key2)
    {
        byte[] combined = new byte[24]; // 24 bytes for Triple DES
        Buffer.BlockCopy(key1.ToByteArray(), 0, combined, 0, 16);
        Buffer.BlockCopy(key2.ToByteArray(), 0, combined, 16, 8);
        return combined;
    }
}
