                return await client.GetStringAsync(url);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error downloading content: {ex.Message}");
                return null;
            }
        }
    }

    static void OpenContentInNewProcess(string content)
    {
        string tempFilePath = System.IO.Path.GetTempFileName() + ".html";
        System.IO.File.WriteAllText(tempFilePath, content);

        Process.Start(new ProcessStartInfo
        {
            FileName = tempFilePath,
            UseShellExecute = true
        });
    }
