using System;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigUpdater
{
    public int RemoveSection(string filePath, string sectionXPath)
    {
        if (string.IsNullOrEmpty(filePath) || string.IsNullOrEmpty(sectionXPath))
            throw new ArgumentException("File path and section XPath cannot be null or empty.");

        XDocument config = XDocument.Load(filePath);
        var sectionsToRemove = config.XPathSelectElements(sectionXPath);

        int removedCount = sectionsToRemove.Count;

        foreach (var section in sectionsToRemove)
        {
            section.Remove();
        }

        config.Save(filePath);
        return removedCount;
    }
}
