using System;
using System.Xml.Linq;
using System.Xml.XPath;

public class XmlConfigUpdater
{
    public void AddIndexProviderSection(string xmlFilePath, string existingSectionXPath, string newIndexProviderSection)
    {
        XDocument xDocument = XDocument.Load(xmlFilePath);

        var existingSections = xDocument.XPathSelectElements(existingSectionXPath);
        if (existingSections != null)
        {
            foreach (var existingSection in existingSections)
            {
                // Create the new index provider section
                XElement newSection = XElement.Parse(newIndexProviderSection);

                // Insert the new section after the existing section
                existingSection.AddAfterSelf(newSection);
            }
        }

        xDocument.Save(xmlFilePath);
    }
}
