public class XmlUpdater
{
    public string UpdateXmlFile(string filePath, string xpathToRemove, string xpathAfterInsert)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.Load(filePath);

        XmlNode nodeToRemove = xmlDoc.SelectSingleNode(xpathToRemove);
        if (nodeToRemove != null)
        {
            XmlNode parentNode = nodeToRemove.ParentNode;
            parentNode.RemoveChild(nodeToRemove);
        }

        XmlNode insertAfterNode = xmlDoc.SelectSingleNode(xpathAfterInsert);
