using System;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigurationUpdater
{
    public XDocument UpdateConfigurationFile(string configFilePath, string newSearchProviderXml, string xpathExpression)
    {
        // Load the existing configuration file
        XDocument configDocument = XDocument.Load(configFilePath);

        // Parse the new search provider XML fragment
        XElement newSearchProvider = XElement.Parse(newSearchProviderXml);

        // Find the target element using the provided XPath expression
        var targetElement = configDocument.XPathSelectElement(xpathExpression);
        if (targetElement != null)
        {
            // Insert the new search provider section after the target element
            targetElement.AddAfterSelf(newSearchProvider);
        }
        else
        {
            throw new InvalidOperationException("The specified XPath expression did not match any elements.");
        }

        // Return the updated configuration document
        return configDocument;
    }
}
