using System.Collections.Generic;
using System.Security.Cryptography;

public class CipherProperties
{
    public string Algorithm { get; set; }
    public int KeySize { get; set; }
    public int KeyLength { get; set; }
    public int IVLength { get; set; }
    public int BlockSize { get; set; }
    public int FeedbackSize { get; set; }
    public CipherMode Mode { get; set; }
    public PaddingMode Padding { get; set; }
    public List<int> LegalBlockSizes { get; set; }
    public List<int> LegalKeySizes { get; set; }
}

public class CryptographyHelper
{
    public static CipherProperties GetCipherProperties(string algorithmName)
    {
        using (SymmetricAlgorithm algorithm = SymmetricAlgorithm.Create(algorithmName))
        {
            if (algorithm == null)
            {
                throw new ArgumentException("Invalid algorithm name.");
            }

            return new CipherProperties
            {
                Algorithm = algorithm.AlgorithmName,
                KeySize = algorithm.KeySize,
                KeyLength = algorithm.KeySize / 8,
                IVLength = algorithm.IV.Length,
                BlockSize = algorithm.BlockSize,
                FeedbackSize = algorithm.FeedbackSize,
                Mode = algorithm.Mode,
                Padding = algorithm.Padding,
                LegalBlockSizes = GetLegalSizes(algorithm.LegalBlockSizes),
                LegalKeySizes = GetLegalSizes(algorithm.LegalKeySizes)
            };
        }
    }

    private static List<int> GetLegalSizes(KeySizes[] sizes)
    {
        var legalSizes = new List<int>();
        foreach (var size in sizes)
        {
            for (int i = size.MinSize; i <= size.MaxSize; i += size.SkipSize)
            {
                legalSizes.Add(i);
            }
        }
        return legalSizes;
    }
}
