    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified file does not exist.", filePath);
        }

        using (FileStream fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            T lastObject = default(T);
            long position = fileStream.Length;

            while (position > 0)
            {
                fileStream.Seek(position - sizeof(int), SeekOrigin.Begin);
                int objectSize = (int)formatter.Deserialize(fileStream);
                position -= objectSize + sizeof(int);

                if (position >= 0)
                {
                    fileStream.Seek(position, SeekOrigin.Begin);
                    lastObject = (T)formatter.Deserialize(fileStream);
                    break;
                }
            }

            return lastObject;
        }
    }
}
