public class ConfigManager
{
    private string configFilePath;

    public ConfigManager(string directory)
    {
        configFilePath = Path.Combine(directory, "config.xml");
    }

    public void LoadConfig()
    {
        if (!File.Exists(configFilePath))
        {
            throw new FileNotFoundException("Configuration file not found.", configFilePath);
        }

        XElement config = XElement.Load(configFilePath);
        ParseSettings(config);
    }

    private void ParseSettings(XElement config)
    {
        // Example of parsing settings
        foreach (var setting in config.Elements("Setting"))
        {
            string key = setting.Attribute("Key")?.Value;
            string value = setting.Value;
            Console.WriteLine($"Key: {key}, Value: {value}");
        }
    }

    public void UpdateSetting(string key, string newValue)
    {
        XElement config = XElement.Load(configFilePath);
        var setting = config.Elements("Setting").FirstOrDefault(s => s.Attribute("Key")?.Value == key);

        if (setting != null)
        {
            setting.Value = newValue;
            SaveConfig(config);
        }
        else
        {
            throw new ArgumentException($"Setting with key '{key}' not found.");
        }
    }

    private void SaveConfig(XElement config)
    {
        config.Save(configFilePath);
    }
}
