public static class XmlPropertyPopulator
{
    public static void PopulateProperty(XmlDocument xmlDoc, PropertyInfo propertyInfo, XmlNode xmlNode)
    {
        if (propertyInfo == null || xmlNode == null)
            throw new ArgumentNullException("PropertyInfo or XmlNode cannot be null.");

        object propertyValue = Activator.CreateInstance(propertyInfo.PropertyType);
        if (typeof(IExportToXmlable).IsAssignableFrom(propertyInfo.PropertyType))
        {
            IExportToXmlable exportable = (IExportToXmlable)propertyValue;
            exportable.ImportFromXml(xmlNode.OuterXml);
            propertyInfo.SetValue(propertyInfo.DeclaringType, exportable);
        }
        else
        {
            if (xmlNode.InnerText != null)
            {
                object value = Convert.ChangeType(xmlNode.InnerText, propertyInfo.PropertyType);
                propertyInfo.SetValue(propertyInfo.DeclaringType, value);
            }
        }
    }
}

public interface IExportToXmlable
{
    void ImportFromXml(string xml);
}
