using System;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionTest
{
    public void TestEncryptionDecryption(string algorithm, byte[] key, byte[] plaintext)
    {
        // Validate key size
        using (var cipher = SymmetricAlgorithm.Create(algorithm))
        {
            if (cipher == null)
                throw new ArgumentException("Invalid algorithm specified.");

            if (key.Length * 8 != cipher.KeySize)
                throw new ArgumentException("Key size is incorrect.");

            cipher.Key = key;
            cipher.Mode = CipherMode.ECB;
            cipher.Padding = PaddingMode.Zeros;

            // Encrypt the plaintext
            byte[] encrypted;
            using (var encryptor = cipher.CreateEncryptor())
            {
                encrypted = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
            }

            // Decrypt the ciphertext
            byte[] decrypted;
            using (var decryptor = cipher.CreateDecryptor())
            {
                decrypted = decryptor.TransformFinalBlock(encrypted, 0, encrypted.Length);
            }

            // Check if decrypted text matches the original plaintext
            if (!AreEqual(decrypted, plaintext))
                throw new Exception("Decryption did not yield the original plaintext.");

            // Check that the encrypted message is not the same as the original plaintext
            if (AreEqual(encrypted, plaintext))
                throw new Exception("Encrypted message should not be the same as the original plaintext.");
        }
    }

    private bool AreEqual(byte[] a, byte[] b)
    {
        if (a.Length != b.Length)
            return false;

        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i])
                return false;
        }
        return true;
    }
}
