        // Ensure the last character is from the restricted set
        int endIndex = random.nextInt(END_CHARACTERS.length());
        password.append(END_CHARACTERS.charAt(endIndex));

        return password.toString();
    }

    public static void main(String[] args) {
        int passwordLength = 10; // Example length
        String password = generatePassword(passwordLength);
        System.out.println("Generated Password: " + password);
    }
}
