import java.io.IOException;
import java.nio.file.Paths;

public class DocumentComparator {

    public static void compareNumericFields(String indexPath, int docId1, int docId2, String fieldName) throws IOException {
        Directory directory = FSDirectory.open(Paths.get(indexPath));
        try (IndexReader reader = DirectoryReader.open(directory)) {
            // Load fields from both documents
            Terms terms1 = reader.getTermVector(docId1, fieldName);
            Terms terms2 = reader.getTermVector(docId2, fieldName);

            // Check if both fields are present
            if (terms1 == null || terms2 == null) {
                throw new IllegalArgumentException("One of the documents does not contain the specified field.");
            }

            // Compare number of values
            MatcherAssert.assertThat("Number of values in fields should be the same", 
                terms1.size(), 
                org.hamcrest.Matchers.is(terms2.size()));

            // Compare values
            TermsEnum termsEnum1 = terms1.iterator();
            TermsEnum termsEnum2 = terms2.iterator();

            while (termsEnum1.next() != null && termsEnum2.next() != null) {
                BytesRef value1 = termsEnum1.term();
                BytesRef value2 = termsEnum2.term();
                MatcherAssert.assertThat("Values should be equal", 
                    value1.utf8ToString(), 
                    org.hamcrest.Matchers.is(value2.utf8ToString()));
            }
        }
    }
}
