import java.util.Random;
import java.util.logging.Logger;

public class NodeOperations {
    private static final Logger logger = Logger.getLogger(NodeOperations.class.getName());
    private int heartbeatCount = 0;
    private int clearCount = 0;
    private final Random random = new Random();

    public void performRandomOperations(int expectedHeartbeats, int expectedClears) {
        for (int i = 0; i < 10; i++) { // Perform 10 random operations
            if (random.nextBoolean()) {
                reportHeartbeat();
            } else {
                clearPrimary();
            }
        }
        logOperationCounts(expectedHeartbeats, expectedClears);
    }

    private void reportHeartbeat() {
        heartbeatCount++;
        logger.info("Heartbeat reported. Total heartbeats: " + heartbeatCount);
    }

    private void clearPrimary() {
        clearCount++;
        logger.info("Primary cleared. Total clears: " + clearCount);
    }

    private void logOperationCounts(int expectedHeartbeats, int expectedClears) {
        logger.info("Expected Heartbeats: " + expectedHeartbeats + ", Actual Heartbeats: " + heartbeatCount);
        logger.info("Expected Clears: " + expectedClears + ", Actual Clears: " + clearCount);
    }
}
