import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.FileSystem;
import java.nio.file.Path;
import java.util.Random;

public class RandomBinaryFileGenerator {

    public static File generateRandomBinaryFile(FileSystem fileSystem, String folder, String fileName, int length) throws IOException {
        File file = fileSystem.getPath(folder, fileName).toFile();
        file.deleteOnExit();

        try (FileOutputStream out = new FileOutputStream(file)) {
            Random random = new Random();
            byte[] buffer = new byte[1024]; // Buffer size for writing

            int bytesWritten = 0;
            while (bytesWritten < length) {
                int bytesToWrite = random.nextBoolean() ? 1 : Math.min(random.nextInt(buffer.length) + 1, length - bytesWritten);
                random.nextBytes(buffer);
                out.write(buffer, 0, bytesToWrite);
                bytesWritten += bytesToWrite;
            }
        }

        return file;
    }
}
