import javax.crypto.Cipher;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.Base64;

public class AESCryptography {

    private static final String ALGORITHM = "AES";
    private static final String CIPHER_TRANSFORMATION = "AES/CBC/NoPadding";
    private static final int KEY_LENGTH = 128; // AES key length
    private static final int ITERATIONS = 65536; // PBKDF2 iterations
    private static final int SALT_LENGTH = 16; // Salt length
    private static final int BLOCK_SIZE = 16; // AES block size

    public static byte[] generateKey(String password, byte[] salt) throws Exception {
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt, ITERATIONS, KEY_LENGTH);
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
        byte[] key = factory.generateSecret(spec).getEncoded();
        return key;
    }

    public static byte[] encrypt(byte[] data, byte[] key, byte[] iv) throws Exception {
        Cipher cipher = Cipher.getInstance(CIPHER_TRANSFORMATION);
        SecretKeySpec secretKey = new SecretKeySpec(key, ALGORITHM);
        IvParameterSpec ivParams = new IvParameterSpec(iv);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParams);

        // Padding data to be a multiple of BLOCK_SIZE
        int paddedLength = (data.length + BLOCK_SIZE - 1) / BLOCK_SIZE * BLOCK_SIZE;
        byte[] paddedData = new byte[paddedLength];
        System.arraycopy(data, 0, paddedData, 0, data.length);

        return cipher.doFinal(paddedData);
    }

    public static byte[] decrypt(byte[] encryptedData, byte[] key, byte[] iv) throws Exception {
        Cipher cipher = Cipher.getInstance(CIPHER_TRANSFORMATION);
        SecretKeySpec secretKey = new SecretKeySpec(key, ALGORITHM);
        IvParameterSpec ivParams = new IvParameterSpec(iv);
        cipher.init(Cipher.DECRYPT_MODE, secretKey, ivParams);

        byte[] decryptedData = cipher.doFinal(encryptedData);

        // Remove padding
        int unpaddedLength = decryptedData.length;
        while (unpaddedLength > 0 && decryptedData[unpaddedLength - 1] == 0) {
            unpaddedLength--;
        }

        byte[] result = new byte[unpaddedLength];
        System.arraycopy(decryptedData, 0, result, 0, unpaddedLength);
        return result;
    }

    public static byte[] generateSalt() {
        byte[] salt = new byte[SALT_LENGTH];
        new SecureRandom().nextBytes(salt);
        return salt;
    }

    public static void main(String[] args) throws Exception {
        String password = "mySecurePassword";
        byte[] salt = generateSalt();
        byte[] key = generateKey(password, salt);
        byte[] iv = new byte[BLOCK_SIZE]; // Initialization vector
        new SecureRandom().nextBytes(iv);

        String originalData = "Hello, World!";
        byte[] encryptedData = encrypt(originalData.getBytes(), key, iv);
        byte[] decryptedData = decrypt(encryptedData, key, iv);

        System.out.println("Original: " + originalData);
        System.out.println("Encrypted: " + Base64.getEncoder().encodeToString(encryptedData));
        System.out.println("Decrypted: " + new String(decryptedData));
    }
}
