import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class RandomObjectReplacer {

    private static final Random random = new Random();

    public static List<Object> replaceRandomObjects(List<Object> originalList) {
        int size = originalList.size();
        double mean = 0.0;
        double stdDev = 0.2 * size;
        List<Object> newList = new ArrayList<>(originalList);
        List<Object> discreteValues = new ArrayList<>();

        for (int i = 0; i < size; i++) {
            if (random.nextBoolean()) { // Randomly decide to replace the object
                double newValue = mean + random.nextGaussian() * stdDev;
                newList.set(i, newValue);
                discreteValues.add(newValue);
            }
        }

        // Optionally, you can return the discrete values or handle them as needed
        return newList;
    }

    public static List<Object> getDiscreteValues(List<Object> originalList, int iterations) {
        List<Object> allDiscreteValues = new ArrayList<>();
        for (int i = 0; i < iterations; i++) {
            List<Object> modifiedList = replaceRandomObjects(originalList);
            allDiscreteValues.addAll(modifiedList);
        }
        return allDiscreteValues;
    }
}
