import java.util.concurrent.atomic.AtomicInteger;
import java.util.ArrayList;
import java.util.List;

class Graph {
    private final int vertices;
    private final List<List<Integer>> adjacencyList;

    public Graph(int vertices) {
        this.vertices = vertices;
        adjacencyList = new ArrayList<>(vertices);
        for (int i = 0; i < vertices; i++) {
            adjacencyList.add(new ArrayList<>());
        }
    }

    public void addEdge(int source, int destination) {
        adjacencyList.get(source).add(destination);
        adjacencyList.get(destination).add(source); // For undirected graph
    }

    public List<Integer> getAdjacencyList(int vertex) {
        return adjacencyList.get(vertex);
    }

    public int getVertices() {
        return vertices;
    }
}

class GraphTraversalThread extends Thread {
    private final Graph graph;
    private final int startVertex;
    private final AtomicInteger completedThreads;

    public GraphTraversalThread(Graph graph, int startVertex, AtomicInteger completedThreads) {
        this.graph = graph;
        this.startVertex = startVertex;
        this.completedThreads = completedThreads;
    }

    @Override
    public void run() {
        boolean[] visited = new boolean[graph.getVertices()];
        traverse(startVertex, visited);
        completedThreads.incrementAndGet();
    }

    private void traverse(int vertex, boolean[] visited) {
        visited[vertex] = true;
        System.out.println("Visited vertex: " + vertex);
        for (int neighbor : graph.getAdjacencyList(vertex)) {
            if (!visited[neighbor]) {
                traverse(neighbor, visited);
            }
        }
    }
}

public class ConcurrentGraphTraversal {
    public static void main(String[] args) throws InterruptedException {
        int vertices = 5;
        Graph graph = new Graph(vertices);
        graph.addEdge(0, 1);
        graph.addEdge(0, 2);
        graph.addEdge(1, 3);
        graph.addEdge(1, 4);

        AtomicInteger completedThreads = new AtomicInteger(0);
        Thread[] threads = new Thread[vertices];

        for (int i = 0; i < vertices; i++) {
            threads[i] = new GraphTraversalThread(graph, i, completedThreads);
            threads[i].start();
        }

        for (Thread thread : threads) {
            thread.join();
        }

        System.out.println("Number of vertices: " + graph.getVertices());
        System.out.println("Number of edges: " + (graph.getVertices() - 1)); // Assuming a tree structure
        System.out.println("Completed threads: " + completedThreads.get());
    }
}
