public class ProcessReturnInfo {
    private final int exitCode;
    private final String stdout;
    private final String stderr;

    public ProcessReturnInfo(int exitCode, String stdout, String stderr) {
        this.exitCode = exitCode;
        this.stdout = stdout;
        this.stderr = stderr;
    }

    public int getExitCode() {
        return exitCode;
    }

    public String getStdout() {
        return stdout;
    }

    public String getStderr() {
        return stderr;
    }
}

public ProcessReturnInfo executeCommand(String command) {
    StringBuilder outputBuilder = new StringBuilder();
    StringBuilder errorBuilder = new StringBuilder();
    Process process = null;

    try {
        process = Runtime.getRuntime().exec(command);

        // Capture stdout
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                outputBuilder.append(line).append("\n");
            }
        }

        // Capture stderr
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                errorBuilder.append(line).append("\n");
            }
        }

        // Wait for the process to complete
        int exitCode = process.waitFor();
        return new ProcessReturnInfo(exitCode, outputBuilder.toString().trim(), errorBuilder.toString().trim());

    } catch (IOException | InterruptedException e) {
        errorBuilder.append(e.getMessage());
        return new ProcessReturnInfo(-1, outputBuilder.toString().trim(), errorBuilder.toString().trim());
    } finally {
        if (process != null) {
            process.destroy();
        }
    }
}
