import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class WeightedItemNormalizer {

    public static <T> Map<T, Double> normalizeWeights(List<T> items, Function<T, Double> weightFunction) {
        Map<T, Double> normalizedWeights = new HashMap<>();
        double totalWeight = 0.0;

        // Calculate total weight
        for (T item : items) {
            double weight = weightFunction.apply(item);
            totalWeight += weight;
            normalizedWeights.put(item, weight);
        }

        // Normalize weights
        if (totalWeight > 0) {
            for (Map.Entry<T, Double> entry : normalizedWeights.entrySet()) {
                entry.setValue(entry.getValue() / totalWeight);
            }
        }

        return normalizedWeights;
    }
}
