public class RemoteConnection {

    private SocketChannel socketChannel;
    private String remoteAddress;
    private int remotePort;

    public RemoteConnection(String remoteAddress, int remotePort) {
        this.remoteAddress = remoteAddress;
        this.remotePort = remotePort;
    }

    public void connect() {
        try {
            socketChannel = SocketChannel.open();
            socketChannel.configureBlocking(false);
            socketChannel.connect(new InetSocketAddress(remoteAddress, remotePort));

            while (!socketChannel.finishConnect()) {
                // Wait for the connection to finish
            }

            System.out.println("Connected to " + remoteAddress + ":" + remotePort);
            handleConnectionStateChange(true);
        } catch (IOException e) {
            System.err.println("Connection to " + remoteAddress + ":" + remotePort + " failed: " + e.getMessage());
            handleConnectionStateChange(false);
        }
    }

    private void handleConnectionStateChange(boolean isConnected) {
        if (isConnected) {
            // Handle successful connection state
            System.out.println("Connection established successfully.");
        } else {
            // Handle failed connection state
            System.out.println("Connection failed.");
        }
    }

    public void disconnect() {
        try {
            if (socketChannel != null && socketChannel.isOpen()) {
                socketChannel.close();
                System.out.println("Disconnected from " + remoteAddress + ":" + remotePort);
                handleConnectionStateChange(false);
            }
        } catch (IOException e) {
            System.err.println("Error while disconnecting: " + e.getMessage());
        }
    }
}
