import java.util.List;
import java.util.Collections;

public class GeoPointComparator {

    public void compareGeoPoints(List<Double> setA, List<Double> setB, double tolerance) throws Exception {
        if (setA.size() != setB.size()) {
            throw new Exception("The number of values in the two sets are not equal.");
        }

        if (setA.size() > 0) {
            List<Double> sortedA = List.copyOf(setA);
            List<Double> sortedB = List.copyOf(setB);
            Collections.sort(sortedA);
            Collections.sort(sortedB);

            for (int i = 0; i < sortedA.size(); i++) {
                if (Math.abs(sortedA.get(i) - sortedB.get(i)) > tolerance) {
                    throw new Exception("Values at index " + i + " are not equal within the specified tolerance.");
                }
            }
        }
    }
}
