                return createToken(username, password);
            case "verify":
                return verifyToken(tokenId);
            case "renew":
                return renewToken(tokenId);
            case "cancel":
                return cancelToken(tokenId);
            default:
                throw new IllegalArgumentException("Invalid action: " + action);
        }
    }

