import java.util.ArrayList;
import java.util.List;
import java.util.Random;

class LocationTime {
    private long timestamp;
    private double latitude;
    private double longitude;

    public LocationTime(long timestamp, double latitude, double longitude) {
        this.timestamp = timestamp;
        this.latitude = latitude;
        this.longitude = longitude;
    }

    public long getTimestamp() {
        return timestamp;
    }
}

class SensorData {
    private long timestamp;
    private String type;
    private double[] data;

    public SensorData(long timestamp, String type, double[] data) {
        this.timestamp = timestamp;
        this.type = type;
        this.data = data;
    }
}

public class SensorDataGenerator {
    public static List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<double[]> stdDevs, double stepsPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        Random random = new Random();

        for (int i = 0; i < locationTimes.size(); i++) {
            LocationTime locationTime = locationTimes.get(i);
            double[] stdDev = stdDevs.get(i);
            double[] accelerometerReading = new double[3];

            for (int j = 0; j < accelerometerReading.length; j++) {
                accelerometerReading[j] = random.nextGaussian() * stdDev[j];
            }

            sensorDataList.add(new SensorData(locationTime.getTimestamp(), "ACC", accelerometerReading));
        }

        return sensorDataList;
    }
}
