import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class WeatherService {

    private static final String API_KEY = "your_api_key"; // Replace with your OpenWeatherMap API key
    private static final String API_URL = "http://api.openweathermap.org/data/2.5/weather?q=";

    public String getWeatherData(String location) {
        StringBuilder result = new StringBuilder();
        HttpURLConnection connection = null;

        try {
            URL url = new URL(API_URL + location + "&appid=" + API_KEY);
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String inputLine;

                while ((inputLine = in.readLine()) != null) {
                    result.append(inputLine);
                }
                in.close();
            } else {
                throw new Exception("Failed to get weather data: " + responseCode);
            }
        } catch (Exception e) {
            e.printStackTrace();
            return "Error retrieving weather data: " + e.getMessage();
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }

        return result.toString();
    }
}
