    public static String downloadFile(String fileURL, String saveDir) {
        HttpURLConnection httpConn = null;
        InputStream inputStream = null;
        FileOutputStream outputStream = null;
        String fileName = "";

        try {
            URL url = new URL(fileURL);
            httpConn = (HttpURLConnection) url.openConnection();
            httpConn.setConnectTimeout(5000); // Set connect timeout
            httpConn.setReadTimeout(5000); // Set read timeout
            httpConn.setRequestMethod("GET");
            httpConn.setRequestProperty("Accept-Encoding", "identity");
            httpConn.connect();

            // Check for successful response code
            int responseCode = httpConn.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                return null;
            }

            // Get file name from response header or URL
            String disposition = httpConn.getHeaderField("Content-Disposition");
            if (disposition != null) {
                String[] parts = disposition.split(";");
                for (String part : parts) {
                    if (part.trim().startsWith("filename")) {
                        fileName = part.substring(part.indexOf('=') + 2, part.length() - 1);
                    }
                }
            }
            if (fileName.isEmpty()) {
                fileName = fileURL.substring(fileURL.lastIndexOf("/") + 1);
            }

            // Open input stream and output stream
            inputStream = httpConn.getInputStream();
            String saveFilePath = saveDir + File.separator + fileName;
            outputStream = new FileOutputStream(saveFilePath);

            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }

            return new File(saveFilePath).toURI().toString(); // Return file URI

        } catch (Exception e) {
            e.printStackTrace();
            return null;
        } finally {
            // Close streams
            try {
                if (outputStream != null) outputStream.close();
                if (inputStream != null) inputStream.close();
                if (httpConn != null) httpConn.disconnect();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
