import javax.swing.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class ObjectLoader {

    private JButton loadButton;
    private JLabel propertyLabel;

    public ObjectLoader() {
        JFrame frame = new JFrame("Object Loader");
        loadButton = new JButton("Load Object");
        propertyLabel = new JLabel("Object Properties will appear here");

        loadButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                loadObject();
            }
        });

        frame.setLayout(new java.awt.FlowLayout());
        frame.add(loadButton);
        frame.add(propertyLabel);
        frame.setSize(300, 200);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);
    }

    private void loadObject() {
        JFileChooser fileChooser = new JFileChooser();
        int returnValue = fileChooser.showOpenDialog(null);
        if (returnValue == JFileChooser.APPROVE_OPTION) {
            FileInputStream fileInputStream = null;
            ObjectInputStream objectInputStream = null;
            try {
                fileInputStream = new FileInputStream(fileChooser.getSelectedFile());
                objectInputStream = new ObjectInputStream(fileInputStream);
                MyObject myObject = (MyObject) objectInputStream.readObject();
                updateGUI(myObject);
            } catch (IOException | ClassNotFoundException ex) {
                ex.printStackTrace();
                propertyLabel.setText("Error loading object: " + ex.getMessage());
            } finally {
                try {
                    if (objectInputStream != null) objectInputStream.close();
                    if (fileInputStream != null) fileInputStream.close();
                } catch (IOException ex) {
                    ex.printStackTrace();
                }
            }
        }
    }

    private void updateGUI(MyObject myObject) {
        propertyLabel.setText("Loaded Object: " + myObject.toString());
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(ObjectLoader::new);
    }
}

class MyObject implements java.io.Serializable {
    private String name;
    private int value;

    // Constructor, getters, setters, and toString() method
    public MyObject(String name, int value) {
        this.name = name;
        this.value = value;
    }

    @Override
    public String toString() {
        return "Name: " + name + ", Value: " + value;
    }
}
