public class FileDataFilter {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory"; // Specify the directory path
        String targetDataType = "desiredDataType"; // Specify the type of data to filter
        List<String> filteredFiles = new ArrayList<>();
        Hashtable<String, Object> dataStore = new Hashtable<>();

        File dir = new File(directoryPath);
        if (dir.isDirectory()) {
            File[] files = dir.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.isFile()) {
                        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                            Object data = ois.readObject();
                            if (data instanceof YourDataType && ((YourDataType) data).getType().equals(targetDataType)) {
                                dataStore.put(file.getName(), data);
                                filteredFiles.add(file.getAbsolutePath());
                            }
                        } catch (FileNotFoundException e) {
                            System.err.println("File not found: " + file.getAbsolutePath());
                        } catch (ClassNotFoundException e) {
                            System.err.println("Class not found for file: " + file.getAbsolutePath());
                        } catch (IOException e) {
                            System.err.println("IOException for file: " + file.getAbsolutePath());
                        }
                    }
                }
            }
        }

        System.out.println("Filtered files containing the specified data type:");
        for (String filePath : filteredFiles) {
            System.out.println(filePath);
        }
    }
}

class YourDataType implements Serializable {
    private String type;

    public YourDataType(String type) {
        this.type = type;
    }

    public String getType() {
        return type;
    }
