import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import javax.swing.JFrame;
import javax.swing.JLabel;

public class ImageRotator {

    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java ImageRotator <image-file-path> <rotation-angle>");
            return;
        }

        String imagePath = args[0];
        String angleStr = args[1];
        int angle;

        try {
            angle = Integer.parseInt(angleStr);
        } catch (NumberFormatException e) {
            System.out.println("Error: Rotation angle must be an integer.");
            return;
        }

        // Rotate the image using a system call
        String command = String.format("convert %s -rotate %d rotated_image.jpg", imagePath, angle);
        try {
            Process process = Runtime.getRuntime().exec(command);
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.out.println("Error: Image rotation failed.");
                return;
            }
        } catch (IOException | InterruptedException e) {
            System.out.println("Error: Unable to execute the command.");
            e.printStackTrace();
            return;
        }

        // Display the rotated image
        displayImage("rotated_image.jpg");
    }

    private static void displayImage(String imagePath) {
        JFrame frame = new JFrame("Rotated Image");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        try {
            BufferedImage img = ImageIO.read(new File(imagePath));
            JLabel label = new JLabel(new ImageIcon(img));
            frame.getContentPane().add(label);
            frame.pack();
            frame.setVisible(true);
        } catch (IOException e) {
            System.out.println("Error: Unable to load the rotated image.");
            e.printStackTrace();
        }
    }
}
