public class MacAddressRetriever {

    public static List<String> getMacAddresses() {
        List<String> macAddresses = new ArrayList<>();
        String command = "ifconfig"; // Use "ip link" for Linux or "getmac" for Windows

        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;

            while ((line = reader.readLine()) != null) {
                if (line.contains("ether")) { // For Linux
                    String[] parts = line.trim().split("\\s+");
                    macAddresses.add(parts[1]);
                } else if (line.contains("Physical") || line.contains("MAC")) { // For Windows
                    String[] parts = line.trim().split("\\s+");
                    macAddresses.add(parts[parts.length - 1]);
                }
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }

        return macAddresses;
    }

    public static void main(String[] args) {
        List<String> macAddresses = getMacAddresses();
        for (String mac : macAddresses) {
            System.out.println(mac);
        }
    }
}
