import org.apache.commons.httpclient.HttpClient;
import org.apache.commons.httpclient.methods.PostMethod;
import org.apache.commons.httpclient.methods.StringRequestEntity;
import org.apache.commons.httpclient.UsernamePasswordCredentials;
import org.apache.commons.httpclient.auth.AuthScope;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.zip.GZIPOutputStream;
import java.util.concurrent.TimeUnit;
import com.google.common.util.concurrent.RateLimiter;

public class HttpClientUtil {

    public String sendPostRequest(String uri, String requestBody, String mediaType, String token, Integer maxRate) throws Exception {
        if (maxRate != null) {
            RateLimiter rateLimiter = RateLimiter.create(maxRate);
            rateLimiter.acquire(); // Acquire a permit, blocking if necessary
        }

        HttpClient httpClient = new HttpClient();
        PostMethod postMethod = new PostMethod(uri);
        postMethod.addRequestHeader("Content-Type", mediaType);
        if (token != null) {
            postMethod.addRequestHeader("Authorization", "Bearer " + token);
        }

        byte[] compressedBody = compressGzip(requestBody);
        StringRequestEntity entity = new StringRequestEntity(new String(compressedBody), mediaType, "UTF-8");
        postMethod.setRequestEntity(entity);

        httpClient.executeMethod(postMethod);
        return postMethod.getResponseBodyAsString();
    }

    private byte[] compressGzip(String data) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        try (GZIPOutputStream gzipOutputStream = new GZIPOutputStream(byteArrayOutputStream)) {
            gzipOutputStream.write(data.getBytes("UTF-8"));
        }
        return byteArrayOutputStream.toByteArray();
    }
}
