public class FileHashGenerator {

    public static void generateMD5Hash(String filePath) {
        File file = new File(filePath);
        if (!file.exists()) {
            System.out.println("File does not exist: " + filePath);
            return;
        }

        System.out.println("Generating MD5 hash for: " + filePath);
        try (FileInputStream fis = new FileInputStream(file);
             FileOutputStream fos = new FileOutputStream(filePath + ".md5")) {

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] dataBytes = new byte[1024];
            int bytesRead;

            while ((bytesRead = fis.read(dataBytes)) != -1) {
                md.update(dataBytes, 0, bytesRead);
            }

            byte[] mdBytes = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : mdBytes) {
                sb.append(String.format("%02x", b));
            }

            fos.write(sb.toString().getBytes());
            System.out.println("MD5 hash generated and written to: " + filePath + ".md5");

        } catch (IOException | NoSuchAlgorithmException e) {
            System.out.println("Error generating MD5 hash: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java FileHashGenerator <file-path>");
            return;
        }
        generateMD5Hash(args[0]);
    }
}
