        this.myDao = myDao;
    }

    public void createOrUpdateObject(String userName, String url, boolean someFlag, String algorithm) {
        try {
            String uniqueIdentifier = generateUniqueIdentifier(userName, url, algorithm);
            MyObject myObject = new MyObject(uniqueIdentifier, userName, url, someFlag);
            myDao.createOrUpdate(myObject);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace(); // Handle exception appropriately
        }
