import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Iterator;

public class ETagGenerator {

    public static String generateETag(Change change) {
        StringBuilder stringBuilder = new StringBuilder();
        stringBuilder.append(change.getLastUpdatedTimestamp())
                     .append(change.getRowVersion())
                     .append(change.getAccountId());

        ProjectState projectState = change.getProjectState();
        Iterator<Revision> revisions = projectState.getRevisions();

        while (revisions.hasNext()) {
            Revision revision = revisions.next();
            stringBuilder.append(revision.getRevisionId());
        }

        return calculateMD5(stringBuilder.toString());
    }

    private static String calculateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : messageDigest) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return "\"" + hexString.toString() + "\"";
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
}
