import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.zip.Deflater;

public class LZOCompressor {

    public static String compressFile(String filePath, int compressionLevel) throws IOException, NoSuchAlgorithmException {
        File inputFile = new File(filePath);
        byte[] inputData = new byte[(int) inputFile.length()];

        try (FileInputStream fis = new FileInputStream(inputFile)) {
            fis.read(inputData);
        }

        byte[] compressedData = compress(inputData, compressionLevel);
        return calculateMD5(compressedData);
    }

    private static byte[] compress(byte[] data, int compressionLevel) {
        Deflater deflater = new Deflater(compressionLevel);
        deflater.setInput(data);
        deflater.finish();

        byte[] buffer = new byte[1024];
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            while (!deflater.finished()) {
                int count = deflater.deflate(buffer);
                baos.write(buffer, 0, count);
            }
            deflater.end();
            return baos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Error during compression", e);
        }
    }

    private static String calculateMD5(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : digest) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
