import akka.io.Tcp;
import akka.io.Tcp.*;
import akka.util.ByteString;

import java.net.InetSocketAddress;

public class DiscoveryActor extends AbstractActor {
    private final ActorRef tcpManager;
    private final InetSocketAddress remoteAddress;

    public DiscoveryActor(InetSocketAddress remoteAddress) {
        this.tcpManager = Tcp.get(getContext().getSystem()).manager();
        this.remoteAddress = remoteAddress;
    }

    @Override
    public Receive createReceive() {
        return receiveBuilder()
                .match(Tcp.Bound.class, this::onBound)
                .match(Tcp.CommandFailed.class, this::onCommandFailed)
                .match(Tcp.Connected.class, this::onConnected)
                .build();
    }

    @Override
    public void preStart() {
        tcpManager.tell(Tcp.bind(getSelf(), new InetSocketAddress("localhost", 8888)), getSelf());
    }

    private void onBound(Tcp.Bound bound) {
        System.out.println("Listening on: " + bound.localAddress());
        sendDiscoveryMessage();
    }

    private void onCommandFailed(Tcp.CommandFailed commandFailed) {
        System.err.println("Command failed: " + commandFailed);
    }

    private void onConnected(Tcp.Connected connected) {
        System.out.println("Connected to: " + connected.remoteAddress());
        getSender().tell(TcpMessage.register(getSelf()), getSelf());
    }

    private void sendDiscoveryMessage() {
        ByteString message = ByteString.fromString("DISCOVERY_MESSAGE");
        tcpManager.tell(TcpMessage.connect(remoteAddress), getSelf());
        System.out.println("Sent discovery message to: " + remoteAddress);
    }

    public static void main(String[] args) {
        ActorSystem system = ActorSystem.create("DiscoverySystem");
        InetSocketAddress remoteAddress = new InetSocketAddress("remote.host.com", 9999);
        system.actorOf(Props.create(DiscoveryActor.class, remoteAddress), "discoveryActor");
    }
}
