public class RemoteClientHandler {

    public void handleClient(Socket socket) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true)) {

            // Read the request from the client
            String request = in.readLine();
            if (request == null) {
                throw new IOException("No request received from client.");
            }

            // Parse the request to identify the class and method
            String[] parts = request.split(" ");
            if (parts.length < 2) {
                out.println("Error: Invalid request format.");
                return;
            }

            String className = parts[0];
            String methodName = parts[1];
            String[] methodArgs = new String[parts.length - 2];
            System.arraycopy(parts, 2, methodArgs, 0, methodArgs.length);

            // Dynamically invoke the method
            String result = invokeMethod(className, methodName, methodArgs);

            // Send the result back to the client
            out.println(result);

        } catch (IOException e) {
            e.printStackTrace();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private String invokeMethod(String className, String methodName, String[] args) throws Exception {
        Class<?> clazz = Class.forName(className);
        Class<?>[] argTypes = new Class[args.length];
        for (int i = 0; i < args.length; i++) {
            argTypes[i] = String.class; // Assuming all arguments are strings
        }
        return (String) clazz.getMethod(methodName, argTypes).invoke(clazz.getDeclaredConstructor().newInstance(), (Object[]) args);
    }
}
