import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class ProcessExecutor {

    private static final int DEFAULT_TIMEOUT = 60000; // 60 seconds
    private static final Logger logger = LoggerFactory.getLogger(ProcessExecutor.class);

    public boolean executeProcess(List<String> commandLineArgs) {
        if (commandLineArgs == null || commandLineArgs.isEmpty()) {
            logger.warn("No command line arguments provided.");
            return false;
        }

        String command = String.join(" ", commandLineArgs);
        logger.info("Executing command: {}", command);

        ProcessBuilder processBuilder = new ProcessBuilder(commandLineArgs);
        processBuilder.redirectErrorStream(true); // Redirect error stream to output stream

        Process process;
        try {
            process = processBuilder.start();
        } catch (IOException e) {
            logger.error("Failed to start process: {}", e.getMessage());
            return false;
        }

        WatchdogThread watchdog = new WatchdogThread(process);
        watchdog.start();

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                logger.info("Process output: {}", line);
            }
        } catch (IOException e) {
            logger.error("Error reading process output: {}", e.getMessage());
        }

        try {
            boolean finished = process.waitFor(DEFAULT_TIMEOUT, TimeUnit.MILLISECONDS);
            if (!finished) {
                logger.warn("Process did not finish in time, terminating...");
                process.destroyForcibly();
                return false;
            }
        } catch (InterruptedException e) {
            logger.error("Process was interrupted: {}", e.getMessage());
            return false;
        }

        logger.info("Process completed with exit value: {}", process.exitValue());
        return true;
    }

    private static class WatchdogThread extends Thread {
        private final Process process;

        public WatchdogThread(Process process) {
            this.process = process;
        }

        @Override
        public void run() {
            try {
                process.waitFor();
