import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.KeyStore;
import java.security.PrivateKey;
import java.security.Signature;
import java.security.cert.Certificate;
import java.util.Scanner;

public class CodeSigner {

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java CodeSigner <keystore_path> <keystore_password> <file_to_sign>");
            return;
        }

        String keystorePath = args[0];
        String keystorePassword = args[1];
        String fileToSign = args[2];

        try {
            String result = signFile(keystorePath, keystorePassword, fileToSign);
            System.out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static String signFile(String keystorePath, String keystorePassword, String fileToSign) throws Exception {
        KeyStore keystore = KeyStore.getInstance("JKS");
        try (FileInputStream keystoreStream = new FileInputStream(keystorePath)) {
            keystore.load(keystoreStream, keystorePassword.toCharArray());
        }

        String alias = keystore.aliases().nextElement();
        PrivateKey privateKey = (PrivateKey) keystore.getKey(alias, keystorePassword.toCharArray());
        Certificate certificate = keystore.getCertificate(alias);

        Signature signature = Signature.getInstance("SHA256withRSA");
        signature.initSign(privateKey);

        byte[] fileData = readFile(fileToSign);
        signature.update(fileData);
        byte[] digitalSignature = signature.sign();

        String signedFilePath = fileToSign + ".sig";
        try (FileOutputStream fos = new FileOutputStream(signedFilePath)) {
            fos.write(digitalSignature);
        }

        return "File signed successfully. Signature saved to: " + signedFilePath;
    }

    private static byte[] readFile(String filePath) throws IOException {
        File file = new File(filePath);
        byte[] data = new byte[(int) file.length()];
        try (FileInputStream fis = new FileInputStream(file)) {
            fis.read(data);
        }
        return data;
    }
}
