public class SerializationTest {
    public static void main(String[] args) {
        SerializableObject obj = new SerializableObject("TestObject", 123);
        int iterations = 500;
        long totalTime = 0;
        long totalSize = 0;

        for (int i = 0; i < iterations; i++) {
            long startTime = System.nanoTime();
            byte[] serializedData = serialize(obj);
            long endTime = System.nanoTime();

            totalTime += (endTime - startTime);
            totalSize += serializedData.length;

            SerializableObject deserializedObj = deserialize(serializedData);
            System.out.println("Iteration " + (i + 1) + ": " + deserializedObj);
        }

        System.out.println("Average serialization time (ns): " + (totalTime / iterations));
        System.out.println("Average serialized size (bytes): " + (totalSize / iterations));
    }

    private static byte[] serialize(SerializableObject obj) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(obj);
            return bos.toByteArray();
        } catch (IOException e) {
            e.printStackTrace();
            return new byte[0];
        }
    }

    private static SerializableObject deserialize(byte[] data) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return (SerializableObject) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
            return null;
        }
    }
