import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class MapMerger {

    public Map<String, byte[]> mergeMaps(Map<String, String> stringMap, byte[] binaryData) throws IOException, ClassNotFoundException {
        Map<String, byte[]> mergedMap = new HashMap<>(stringMap.size() + 1);

        // Deserialize the binary data into a map of string keys to byte values
        Map<String, byte[]> binaryMap = deserializeBinaryData(binaryData);

        // Merge the two maps
        mergedMap.putAll(binaryMap);

        // Convert string values to byte values and add to the merged map
        for (Map.Entry<String, String> entry : stringMap.entrySet()) {
            mergedMap.put(entry.getKey(), entry.getValue().getBytes());
        }

        return mergedMap;
    }

    private Map<String, byte[]> deserializeBinaryData(byte[] binaryData) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(binaryData);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return (Map<String, byte[]>) ois.readObject();
        }
    }
}
