import java.nio.charset.StandardCharsets;
import java.util.zip.CRC32;

public class HashUtil {

    public static long hashString(String input, String hashFunction) {
        switch (hashFunction.toLowerCase()) {
            case "crc32":
                return crc32Hash(input);
            case "simple":
                return simpleHash(input);
            default:
                throw new IllegalArgumentException("Unsupported hash function: " + hashFunction);
        }
    }

    private static long crc32Hash(String input) {
        CRC32 crc = new CRC32();
        crc.update(input.getBytes(StandardCharsets.UTF_8));
        return crc.getValue();
    }

    private static long simpleHash(String input) {
        long hash = 0;
        for (char c : input.toCharArray()) {
            hash = 31 * hash + c;
        }
        return hash;
    }

    public static void main(String[] args) {
        String testString = "Hello, World!";
        System.out.println("CRC32 Hash: " + hashString(testString, "crc32"));
        System.out.println("Simple Hash: " + hashString(testString, "simple"));
    }
}
