            // Create a MessageDigest instance for MD5
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Generate a random UUID and convert it to bytes
            UUID randomUUID = UUID.randomUUID();
            byte[] uuidBytes = randomUUID.toString().getBytes();

            // Calculate the MD5 hash
            byte[] digest = md.digest(uuidBytes);

            // Convert the first 16 bytes of the hash to a UUID
            long mostSigBits = 0;
            long leastSigBits = 0;
            for (int i = 0; i < 8; i++) {
                mostSigBits <<= 8;
                mostSigBits |= (digest[i] & 0xff);
            }
            for (int i = 8; i < 16; i++) {
                leastSigBits <<= 8;
                leastSigBits |= (digest[i] & 0xff);
            }

            return new UUID(mostSigBits, leastSigBits);
        } catch (NoSuchAlgorithmException e) {
            // Handle the exception (e.g., log it or rethrow it)
