import java.io.*;
import java.nio.file.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import java.sql.*;
import java.util.*;

public class FileDataExtractor {
    public static void main(String[] args) {
        if (args.length < 1) {
            System.err.println("Usage: java FileDataExtractor <file1> <file2> ...");
            System.exit(1);
        }

        for (String filePath : args) {
            try {
                if (filePath.endsWith(".xml")) {
                    extractFromXML(filePath);
                } else if (filePath.endsWith(".sql")) {
                    extractFromSQL(filePath);
                } else {
                    System.err.println("Unsupported file format: " + filePath);
                }
            } catch (Exception e) {
                System.err.println("Error processing file " + filePath + ": " + e.getMessage());
            }
        }
    }

    private static void extractFromXML(String filePath) throws Exception {
        File xmlFile = new File(filePath);
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        Document doc = dBuilder.parse(xmlFile);
        doc.getDocumentElement().normalize();

        NodeList nodeList = doc.getElementsByTagName("data");
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                System.out.println("Extracted XML Data: " + element.getTextContent());
            }
        }
    }

    private static void extractFromSQL(String filePath) throws Exception {
        Connection conn = null;
        Statement stmt = null;
        try {
            // Assuming a SQLite database for demonstration
            conn = DriverManager.getConnection("jdbc:sqlite:sample.db");
            stmt = conn.createStatement();
            String sql = new String(Files.readAllBytes(Paths.get(filePath)));
            ResultSet rs = stmt.executeQuery(sql);

            while (rs.next()) {
                System.out.println("Extracted SQL Data: " + rs.getString(1));
            }
            rs.close();
        } catch (SQLException e) {
            System.err.println("SQL Error: " + e.getMessage());
        } finally {
            if (stmt != null) stmt.close();
            if (conn != null) conn.close();
        }
    }
}
