import java.util.Arrays;

public class CoordinateParser {

    public static void parseCoordinates(String coordinates, String delimiter, double expectedX, double expectedY) {
        String[] parts = coordinates.split(delimiter);
        if (parts.length != 2) {
            throw new IllegalArgumentException("Input must contain exactly two coordinates.");
        }

        double x = Double.parseDouble(parts[0].trim());
        double y = Double.parseDouble(parts[1].trim());

        assert x == expectedX : "Expected X: " + expectedX + ", but got: " + x;
        assert y == expectedY : "Expected Y: " + expectedY + ", but got: " + y;
    }

    public static void main(String[] args) {
        // Example usage
        parseCoordinates("12.5, 15.0", ",", 12.5, 15.0);
    }
}
