import java.io.Serializable;

public class SingletonLoader implements Serializable {
    private static final long serialVersionUID = 1L;
    private static SingletonLoader instance;

    private SingletonLoader() {
        // Private constructor to prevent instantiation
    }

    public static SingletonLoader getInstance() {
        if (instance == null) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("singleton.ser"))) {
                instance = (SingletonLoader) ois.readObject();
            } catch (IOException | ClassNotFoundException e) {
                instance = new SingletonLoader();
                saveInstance();
            }
        }
        return instance;
    }

    private static void saveInstance() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("singleton.ser"))) {
            oos.writeObject(instance);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
