import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    public int executeCommand(InputStream inputStream, OutputStream outputStream, String command, Optional<Long> timeout) {
        Process process = null;
        int exitCode = -1;

        try {
            process = Runtime.getRuntime().exec(command);

            // Handle input stream
            if (inputStream != null) {
                Thread inputThread = new Thread(() -> {
                    try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            outputStream.write((line + "\n").getBytes());
                        }
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                });
                inputThread.start();
            }

            // Wait for the process to complete with timeout
            boolean finished = process.waitFor(timeout.orElse(60000), TimeUnit.MILLISECONDS);
            if (!finished) {
                process.destroyForcibly();
                throw new IOException("Process timed out and was forcibly terminated.");
            }

            exitCode = process.exitValue();
        } catch (IOException e) {
            e.printStackTrace();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            e.printStackTrace();
        } finally {
            if (process != null) {
                process.destroy();
            }
        }

        return exitCode;
    }
