import java.io.*;
import java.util.Objects;

class NFA implements Serializable {
    private static final long serialVersionUID = 1L;
    private int windowLength;

    public NFA(int windowLength) {
        this.windowLength = windowLength;
    }

    public int getWindowLength() {
        return windowLength;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof NFA)) return false;
        NFA nfa = (NFA) o;
        return windowLength == nfa.windowLength;
    }

    @Override
    public int hashCode() {
        return Objects.hash(windowLength);
    }
}

public class NFASerializer {
    public static void main(String[] args) {
        try {
            NFA originalNFA = new NFA(5);
            byte[] serializedNFA = serialize(originalNFA);
            NFA deserializedNFA = deserialize(serializedNFA);

            System.out.println("Original NFA: " + originalNFA.getWindowLength());
            System.out.println("Deserialized NFA: " + deserializedNFA.getWindowLength());
            System.out.println("Are they equal? " + originalNFA.equals(deserializedNFA));
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }

    private static byte[] serialize(NFA nfa) throws IOException {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(bos)) {
            oos.writeObject(nfa);
            return bos.toByteArray();
        }
    }

    private static NFA deserialize(byte[] data) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return (NFA) ois.readObject();
        }
    }
}
