public class QueryGenerator {

    private static final String COMMAND_TEMPLATE = "path/to/external/tool --generate-query %s";
    private static final int TIMEOUT = 60000; // 60 seconds

    public static void main(String[] args) {
        String inputTemplate = "your_template_here"; // Replace with actual template input
        executeQueryGenerator(inputTemplate);
    }

    public static void executeQueryGenerator(String template) {
        String commandLine = String.format(COMMAND_TEMPLATE, template);
        Process proc = null;

        try {
            proc = Runtime.getRuntime().exec(commandLine);
            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            // Read the output
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
            }

            // Read the error stream
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    errorBuilder.append(line).append("\n");
                }
            }

            // Wait for the process to complete
            boolean finished = proc.waitFor(TIMEOUT, TimeUnit.MILLISECONDS);
            if (!finished) {
                proc.destroyForcibly();
                System.err.println("Process timed out and was forcibly terminated.");
            }

            // Output results
            System.out.println("Output:\n" + outputBuilder.toString());
            if (errorBuilder.length() > 0) {
                System.err.println("Errors:\n" + errorBuilder.toString());
            }

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            if (proc != null) {
                proc.destroy();
            }
        }
    }
}
