public class HashUtil {
    public static long sha1HashToUnsignedLong(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] asciiBytes = input.getBytes("ASCII");
            byte[] hashBytes = digest.digest(asciiBytes);

            long hashValue = 0;
            for (int i = 0; i < 8; i++) {
                hashValue = (hashValue << 8) | (hashBytes[i] & 0xFF);
            }
            return hashValue;
        } catch (NoSuchAlgorithmException | java.io.UnsupportedEncodingException e) {
            throw new RuntimeException("Error while hashing the input string", e);
        }
    }
}
