import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;

public class FileUploader {

    public static void uploadFile(String filePath, String serverUrl) {
        File file = new File(filePath);
        if (!file.exists()) {
            System.err.println("File not found: " + filePath);
            return;
        }

        int maxRetries = 3;
        int attempt = 0;
        boolean success = false;

        while (attempt < maxRetries && !success) {
            attempt++;
            success = upload(file, serverUrl);
            if (!success) {
                System.out.println("Upload failed, retrying... (" + attempt + "/" + maxRetries + ")");
            }
        }

        if (success) {
            System.out.println("File uploaded successfully.");
        } else {
            System.err.println("Failed to upload file after " + maxRetries + " attempts.");
        }
    }

    private static boolean upload(File file, String serverUrl) {
        HttpURLConnection connection = null;
        try (FileInputStream inputStream = new FileInputStream(file)) {
            URL url = new URL(serverUrl);
            connection = (HttpURLConnection) url.openConnection();
            connection.setDoOutput(true);
            connection.setRequestMethod("PUT");
            connection.setRequestProperty("Content-Type", "application/octet-stream");
            connection.setRequestProperty("Content-Length", String.valueOf(file.length()));

            // Write file to output stream
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                connection.getOutputStream().write(buffer, 0, bytesRead);
            }

            // Check the response code
            int responseCode = connection.getResponseCode();
            return responseCode == HttpURLConnection.HTTP_OK;

        } catch (IOException e) {
            System.err.println("IOException during upload: " + e.getMessage());
            return false;
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

    public static void main(String[] args) {
        String filePath = "path/to/your/file.txt";
        String serverUrl = "http://yourserver.com/upload";
        uploadFile(filePath, serverUrl);
    }
}
