import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Formatter;

public class RandomStringGenerator {

    public static String generateRandomString(double seed) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(Double.toString(seed).getBytes());
            byte[] digest = md.digest();
            return formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Hashing algorithm not found", e);
        }
    }

    private static String formatHex(byte[] bytes) {
        Formatter formatter = new Formatter();
        for (byte b : bytes) {
            formatter.format("%02x", b);
        }
        String hexString = formatter.toString();
        return hexString.length() > 32 ? hexString.substring(0, 32) : hexString;
    }

    public static void main(String[] args) {
        double seed = 12345.6789;
        String randomString = generateRandomString(seed);
        System.out.println(randomString);
    }
}
