import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public class MGF1 {

    public static byte[] mgf1(int maskLength, byte[] seed, String digestAlgorithm) throws NoSuchAlgorithmException {
        int hLen = MessageDigest.getInstance(digestAlgorithm).getDigestLength();
        int d = (int) Math.ceil((double) maskLength / hLen);
        byte[] mask = new byte[maskLength];
        byte[] buffer = new byte[seed.length + 4];
        MessageDigest md = MessageDigest.getInstance(digestAlgorithm);

        for (int i = 0; i < d; i++) {
            // Copy seed into buffer
            System.arraycopy(seed, 0, buffer, 0, seed.length);
            // Append the integer i as a 4-byte big-endian value
            buffer[seed.length] = (byte) (i >> 24);
            buffer[seed.length + 1] = (byte) (i >> 16);
            buffer[seed.length + 2] = (byte) (i >> 8);
            buffer[seed.length + 3] = (byte) (i);

            // Hash the buffer and store the result in the mask
            byte[] hash = md.digest(buffer);
            int offset = i * hLen;
            int len = Math.min(hLen, maskLength - offset);
            System.arraycopy(hash, 0, mask, offset, len);
        }

        return mask;
    }
}
