{
    unsigned char hash[20]; // SHA-1 produces a 20-byte hash
    char hash_str[41]; // 40 hex characters + null terminator
    SHA1_CTX sha1_ctx;

    pj_assert(result->slen >= 41); // Ensure result buffer is large enough

    // Hash the input string
    SHA1_Init(&sha1_ctx);
    SHA1_Update(&sha1_ctx, input->ptr, input->slen);
