    // Convert hash to hex string
    for (int i = 0; i < 20; i++) {
        sprintf(&hash_str[i * 2], "%02x", hash[i]);
    }

    // Hash the namespace
    unsigned char namespace_hash[20];
    SHA1_Init(&sha1_ctx);
    SHA1_Update(&sha1_ctx, namespace->ptr, namespace->slen);
    SHA1_Final(namespace_hash, &sha1_ctx);

    char namespace_hash_str[41];
    for (int i = 0; i < 20; i++) {
        sprintf(&namespace_hash_str[i * 2], "%02x", namespace_hash[i]);
    }

    // Format the result as 'prefix:namespace:key'
