const fs = require('fs');
const path = require('path');

const moduleCache = new Map();

function loadModule(filename, options) {
    const resolvedPath = path.resolve(filename);

    if (moduleCache.has(resolvedPath)) {
        return moduleCache.get(resolvedPath);
    }

    try {
        const moduleContent = fs.readFileSync(resolvedPath, 'utf-8');
        const module = new Function('exports', moduleContent);
        const exports = {};
        module(exports);

        if (typeof exports.default !== 'function') {
            throw new Error(`Module does not export a default function`);
        }

        moduleCache.set(resolvedPath, exports.default);
        return exports.default;
    } catch (error) {
        throw new Error(`Failed to load module: ${error.message}`);
    }
}
