const path = require('path');
const stylus = require('stylus');

function generateCSS(filePath, destinationDir) {
    const stylusFiles = fs.readdirSync(filePath).filter(file => file.endsWith('.styl'));
    let combinedCSS = '';

    stylusFiles.forEach(file => {
        const fileContent = fs.readFileSync(path.join(filePath, file), 'utf8');
        combinedCSS += fileContent + '\n';
    });

    stylus.render(combinedCSS, (err, css) => {
        if (err) {
            throw new Error(`Error processing Stylus files: ${err.message}`);
        }

        const outputFilePath = path.join(destinationDir, 'styles.css');
        fs.mkdirSync(destinationDir, { recursive: true });
        fs.writeFileSync(outputFilePath, css);
        console.log(`CSS file generated at: ${outputFilePath}`);
    });
}
