function testElementSelector(element, selector, operator = '=', value = null) {
    if (!(element instanceof Element)) {
        throw new Error("First argument must be a DOM element.");
    }

    const attrValue = Sizzle.attr(element, selector);

    if (value === null) {
        return attrValue !== undefined;
    }

    switch (operator) {
        case '=':
            return attrValue === value;
        case '!=':
            return attrValue !== value;
        case '<':
            return attrValue < value;
        case '<=':
            return attrValue <= value;
        case '>':
            return attrValue > value;
        case '>=':
            return attrValue >= value;
        default:
            throw new Error("Invalid operator. Use '=', '!=', '<', '<=', '>', '>='.");
    }
}
