function depthFirstSearch(grid, startX, startY, maxNodes) {
    const rows = grid.length;
    const cols = grid[0].length;
    let visitedCount = 0;

    function isValid(x, y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y].state !== 'visited';
    }

    function plantNode() {
        let planted = false;
        while (!planted && visitedCount < maxNodes) {
            const randomX = Math.floor(Math.random() * rows);
            const randomY = Math.floor(Math.random() * cols);
            if (grid[randomX][randomY].state !== 'visited') {
                grid[randomX][randomY].value = Math.floor(Math.random() * 100); // Random value
                grid[randomX][randomY].state = 'planted';
                planted = true;
                visitedCount++;
            }
        }
    }

    function dfs(x, y) {
        if (!isValid(x, y)) return;

        grid[x][y].state = 'visited';
        plantNode();

        // Explore neighbors (up, down, left, right)
        dfs(x - 1, y); // up
        dfs(x + 1, y); // down
        dfs(x, y - 1); // left
        dfs(x, y + 1); // right
    }

    dfs(startX, startY);
}

