const ctx = canvas.getContext('2d');
let particle = { x: canvas.width / 2, y: canvas.height / 2 };

function updateParticlePosition(event) {
    const randomOffsetX = (Math.random() - 0.5) * 20; // Random offset between -10 and 10
    const randomOffsetY = (Math.random() - 0.5) * 20; // Random offset between -10 and 10

    switch (event.key) {
        case 'ArrowUp':
            particle.y -= 5 + randomOffsetY;
            break;
        case 'ArrowDown':
            particle.y += 5 + randomOffsetY;
            break;
        case 'ArrowLeft':
            particle.x -= 5 + randomOffsetX;
            break;
        case 'ArrowRight':
            particle.x += 5 + randomOffsetX;
            break;
    }

    // Keep particle within canvas bounds
    particle.x = Math.max(0, Math.min(canvas.width, particle.x));
    particle.y = Math.max(0, Math.min(canvas.height, particle.y));

    drawParticle();
}

function drawParticle() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, 10, 0, Math.PI * 2);
