function autocomplete(inputElement, suggestionsContainer) {
    inputElement.addEventListener('input', function() {
        const query = this.value;

        if (query.length < 2) {
            suggestionsContainer.innerHTML = '';
            return;
        }

        fetch(`path/to/your/php/script.php?query=${encodeURIComponent(query)}`)
            .then(response => response.json())
            .then(data => {
                const templateSource = document.getElementById('suggestion-template').innerHTML;
                const template = Handlebars.compile(templateSource);
                const html = template(data);
                suggestionsContainer.innerHTML = html;

                const suggestionItems = suggestionsContainer.querySelectorAll('.suggestion-item');
                suggestionItems.forEach(item => {
                    item.addEventListener('click', function() {
                        const selectedProductId = this.getAttribute('data-id');
