def escape_unescape_string(input_string, character_map, unescape=False):
    """Escapes or unescapes special characters in a string based on a character map."""

    if unescape:
        # Create a reverse map for unescaping
        reverse_map = {v: k for k, v in character_map.items()}
        pattern = re.compile('|'.join(re.escape(key) for key in reverse_map.keys()))
        return pattern.sub(lambda match: reverse_map[match.group(0)], input_string)
