function createParticleSystem(m) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    document.body.appendChild(canvas);

    // Create bitmap of the message
    ctx.font = '48px sans-serif';
    const textWidth = ctx.measureText(m).width;
    canvas.width = textWidth;
    canvas.height = 60; // Adjust height as needed
    ctx.fillStyle = 'white';
    ctx.fillText(m, 0, 50);

    const particles = [];
    const particleCount = 100; // Number of particles

    // Create particles from the bitmap
    for (let x = 0; x < canvas.width; x++) {
        for (let y = 0; y < canvas.height; y++) {
            const pixel = ctx.getImageData(x, y, 1, 1).data;
            if (pixel[3] > 0) { // Check if pixel is not transparent
                particles.push({
                    x: x,
                    y: y,
                    velocityX: 0,
                    velocityY: 0
                });
            }
        }
    }

    function explode() {
        particles.forEach(particle => {
            particle.velocityX = (Math.random() - 0.5) * 10; // Random velocity in X
            particle.velocityY = (Math.random() - 0.5) * 10; // Random velocity in Y
        });
    }

    // Animation loop to update particle positions
    function animate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        particles.forEach(particle => {
            particle.x += particle.velocityX;
            particle.y += particle.velocityY;
            ctx.fillRect(particle.x, particle.y, 2, 2); // Draw particle
        });
        requestAnimationFrame(animate);
    }

    animate();

    return {
        explode: explode
    };
}

