function parseCSSSelector(selector) {
    const result = {
        combinators: [],
        simpleSelectors: [],
        attributeTests: []
    };

    // Regular expressions for different components
    const combinatorRegex = /[>+~]/g;
    const simpleSelectorRegex = /([.#]?[a-zA-Z_][\w-]*)|(\*)|(:[a-zA-Z-]+(?:\([^\)]+\))?)/g;
    const attributeTestRegex = /\[([^\]]+)\]/g;

    // Trim whitespace and split by combinators
    const parts = selector.trim().split(combinatorRegex);

    parts.forEach(part => {
        const trimmedPart = part.trim();

        // Check for attribute tests
        let attributeMatch;
        while ((attributeMatch = attributeTestRegex.exec(trimmedPart)) !== null) {
            result.attributeTests.push(attributeMatch[1].trim());
        }

        // Check for simple selectors
        let simpleMatch;
        while ((simpleMatch = simpleSelectorRegex.exec(trimmedPart)) !== null) {
            if (simpleMatch[0]) {
                result.simpleSelectors.push(simpleMatch[0].trim());
            }
        }
    });

    // Collect combinators
    const combinatorMatches = selector.match(combinatorRegex);
    if (combinatorMatches) {
        result.combinators = combinatorMatches.map(c => c.trim());
    }

    return result;
}
