function getRandomGreeting() {
    const greetings = {
        morning: ["Good morning!", "Rise and shine!", "Wishing you a wonderful morning!"],
        afternoon: ["Good afternoon!", "Hope your day is going well!", "Enjoy your afternoon!"],
        evening: ["Good evening!", "Hope you had a great day!", "Relax and unwind this evening!"]
    };

    const hour = new Date().getHours();
    let selectedGreeting;

    if (hour >= 5 && hour < 12) {
        selectedGreeting = greetings.morning;
    } else if (hour >= 12 && hour < 18) {
        selectedGreeting = greetings.afternoon;
    } else if (hour >= 18 && hour < 22) {
        selectedGreeting = greetings.evening;
    } else {
        return "Hello!"; // Default greeting
    }

    return selectedGreeting[Math.floor(Math.random() * selectedGreeting.length)];
}
