void generate_uuid(int length, char *uuid) {
    if (length != UUID_LENGTH) {
        fprintf(stderr, "Invalid UUID length specified. Must be %d.\n", UUID_LENGTH);
        return;
    }

    const char *uuid_chars = "0123456789abcdef";
    unsigned char random_bytes[16];
    FILE *randfp;

