    if ((randfp = fopen("/dev/urandom", "r")) == NULL) {
        perror("Error opening /dev/urandom:");
        return;
    }

    /* Read random octets */
    if (fread(random_bytes, 1, sizeof(random_bytes), randfp) != sizeof(random_bytes)) {
        fprintf(stderr, "Error: Couldn't read from /dev/urandom\n");
        fclose(randfp);
        return;
    }
    fclose(randfp);

    /* Format the UUID according to RFC 4122 */
    snprintf(uuid, length + 1,
             "%02x%02x%02x%02x-%02x%02x-%04x-%04x-%02x%02x%02x%02x",
