async function reloadCommand(commandName, client) {
    try {
        // Check if the command exists
        if (!client.commands.has(commandName)) {
            console.error(`Command ${commandName} does not exist.`);
            return;
        }

        // Delete the old command
        client.commands.delete(commandName);

        // Re-require the command module
        const command = require(`./commands/${commandName}`);

        // Update the command's aliases if they exist
        if (command.aliases) {
            command.aliases.forEach(alias => {
                client.commands.set(alias, command);
            });
        }

        // Set the new command
        client.commands.set(commandName, command);

        console.info(`Command ${commandName} reloaded successfully.`);
    } catch (error) {
        console.error(`Error reloading command ${commandName}:`, error);
    }
