function processString(input) {
    const patterns = [
        { regex: /foo/, handler: (match) => `Found foo: ${match[0]}` },
        { regex: /bar/, handler: (match) => `Found bar: ${match[0]}` },
        { regex: /baz/, handler: (match) => `Found baz: ${match[0]}` },
    ];

    for (const { regex, handler } of patterns) {
        const match = input.match(regex);
        if (match) {
            return typeof handler === 'function' ? handler(match) : eval(handler);
        }
    }

