function createMessageChannel() {
    if (typeof MessageChannel !== 'undefined') {
        const channel = new MessageChannel();
        return {
            send: (message) => channel.port1.postMessage(message),
            onMessage: (callback) => channel.port2.onmessage = (event) => callback(event.data)
        };
    } else if (typeof window !== 'undefined' && window.postMessage) {
        return {
            send: (message) => window.postMessage(message, '*'),
            onMessage: (callback) => {
                window.addEventListener('message', (event) => callback(event.data));
            }
        };
    } else if (typeof ActiveXObject !== 'undefined') {
        // Fallback for IE8 using ONREADYSTATECHANGE
        const iframe = document.createElement('iframe');
        document.body.appendChild(iframe);
        const iframeWindow = iframe.contentWindow;

        return {
            send: (message) => iframeWindow.document.body.innerHTML = message,
            onMessage: (callback) => {
                iframeWindow.document.body.onreadystatechange = function() {
                    if (this.readyState === 'complete') {
                        callback(this.innerHTML);
                    }
                };
            }
        };
    } else {
        throw new Error('No message passing mechanism available');
    }
}

