function traverseDOM(element, selector, testFunction) {
    let matchedElements = [];

    function recursiveTraverse(el) {
        if (!el) return;

        // Check if the current element matches the selector
        if (el.matches(selector) && testFunction(el)) {
            matchedElements.push(el);
        }

        // Recursively traverse through child nodes
        for (let child of el.children) {
            recursiveTraverse(child);
        }
    }

    recursiveTraverse(element);
    return matchedElements;
}
