import hashlib

class HashGenerator:
    def __init__(self):
        self.object_counter = 0
        self.seen_objects = {}

    def get_hash(self, item):
        if item is None:
            return "undefined"

        if isinstance(item, dict):
            if id(item) not in self.seen_objects:
                self.object_counter += 1
                self.seen_objects[id(item)] = self.object_counter
            return f"object_{self.seen_objects[id(item)]}"

        if isinstance(item, list):
            return f"list_{hash(tuple(map(self.get_hash, item)))}"

        return hashlib.sha256(str(item).encode()).hexdigest()

