function createExecutor(code) {
    const cache = new Map();

    return async function(s, k) {
        const cacheKey = JSON.stringify({ s, k });
        if (cache.has(cacheKey)) {
            return cache.get(cacheKey);
        }

        try {
            const func = new Function(...Object.keys(k), `with(this) { return (${code}); }`).bind(s);
            const result = await func(...Object.values(k));
            cache.set(cacheKey, result);
            return result;
        } catch (error) {
            console.error("Error executing code:", error);
            throw error;
        }
    };
}
