class StreamCollector {
    constructor() {
        this.data = [];
        this.isPaused = false;
        this.stream = null;
    }

    startStream(stream) {
        this.stream = stream;
        this.stream.on('data', (chunk) => {
            if (!this.isPaused) {
                this.collectData(chunk);
            }
        });

        this.stream.on('end', () => {
            console.log('Stream ended. Collected data:', this.data);
        });
    }

    collectData(chunk) {
        this.data.push(chunk);
    }

    pause() {
        this.isPaused = true;
    }

    resume() {
        this.isPaused = false;
    }
}

