function createDraggableObject(minX, minY, maxX, maxY) {
    const draggable = document.createElement('div');
    draggable.style.position = 'absolute';
    draggable.style.width = '100px';
    draggable.style.height = '100px';
    draggable.style.backgroundColor = 'lightblue';
    document.body.appendChild(draggable);

    let isDragging = false;

    function onDragStart(event) {
        isDragging = true;
        draggable.style.transition = 'none';
    }

    function onDrag(event) {
        if (!isDragging) return;
        let newX = event.clientX - draggable.offsetWidth / 2;
        let newY = event.clientY - draggable.offsetHeight / 2;

        newX = Math.max(minX, Math.min(newX, maxX - draggable.offsetWidth));
        newY = Math.max(minY, Math.min(newY, maxY - draggable.offsetHeight));

        draggable.style.left = newX + 'px';
        draggable.style.top = newY + 'px';
    }

    function onDragEnd() {
        isDragging = false;
        draggable.style.transition = 'all 0.2s';
    }

    draggable.addEventListener('mousedown', onDragStart);
    document.addEventListener('mousemove', onDrag);
    document.addEventListener('mouseup', onDragEnd);

    const startButton = document.createElement('button');
    startButton.innerText = 'Start Dragging';
    document.body.appendChild(startButton);

    const stopButton = document.createElement('button');
    stopButton.innerText = 'Stop Dragging';
    document.body.appendChild(stopButton);

    startButton.addEventListener('click', () => {
        isDragging = true;
    });

    stopButton.addEventListener('click', () => {
        isDragging = false;
    });
}

