function* coroutine(iterator) {
    let controlToken;
    while (true) {
        controlToken = yield;
        if (controlToken === 'yield') {
            // Put the coroutine back in the list of iterators to be processed again
            yield* iterator;
        } else {
            // Process the next value from the iterator
            const nextValue = iterator.next(controlToken);
            if (nextValue.done) break;
            yield nextValue.value;
        }
    }
}
