function makeDraggableResizable(element) {
    let isResizing = false;
    let isDragging = false;
    let startX, startY, startWidth, startHeight;

    const resizeHandle = document.createElement('div');
    resizeHandle.style.width = '10px';
    resizeHandle.style.height = '10px';
    resizeHandle.style.background = 'blue';
    resizeHandle.style.position = 'absolute';
    resizeHandle.style.right = '0';
    resizeHandle.style.bottom = '0';
    resizeHandle.style.cursor = 'nwse-resize';
    element.appendChild(resizeHandle);

    resizeHandle.addEventListener('mousedown', (e) => {
        isResizing = true;
        startX = e.clientX;
        startY = e.clientY;
        startWidth = parseInt(document.defaultView.getComputedStyle(element).width, 10);
        startHeight = parseInt(document.defaultView.getComputedStyle(element).height, 10);
        e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
        if (isResizing) {
            element.style.width = (startWidth + e.clientX - startX) + 'px';
            element.style.height = (startHeight + e.clientY - startY) + 'px';
        }
    });

    document.addEventListener('mouseup', () => {
        isResizing = false;
    });

    element.addEventListener('mousedown', (e) => {
        isDragging = true;
        startX = e.clientX - element.offsetLeft;
        startY = e.clientY - element.offsetTop;
        e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
        if (isDragging) {
            element.style.left = (e.clientX - startX) + 'px';
            element.style.top = (e.clientY - startY) + 'px';
            element.style.position = 'absolute';
        }
    });

    document.addEventListener('mouseup', () => {
        isDragging = false;
    });

    const leftAlignButton = document.createElement('button');
    leftAlignButton.innerText = 'Align Left';
    leftAlignButton.addEventListener('click', () => {
        element.style.left = '0px';
    });
    document.body.appendChild(leftAlignButton);

    const rightAlignButton = document.createElement('button');
    rightAlignButton.innerText = 'Align Right';
    rightAlignButton.addEventListener('click', () => {
        element.style.left = (window.innerWidth - element.offsetWidth) + 'px';
    });
    document.body.appendChild(rightAlignButton);
}

