const propTypeCache = new Map();

function validateProps(componentName, props, propTypes) {
    if (process.env.NODE_ENV !== 'production') {
        const cacheKey = `${componentName}-${JSON.stringify(props)}`;
        if (propTypeCache.has(cacheKey)) {
            return;
        }

        const propTypeErrors = PropTypes.checkPropTypes(propTypes, props, 'prop', componentName);
        if (propTypeErrors) {
            console.warn(`Invalid props for ${componentName}: ${propTypeErrors}`);
        }

        const unknownProps = Object.keys(props).filter(prop => !propTypes.hasOwnProperty(prop));
        if (unknownProps.length > 0) {
            console.warn(`Unknown props for ${componentName}: ${unknownProps.join(', ')}`);
        }

        propTypeCache.set(cacheKey, true);
    }
}

export default validateProps;
