function modifyUrl(url, rootPath, newHash) {
    // Create a URL object from the provided URL
    const urlObj = new URL(url);

    // Check if the current path starts with the root path
    if (urlObj.pathname.startsWith(rootPath)) {
        // Remove the root path from the current path
        urlObj.pathname = urlObj.pathname.replace(rootPath, '');
    }

    // Set or replace the hash value based on the condition
    if (newHash) {
        urlObj.hash = newHash;
