function setupIframeListener(iframe) {
    iframe.addEventListener('load', function() {
        const src = iframe.src;
        const autoplay = iframe.hasAttribute('data-autoplay');
        let message;

        if (src.includes('video')) {
            message = autoplay ? 'playVideo' : 'pauseVideo';
        } else if (src.includes('slide')) {
            message = 'slide:start';
        } else {
            message = 'play';
        }

        iframe.contentWindow.postMessage(message, '*');
    });
}

