inline Buffer* copy_bytes(size_t *n, Chunk *list) {
    size_t total_bytes = 0;
    Chunk *current = list;

    // Calculate total bytes to copy
    while (current != NULL && total_bytes < *n) {
        total_bytes += current->size;
        current = current->next;
    }

    // Adjust n to the number of bytes actually copied
    if (total_bytes > *n) {
        total_bytes = *n;
    }
    *n = total_bytes;

    // Allocate buffer
    Buffer *buffer = (Buffer *)malloc(sizeof(Buffer));
    buffer->size = total_bytes;
    buffer->data = (unsigned char *)malloc(total_bytes);

    // Copy data from chunks to buffer
    size_t bytes_copied = 0;
    current = list;
    while (current != NULL && bytes_copied < total_bytes) {
        size_t to_copy = (current->size < (total_bytes - bytes_copied)) ? current->size : (total_bytes - bytes_copied);
        memcpy(buffer->data + bytes_copied, current->data, to_copy);
        bytes_copied += to_copy;
        current = current->next;
    }

    return buffer;
}
