public class MethodFilter {

    public static List<Method> filterMethods(List<Class<?>> classes, Set<String> excludedMethodNames, 
                                             Class<?> excludedInterface, boolean excludeAbstract, 
                                             Class<?> excludedAnnotation) {
        List<Method> filteredMethods = new ArrayList<>();

        for (Class<?> clazz : classes) {
            for (Method method : clazz.getDeclaredMethods()) {
                boolean isExcluded = excludedMethodNames.contains(method.getName()) ||
                                     (excludedInterface != null && method.getDeclaringClass().isAssignableFrom(excludedInterface)) ||
                                     (excludeAbstract && java.lang.reflect.Modifier.isAbstract(method.getModifiers())) ||
                                     (excludedAnnotation != null && method.isAnnotationPresent(excludedAnnotation));

                if (!isExcluded) {
                    filteredMethods.add(method);
                }
            }
        }

        return filteredMethods;
    }
}
