        return null;
    }

    if (!function_exists('file')) {
        $log[] = "file() function is not available. Returning null.";
        return null;
    }

    $mimeType = mime_content_type($filePath);

    if ($mimeType === false) {
        $log[] = "Failed to detect MIME type for file: $filePath. Returning null.";
        return null;
    }

    $log[] = "Detected MIME type for file $filePath: $mimeType.";
    return $mimeType;
