function encryptAndUpload($filePath, $password, $soapUrl) {
    // Check if the file exists
    if (!file_exists($filePath)) {
        throw new Exception("File not found: " . $filePath);
    }

    // Encrypt the file
    $encryptedData = openssl_encrypt(file_get_contents($filePath), 'aes-256-cbc', $password, 0, substr(hash('sha256', $password), 0, 16));
    if ($encryptedData === false) {
        throw new Exception("Encryption failed: " . openssl_error_string());
    }

    // Prepare SOAP client
    try {
        $client = new SoapClient($soapUrl);
    } catch (SoapFault $e) {
        throw new Exception("SOAP Client Error: " . $e->getMessage());
    }

    // Prepare the request
    $params = [
        'fileData' => base64_encode($encryptedData),
        'fileName' => basename($filePath)
    ];

    // Call the SOAP method
    try {
        $response = $client->__soapCall('uploadFile', [$params]);
    } catch (SoapFault $e) {
        throw new Exception("SOAP Call Error: " . $e->getMessage());
    }

    return $response;
}
