function encryptString($plaintext, $key) {
    // Check if the Mcrypt extension is loaded
    if (!extension_loaded('mcrypt')) {
        throw new Exception('Mcrypt extension is not available.');
    }

    // Define the cipher and mode
    $cipher = MCRYPT_RIJNDAEL_128;
    $mode = MCRYPT_MODE_CTR;

    // Create an initialization vector
    $iv_size = mcrypt_get_iv_size($cipher, $mode);
    $iv = mcrypt_create_iv($iv_size, MCRYPT_RAND);

    // Encrypt the plaintext
    $encrypted = mcrypt_encrypt($cipher, $key, $plaintext, $mode, $iv);

    // Check for encryption errors
    if ($encrypted === false) {
        throw new Exception('Encryption failed.');
    }

    // Return the encrypted string in base64
    return base64_encode($iv . $encrypted);
}
