function validate_signature($token, $timestamp, $nonce, $signature) {
    // Create an array with the token, timestamp, and nonce
    $data = array($token, $timestamp, $nonce);

    // Sort the array using SORT_STRING
    sort($data, SORT_STRING);

    // Implode the array into a single string
    $string_to_hash = implode('', $data);

    // Hash the resulting string using sha1
    $hashed_string = sha1($string_to_hash);

    // Compare the hashed string with the provided signature
    return $hashed_string === $signature;
}
