    // Connect to LDAP server
    $ldapConn = ldap_connect($ldapServer);
    if (!$ldapConn) {
        return "Could not connect to LDAP server.";
    }

    // Set LDAP options
    ldap_set_option($ldapConn, LDAP_OPT_PROTOCOL_VERSION, 3);

    // Bind to the LDAP server
    if (!ldap_bind($ldapConn, $ldapUser, $ldapPass)) {
        return "LDAP bind failed.";
    }

    // Construct LDAP query
    $filter = "(uid=" . ldap_escape($sanitizedInput, '', LDAP_ESCAPE_FILTER) . ")";
    $result = ldap_search($ldapConn, "ou=users,dc=example,dc=com", $filter);

    // Get entries
