import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class QueryBuilder {
    private List<String> whereClauses = new ArrayList<>();
    private final StringBuilder parameters = new StringBuilder();

    public QueryBuilder addWhereClause(String where, Object value) {
        if (value != null) {
            String hashedName = generateSHA1Hash(value.toString());
            whereClauses.add(String.format("%s==%s", where, hashedName));
            parameters.append(hashedName).append("=").append(value).append(";");
        } else {
            whereClauses.add(where);
        }
        return this;
    }

    private String generateSHA1Hash(String value) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-1");
            byte[] hash = digest.digest(value.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-1 algorithm not found", e);
        }
    }

    public List<String> getWhereClauses() {
        return whereClauses;
    }

    public String getParameters() {
        return parameters.toString();
    }
}
