function getUserSettings($userId, $tableName, $dbConnection) {
    $settings = [];

    // Prepare the SQL statement to retrieve user settings
    $stmt = $dbConnection->prepare("SELECT * FROM $tableName WHERE user_id = ?");
    $stmt->bind_param("i", $userId);
    $stmt->execute();
    $result = $stmt->get_result();

    // Check if any settings were found
    if ($result->num_rows > 0) {
        $row = $result->fetch_assoc();

        // Iterate through each field in the row
        foreach ($row as $key => $value) {
            // Set the setting as true if the field exists, false otherwise
            $settings[$key] = !is_null($value);
        }
    }

    $stmt->close();
    return $settings;
}
