function executeSshCommand($host, $username, $password, callable $callback) {
    $connection = ssh2_connect($host);
    if (!$connection) {
        throw new Exception("Could not connect to $host");
    }

    if (!ssh2_auth_password($connection, $username, $password)) {
        throw new Exception("Authentication failed for user $username");
    }

    $stream = ssh2_exec($connection, 'pwd');
    if (!$stream) {
        throw new Exception("Could not execute command");
    }

    stream_set_blocking($stream, true);
    $output = stream_get_contents($stream);
    fclose($stream);

    $callback(trim($output));
}
