function deleteContentElement($db, $elementId) {
    // Begin transaction
    $db->beginTransaction();

    try {
        // Prepare statement to delete the content element
        $stmt = $db->prepare("DELETE FROM content WHERE id = :id");
        $stmt->bindParam(':id', $elementId);
        $stmt->execute();

        // Update positions of subsequent elements
        $stmt = $db->prepare("UPDATE content SET position = position - 1 WHERE position > (SELECT position FROM content WHERE id = :id)");
        $stmt->bindParam(':id', $elementId);
        $stmt->execute();

        // Commit transaction
        $db->commit();
    } catch (Exception $e) {
        // Rollback transaction in case of error
        $db->rollBack();
        throw $e; // Rethrow the exception for further handling
    }
}
