function createTableAndQuery($conn, $tableName, $columns, $primaryKey, $queryConditions) {
    // Create table SQL
    $columnsSql = [];
    foreach ($columns as $column => $type) {
        $columnsSql[] = "$column $type";
    }
    $columnsSql[] = "PRIMARY KEY ($primaryKey)";
    $columnsSqlString = implode(", ", $columnsSql);

    $createTableSql = "CREATE TABLE $tableName ($columnsSqlString)";

    // Execute create table query
    if ($conn->query($createTableSql) === TRUE) {
        echo "Table $tableName created successfully.";
    } else {
        return ["error" => "Error creating table: " . $conn->error];
    }

    // Prepare query conditions
    $query = "SELECT * FROM $tableName";
    if (!empty($queryConditions)) {
        $query .= " WHERE " . implode(" AND ", $queryConditions);
    }

    // Execute select query
    $result = $conn->query($query);
    if ($result === FALSE) {
        return ["error" => "Error executing query: " . $conn->error];
    }

    // Fetch data
    $data = [];
    while ($row = $result->fetch_assoc()) {
        $data[] = $row;
    }

    return ["data" => $data];
}
