function processLeaseRecords($leaseRecords, $sortField, $filePath, $serviceName) {
    // Sort the lease records based on the specified field
    usort($leaseRecords, function($a, $b) use ($sortField) {
        return $a[$sortField] <=> $b[$sortField];
    });

    // Write the sorted records to a file
    $fileHandle = fopen($filePath, 'w');
    if ($fileHandle === false) {
        throw new Exception("Unable to open file for writing: $filePath");
    }

    foreach ($leaseRecords as $record) {
        fwrite($fileHandle, json_encode($record) . PHP_EOL);
    }
    fclose($fileHandle);

    // Restart the specified service
    $output = null;
    $returnVar = null;
    exec("systemctl restart $serviceName", $output, $returnVar);

    if ($returnVar !== 0) {
        throw new Exception("Failed to restart service: $serviceName");
    }

    return true;
}
