class UserDAO {
    private $connection;

    public function __construct($dbConnection) {
        $this->connection = $dbConnection;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->isValidPassword($newPassword)) {
            throw new Exception("Password does not meet strength requirements.");
        }

        try {
            $passwordDigest = hash('sha1', $newPassword);
            $stmt = $this->connection->prepare("UPDATE users SET password_digest = ? WHERE user_id = ?");
            $stmt->bind_param("si", $passwordDigest, $userId);
            $stmt->execute();

            if ($stmt->affected_rows > 0) {
                return "Password changed successfully!";
            } else {
                throw new Exception("Failed to update password. User may not exist.");
            }
        } catch (mysqli_sql_exception $e) {
            throw new Exception("Database error: " . $e->getMessage());
        } finally {
            $stmt->close();
        }
    }

    private function isValidPassword($password) {
        return strlen($password) >= 8 && preg_match('/[A-Z]/', $password) && preg_match('/[0-9]/', $password);
    }
}
