function handleRemoteConnectionRequest($requestUri, $method, $body, $headers) {
    $retries = 3;
    $i = 0;
    $seenBadStatusLine = false;
    $responseContent = '';

    while ($i < $retries) {
        $i++;
        try {
            $conn = new \Socket(); // Assuming a Socket class exists
            $conn->connect();

            $conn->request($method, $requestUri, $body, $headers);
        } catch (\Exception $e) {
            $conn->close();
            if ($e instanceof \SocketTimeoutException) {
                throw $e;
            } elseif ($e instanceof \SocketGaiError) {
                throw new \ServerNotFoundException("Unable to find the server at " . $conn->getHost());
            } elseif ($e instanceof \SocketError) {
                if (in_array($e->getCode(), [ENETUNREACH, EADDRNOTAVAIL]) && $i < $retries) {
                    continue; // retry on potentially transient errors
                }
