function createUserAccount(array $userData) {
    // Database connection (assuming $db is your PDO instance)
    global $db;

    // Extract user data
    $username = $userData['username'];
    $firstName = $userData['first_name'];
    $lastName = $userData['last_name'];
    $emailAddress = $userData['email'];
    $password = $userData['password'];

    // Hash the password
    $hashedPassword = password_hash($password, PASSWORD_BCRYPT);

    // Get current date and time for creation and activation
    $creationDate = date('Y-m-d H:i:s');
    $activationDate = date('Y-m-d H:i:s');

    // Get Gravatar URL
    $gravatarUrl = getGravatar($emailAddress);

    // Prepare SQL statement
    $stmt = $db->prepare("INSERT INTO users (username, first_name, last_name, email, password, creation_date, activation_date, gravatar_url) VALUES (?, ?, ?, ?, ?, ?, ?, ?)");
    $stmt->execute([$username, $firstName, $lastName, $emailAddress, $hashedPassword, $creationDate, $activationDate, $gravatarUrl]);

    // Retrieve the created user object
    $userId = $db->lastInsertId();
    return getUserById($userId);
}

function getGravatar($email) {
    $default = "https://www.example.com/default.jpg";
    $size = 200;
    $grav_url = "https://www.gravatar.com/avatar/" . md5(strtolower(trim($email))) . "?d=" . urlencode($default) . "&s=" . $size;
    return $grav_url;
}

function getUserById($userId) {
    global $db;
    $stmt = $db->prepare("SELECT * FROM users WHERE id = ?");
    $stmt->execute([$userId]);
    return $stmt->fetch(PDO::FETCH_OBJ);
}
