import json

class JSONBase:
    _factory_registry = {}

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_string):
        data = json.loads(json_string)
        instance = cls()
        instance.__dict__.update(data)
        return instance

    @classmethod
    def register_factory(cls, id, factory_function):
        cls._factory_registry[id] = factory_function

    @classmethod
    def create_instance(cls, id, *args, **kwargs):
        factory_function = cls._factory_registry.get(id)
        if factory_function:
            return factory_function(*args, **kwargs)
        raise ValueError(f"No factory function registered for ID: {id}")

# Example subclass
class Person(JSONBase):
    def __init__(self, name=None, age=None):
        self.name = name
        self.age = age

# Factory function for Person
def person_factory(name, age):
    return Person(name, age)

# Register the factory function
JSONBase.register_factory('person', person_factory)

# Example usage
if __name__ == "__main__":
    # Create a new Person instance using the factory
    person = JSONBase.create_instance('person', 'Alice', 30)
    print(person.to_json())  # Output: {"name": "Alice", "age": 30}

    # Create a Person instance from JSON
    json_string = '{"name": "Bob", "age": 25}'
