def set_layer_weights_and_save_model(model, layer_names, weights_dict, save_path, save_format='h5'):
    """Sets the weights of specified layers in a model and saves the modified model.

    Args:
        model: A pre-trained TensorFlow/Keras model.
        layer_names: A list of layer names whose weights need to be set.
        weights_dict: A dictionary mapping layer names to their corresponding weights.
        save_path: The file path where the modified model will be saved.
        save_format: The format to save the model ('h5' or 'tf').

    Raises:
        ValueError: If a layer name is not found in the model.
    """
