        return (PIX *)ERROR_PTR("pix not defined", procName, NULL);
    if (wc <= 0 || hc <= 0)   /* no-op */
        return pixCopy(NULL, pix);
    if (nx <= 1 && ny <= 1)
        return pixBlockconv(pix, wc, hc);
    pixGetDimensions(pix, &w, &h, &d);
    if (w < 2 * wc + 3 || h < 2 * hc + 3) {
        L_ERROR("kernel is too large: w = %d, wc = %d, h = %d, hc = %d\n",
                procName, w, wc, h, hc);
        return pixCopy(NULL, pix);
    }

