RETURNS VOID AS $$
DECLARE
    rec RECORD;
BEGIN
    -- Create a temporary table
    EXECUTE 'CREATE TEMP TABLE temp_data (id SERIAL PRIMARY KEY, name VARCHAR(100));';

    -- Insert data into the temporary table
    EXECUTE 'INSERT INTO temp_data (name) VALUES (''Alice''), (''Bob''), (''Charlie'');';

    -- Use a cursor to fetch data from the temporary table
    FOR rec IN EXECUTE 'SELECT * FROM temp_data' LOOP
        RAISE NOTICE 'ID: %, Name: %', rec.id, rec.name;
    END LOOP;

    -- Drop the temporary table
    EXECUTE 'DROP TABLE temp_data;';
END;
$$ LANGUAGE plpgsql;
