//      }

	if (todo & 64)
		log_appendf(2, " TODO: test this file with other players (beats per track != 64)");
	if (todo & 16)
		log_appendf(2, " TODO: double check 16 bit sample loading");

	/* done! */
	return LOAD_SUCCESS;
