import os
import difflib
import shutil

def read_file(file_path):
    with open(file_path, 'r') as file:
        return file.readlines()

def compute_differences(file1_lines, file2_lines):
    return list(difflib.unified_diff(file1_lines, file2_lines, lineterm=''))

def remove_matching_files(directory, criteria):
    for filename in os.listdir(directory):
        if criteria in filename:
            os.remove(os.path.join(directory, filename))

def create_directory(directory):
    if not os.path.exists(directory):
        os.makedirs(directory)

def process_remaining_files(directory):
    for filename in os.listdir(directory):
        file_path = os.path.join(directory, filename)
        if os.path.isfile(file_path):
            with open(file_path, 'r') as file:
                data = file.read()
                # Perform additional operations on the data
                print(f"Processing {filename}: {data[:50]}...")  # Print first 50 characters

def main(file1_path, file2_path, directory, criteria):
    file1_lines = read_file(file1_path)
    file2_lines = read_file(file2_path)

    differences = compute_differences(file1_lines, file2_lines)
    print("Differences between files:")
    for line in differences:
