            if (isInRenderingEngine && !is10Syntax(wrappingSyntaxId)
                && (HTMLUtils.containsElementText(result) || result.indexOf("{") != -1))
            {
                result.insert(0, "{{html clean=\"false\" wiki=\"false\"}}");
