import gzip

def gff3_to_gtf(gff3_file, gtf_file, dialect='default'):
    with open(gff3_file, 'rb') as f:
        if gff3_file.endswith('.gz'):
            with gzip.open(f, 'rt') as gz_f:
                lines = gz_f.readlines()
        else:
            lines = f.readlines()

    with open(gtf_file, 'w') as out_f:
        for line in lines:
            if line.startswith('#'):
                continue  # Skip comments
            fields = line.strip().split('\t')
            if len(fields) < 9:
                continue  # Skip malformed lines

            seqid, source, type_, start, end, score, strand, phase, attributes = fields

            # Convert GFF3 attributes to GTF format
            gtf_attributes = []
            for attr in attributes.split(';'):
                if attr.strip():
                    key_value = attr.split('=')
                    if len(key_value) == 2:
                        gtf_attributes.append(f'{key_value[0].strip()} "{key_value[1].strip()}";')
            gtf_attributes_str = ' '.join(gtf_attributes)

            # Write to GTF file
            out_f.write(f"{seqid}\t{source}\t{type_}\t{start}\t{end}\t{score}\t{strand}\t{phase}\t{gtf_attributes_str}\n")
