import hashlib

class HashGenerator:
    def __init__(self, algorithm='sha256'):
        self.algorithm = algorithm
        self.hasher = self._create_hasher()

    def _create_hasher(self):
        if self.algorithm == 'md5':
            return hashlib.md5()
        elif self.algorithm == 'sha256':
            return hashlib.sha256()
        else:
            raise ValueError("Unsupported hash algorithm: {}".format(self.algorithm))

    def update(self, data):
        self.hasher.update(data.encode('utf-8'))

    def digest(self):
        return self.hasher.hexdigest()

    def clone(self):
        clone = HashGenerator(self.algorithm)
        clone.hasher = self.hasher.copy()
        return clone

def hash_string(input_string, algorithm='sha256'):
    hasher = HashGenerator(algorithm)
    hasher.update(input_string)
    return hasher.digest()
