import re

def compile_template(template):
    def parse_tokens(template):
        tokens = re.findall(r'\{(.*?)\}', template)
        return tokens

    def convert_token(token):
        syntax_rules = {
            'add': '+',
            'subtract': '-',
            'multiply': '*',
            'divide': '/',
            'mod': '%',
        }
        return syntax_rules.get(token.strip(), token.strip())

    tokens = parse_tokens(template)
    converted_tokens = [convert_token(token) for token in tokens]
    expression = template
    for token, converted in zip(tokens, converted_tokens):
        expression = expression.replace(f'{{{token}}}', converted)

    return eval(f'lambda _n: {expression}')

