class SystemConfiguration
  attr_accessor :controllers, :sequencers

  def initialize
    @controllers = []
    @sequencers = []
  end

  def create_controller(id, name)
    controller = Controller.new(id, name)
    @controllers << controller
    controller
  end

  def create_sequencer(id, version, cache, io_bus)
    sequencer = Sequencer.new(id, version, cache, io_bus)
    @sequencers << sequencer
    sequencer
  end

  def assign_sequencer_to_controller(sequencer, controller)
    controller.add_sequencer(sequencer)
  end
end

