import hashlib

class FakeSwitch:
    def __init__(self):
        self.ports = {}

    def create_port(self, device_id):
        vm_id = self._generate_vm_id(device_id)
        self.ports[device_id] = {'vm_id': vm_id, 'tags': []}

    def get_port_tags(self, device_id):
        port = self.ports.get(device_id)
        if port:
