import base64
import secrets

class UserAccount:
    def __init__(self, username, phone_number, emergency_contact):
        self.username = username
        self.password_hash = None
        self.phone_number = phone_number
        self.emergency_contact = emergency_contact
        self.salt = os.urandom(16)

    def set_password(self, password):
        """Set the password for the user account, hashing it with a salt."""
        self.salt = os.urandom(16)  # Generate a new salt for each password
        self.password_hash = self._hash_password(password)

    def _hash_password(self, password):
        """Hash the password with the salt using SHA-256."""
        password_bytes = password.encode('utf-8')
        salted_password = self.salt + password_bytes
        return hashlib.sha256(salted_password).hexdigest()

    def verify_password(self, password):
        """Verify the provided password against the stored password hash."""
        return self.password_hash == self._hash_password(password)

    def generate_secret_key(self):
        """Generate a secure random secret key for the user."""
        return base64.urlsafe_b64encode(secrets.token_bytes(32)).decode('utf-8')
