import subprocess
import json
from collections import defaultdict

def get_commit_history(repo_path):
    command = ['hg', 'log', '--template', '{node}\n{parents}\n']
    result = subprocess.run(command, cwd=repo_path, capture_output=True, text=True)
    return result.stdout.strip().splitlines()

def analyze_commit_history(commit_history):
    commit_parents = defaultdict(list)
    for i in range(0, len(commit_history), 2):
        commit = commit_history[i].strip()
        parents = commit_history[i + 1].strip().strip('()').split(', ')
        commit_parents[commit].extend(parents)
    return commit_parents

def count_branches(commit_parents):
    branch_count = {}
    for commit, parents in commit_parents.items():
        branch_count[commit] = len(parents) + 1  # +1 for the commit itself
    return branch_count

def main(repo_path):
    commit_history = get_commit_history(repo_path)
    commit_parents = analyze_commit_history(commit_history)
    branch_count = count_branches(commit_parents)

    print(json.dumps(branch_count, indent=4))

if __name__ == "__main__":
    repository_path = '/path/to/your/repo'  # Change this to your repository path
    main(repository_path)
