from scapy.all import *

def update_packet_headers(packet):
    # Update headers
    if IP in packet:
        packet[IP].src = "192.168.1.1"
        packet[IP].dst = "192.168.1.2"

    if TCP in packet:
        packet[TCP].dport = 80
        packet[TCP].sport = 12345

    # Iterate through layers and update fields
    for layer in packet.layers():
        if layer.name == "HTTP":
            # Rename layer (for demonstration, we just print the name)
            print(f"Renaming layer: {layer.name} to HTTP Layer")
            # Update fields if necessary
            if hasattr(layer, 'fields'):
                for field in layer.fields:
                    if field == 'Content-Length':
                        layer.fields[field] = 0  # Example update

            # Remove unnecessary HTTP layers
            packet = packet.__class__(bytes(packet))  # Rebuild the packet
            packet = [l for l in packet.layers() if l.name != "HTTP"]
            packet = Ether()/IP()/TCP()  # Recreate the packet without HTTP layers

    return packet
