import json
import os

class FileIterator:
    def __init__(self, source, fail_on_missing=False):
        self.source = source
        self.fail_on_missing = fail_on_missing
        self._file = None
        self._iterator = None

    def __iter__(self):
        if self._iterator is None:
            self._load_source()
        return self

    def __next__(self):
        if self._iterator is None:
            self._load_source()
        return next(self._iterator)

    def _load_source(self):
        if isinstance(self.source, str):
            if not os.path.exists(self.source):
                if self.fail_on_missing:
                    raise FileNotFoundError(f"File not found: {self.source}")
                else:
                    return
            self._file = open(self.source, 'r')
            self._iterator = iter(self._file.readlines())
        else:
            raise ValueError("Source must be a file path as a string.")

    def to_json(self):
        return json.dumps({
            'source': self.source,
            'fail_on_missing': self.fail_on_missing
        })

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        return cls(data['source'], data.get('fail_on_missing', False))

    def close(self):
        if self._file:
            self._file.close()
