                "columns": [col.name for col in cols],
            },
            "meta": {
                "rowCount": rows,
                "totalCount": totalCount,
                "limit": limit,
                "offset": offset,
            },
        }

        if not lazy:
            row_data = []
            # Use the generator to add all rows in batches
            for rows in list(row_gen):
