def get_table_info(conn, table_name):
    """
    Retrieve column names and index information for a given table.

    @param conn: SQLite connection object
    @param table_name: Name of the table to query
    @return: A dictionary with keys 'columns' (list of column names) and 'indexes' (list of index names)
    """
    try:
        cursor = conn.cursor()

        # Query to get column names
        cursor.execute(f"PRAGMA table_info({table_name})")
        columns = [row[1] for row in cursor.fetchall()]

        # Query to get index information
        cursor.execute(f"PRAGMA index_list({table_name})")
        index_info = cursor.fetchall()
        indexes = [index[1] for index in index_info]

        return {
            "columns": columns,
            "indexes": indexes
        }
    except Exception as e:
        return {"error": str(e)}
    finally:
        cursor.close()
