using System;
using System.CodeDom.Compiler;
using System.Reflection;

class Program
{
    static void Main(string[] args)
    {
        if (args.Length < 1)
        {
            Console.WriteLine("Usage: DynamicCodeExecutor <code>");
            return;
        }

        string code = args[0];
        CompileAndExecute(code, args);
    }

    static void CompileAndExecute(string code, string[] args)
    {
        using (var provider = CodeDomProvider.CreateProvider("CSharp"))
        {
            var parameters = new CompilerParameters
            {
                GenerateExecutable = true,
                OutputAssembly = "DynamicAssembly.exe",
                GenerateInMemory = false,
                TreatWarningsAsErrors = false
            };

            parameters.ReferencedAssemblies.Add("System.dll");

            string sourceCode = @"
            using System;

            public class DynamicClass
            {
                public static void Main(string[] args)
                {
                    " + code + @"
                }
            }";

            CompilerResults results = provider.CompileAssemblyFromSource(parameters, sourceCode);

            if (results.Errors.Count > 0)
            {
                foreach (CompilerError error in results.Errors)
                {
                    Console.WriteLine($"Error ({error.ErrorNumber}): {error.ErrorText}");
                }
                return;
            }

            Assembly assembly = Assembly.LoadFile("DynamicAssembly.exe");
            MethodInfo method = assembly.GetType("DynamicClass").GetMethod("Main");
            method.Invoke(null, new object[] { args });
        }
    }
}
