from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker

def connect_to_databases(db_configs):
    engines = {}
    sessions = {}

    try:
        for db_name, config in db_configs.items():
            # Create an engine for each database
            engine = create_engine(config['url'], echo=config.get('echo', False))
            engines[db_name] = engine

            # Create a session for each engine
            Session = sessionmaker(bind=engine)
            sessions[db_name] = Session()

        return sessions

    except Exception as e:
        print(f"Error connecting to databases: {e}")
        return None

    finally:
        # Close all sessions
        for session in sessions.values():
            session.close()
        # Optionally, you can also dispose the engines
        for engine in engines.values():
            engine.dispose()

