import json

def deserialize_json(input_string):
    try:
        # Deserialize the JSON string
        obj = json.loads(input_string)

        # Function to decode non-string dictionary keys
        def decode_keys(d):
            if isinstance(d, dict):
                return {str(k): decode_keys(v) for k, v in d.items()}
            elif isinstance(d, list):
                return [decode_keys(i) for i in d]
            else:
                return d

        # Decode non-string keys
        return decode_keys(obj)
    except json.JSONDecodeError:
        return None
