import os
import hashlib

def calculate_md5_hashes(directory):
    file_hashes = {}

    for filename in os.listdir(directory):
        file_path = os.path.join(directory, filename)
        if os.path.isfile(file_path):
            with open(file_path, 'rb') as f:
                file_hash = hashlib.md5()
                while chunk := f.read(8192):
                    file_hash.update(chunk)
                file_hashes[filename] = file_hash.hexdigest()

    sorted_hashes = dict(sorted(file_hashes.items(), key=lambda item: item[1]))

    return {
        'number_of_files': len(sorted_hashes),
        'file_hash_map': sorted_hashes
    }
