import hashlib
import os

def hash_message(message: str, hash_function: str, salt: str = None) -> str:
    if salt is None:
        salt = os.urandom(16).hex()

    if hash_function not in hashlib.algorithms_available:
        raise ValueError("Specified hash function is not available.")

    hasher = hashlib.new(hash_function)
    hasher.update(salt.encode() + message.encode())

    return hasher.hexdigest()
