use std::sync::mpsc::{channel, SendError};
use std::thread;

struct MyError<T> {
    value: T,
}

fn oneshot_channel<T>(value: T) -> Result<(), MyError<T>> {
    let (sender, receiver) = channel();

    thread::spawn(move || {
        let _ = sender.send(value);
    });

    match receiver.recv() {
        Ok(_) => Ok(()),
        Err(_) => Err(MyError { value }),
    }
}
