fn generate_toc(input: &str, include_index: bool) -> String {
    let mut toc = TableOfContents {
        content: String::new(),
    };

    let sections: Vec<&str> = input.lines().collect();
    for (i, section) in sections.iter().enumerate() {
        toc.content.push_str(&format!("{}: {}\n", i + 1, section));
    }

    if include_index {
        toc.content.push_str("Index:\n");
        for (i, section) in sections.iter().enumerate() {
            toc.content.push_str(&format!("{} - {}\n", i + 1, section));
        }
    }

    unsafe {
        let rendered = render_toc(&toc as *const TableOfContents);
        if rendered.is_null() {
            return toc.content; // Fallback to the raw content if rendering fails
        }
        std::ffi::CStr::from_ptr(rendered).to_string_lossy().into_owned()
    }
}
