template <typename T>
std::string check_memory_layout(T* ptr) {
    if (ptr == nullptr) {
        return "Pointer is null.";
    }

    std::string layout_info;
    layout_info += "Size of struct: " + std::to_string(sizeof(T)) + " bytes\n";
    layout_info += "Alignment of struct: " + std::to_string alignof(T) + " bytes\n";

    // Assuming T has at least two fields named field1 and field2
    layout_info += "Offset of field1: " + std::to_string(reinterpret_cast<std::uintptr_t>(&ptr->field1) - reinterpret_cast<std::uintptr_t>(ptr)) + " bytes\n";
    layout_info += "Offset of field2: " + std::to_string(reinterpret_cast<std::uintptr_t>(&ptr->field2) - reinterpret_cast<std::uintptr_t>(ptr)) + " bytes\n";

    return layout_info;
}

// Example struct
struct ExampleStruct {
    int field1;
    double field2;
};

int main() {
    ExampleStruct example;
    std::cout << check_memory_layout(&example);
    return 0;
