use std::env;
use std::sync::{Arc, Mutex};
use log::{LevelFilter, Log, Metadata, Record, SetLoggerError};

struct LogBuilder {
    level: LevelFilter,
    formatter: Box<dyn Fn(&Record) -> String + Send + Sync>,
}

impl LogBuilder {
    fn new() -> Self {
        let level = match env::var("LOG_LEVEL") {
            Ok(val) => match val.as_str() {
                "error" => LevelFilter::Error,
                "warn" => LevelFilter::Warn,
                "info" => LevelFilter::Info,
                "debug" => LevelFilter::Debug,
                "trace" => LevelFilter::Trace,
                _ => LevelFilter::Off,
            },
            Err(_) => LevelFilter::Info,
        };

        let formatter = Box::new(|record: &Record| {
            format!("[{} {}] {}", record.level(), record.target(), record.args())
        });

        LogBuilder { level, formatter }
    }

    fn initialize_logger(&self) -> Result<(), SetLoggerError> {
        struct Logger {
            level: LevelFilter,
            formatter: Arc<dyn Fn(&Record) -> String + Send + Sync>,
        }

        impl Log for Logger {
            fn enabled(&self, metadata: &Metadata) -> bool {
                metadata.level() <= self.level
            }

            fn log(&self, record: &Record) {
                if self.enabled(record.metadata()) {
                    println!("{}", (self.formatter)(record));
                }
            }

            fn flush(&self) {}
        }

        let logger = Logger {
            level: self.level,
            formatter: Arc::clone(&self.formatter),
        };

        log::set_boxed_logger(Box::new(logger))?;
        log::set_max_level(self.level);
        Ok(())
    }
}

fn main() {
    let log_builder = LogBuilder::new();
    log_builder.initialize_logger().expect("Failed to initialize logger");

    log::info!("Logger initialized successfully");
}
