fn create_unique_directory(base_name: &str) -> std::io::Result<PathBuf> {
    let mut current_dir = env::current_exe()?
        .parent()
        .unwrap_or_else(|| Path::new("."))
        .to_path_buf();

    if current_dir.ends_with("deps") {
        current_dir.pop();
