#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

void copy_files(const char *src, const char *dest, const char *lib_path, const char *compiler_path) {
    struct stat st;
    if (stat(src, &st) != 0) {
        perror("stat");
        return;
    }

    if (S_ISDIR(st.st_mode)) {
        DIR *dir = opendir(src);
        if (!dir) {
            perror("opendir");
            return;
        }

        mkdir(dest, 0755);
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
                char src_path[PATH_MAX];
                char dest_path[PATH_MAX];
                snprintf(src_path, sizeof(src_path), "%s/%s", src, entry->d_name);
                snprintf(dest_path, sizeof(dest_path), "%s/%s", dest, entry->d_name);
                copy_files(src_path, dest_path, lib_path, compiler_path);
            }
        }
        closedir(dir);
    } else {
        // Check if the file is in the library path
        char lib_file[PATH_MAX];
        snprintf(lib_file, sizeof(lib_file), "%s/%s", lib_path, basename((char *)src));
        if (access(lib_file, F_OK) == 0) {
            // Copy the library file instead
            if (link(lib_file, dest) != 0) {
                perror("link");
            }
        } else {
            // Copy the source file
            FILE *src_file = fopen(src, "rb");
            if (!src_file) {
                perror("fopen");
                return;
            }
            FILE *dest_file = fopen(dest, "wb");
            if (!dest_file) {
                perror("fopen");
                fclose(src_file);
                return;
            }
            char buffer[4096];
            size_t n;
            while ((n = fread(buffer, 1, sizeof(buffer), src_file)) > 0) {
                fwrite(buffer, 1, n, dest_file);
            }
            fclose(src_file);
            fclose(dest_file);
        }

        // Set executable bit if the file is in the library path
        if (access(lib_file, F_OK) == 0) {
            chmod(dest, st.st_mode | S_IXUSR | S_IXGRP | S_IXOTH);
        }
    }
}
