use aes::{Aes256, BlockCipher, NewBlockCipher};
use aes::cipher::{BlockDecrypt, KeyInit};
use base64::decode;
use sha2::{Sha256, Digest};
use std::error::Error;

pub fn decrypt_blob(encrypted_blob: &str, device_id: &str, username: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    // Derive the secret key from device_id and username
    let mut hasher = Sha256::new();
    hasher.update(device_id);
    hasher.update(username);
    let key = hasher.finalize().to_vec();

    // Decode the base64 encrypted blob
    let decoded_blob = decode(encrypted_blob)?;

    // Assuming the first 16 bytes are the IV
    let (iv, ciphertext) = decoded_blob.split_at(16);

    // Create the cipher
    let cipher = Aes256::new(&key.into());

    // Decrypt the data
    let mut block = [0u8; 16];
    let mut decrypted_data = Vec::new();

    for chunk in ciphertext.chunks_exact(16) {
        block.copy_from_slice(chunk);
        cipher.decrypt_block(&mut block);
        decrypted_data.extend_from_slice(&block);
    }

    // Remove padding if necessary (assuming PKCS#7 padding)
    let padding_length = *decrypted_data.last().unwrap_or(&0);
    decrypted_data.truncate(decrypted_data.len() - padding_length as usize);

    Ok(decrypted_data)
}
