use std::path::{Path, PathBuf};
use std::fs;

fn realpath_no_symlinks<P: AsRef<Path>>(path: P) -> std::io::Result<PathBuf> {
    let mut absolute_path = fs::canonicalize(path)?;
    let components = absolute_path.components().collect::<Vec<_>>();
    let mut resolved_path = PathBuf::new();

    for component in components {
        match component {
            std::path::Component::RootDir => {
                resolved_path.push(component);
            }
            std::path::Component::Normal(name) => {
                let current_path = resolved_path.join(name);
                if let Ok(link_target) = fs::read_link(&current_path) {
                    resolved_path = link_target;
                } else {
                    resolved_path.push(name);
                }
            }
            _ => {}
        }
    }

    Ok(resolved_path)
}
