use hmac::{Hmac, Mac};
use sha1::{Digest, Sha1};
use base64::{decode, encode};
use std::str;

type HmacSha1 = Hmac<Sha1>;

fn decrypt_blob(encrypted_blob: &str, device_id: &str, username: &str) -> Option<String> {
    if encrypted_blob.is_empty() {
        return None;
    }

    // Generate the secret key using SHA-1
    let mut hasher = Sha1::new();
    hasher.update(device_id);
    hasher.update(username);
    let key = hasher.finalize();

    // Decode the encrypted blob from Base64
    let decoded_blob = match decode(encrypted_blob) {
        Ok(blob) => blob,
        Err(_) => return None,
    };

    // Create HMAC-SHA1 instance
    let mut mac = HmacSha1::new_from_slice(&key).ok()?;

    // Verify the HMAC
    mac.update(&decoded_blob);
    let result = mac.finalize();
    let hmac_result = result.into_bytes();

    // Here we assume the last 20 bytes are the HMAC and the rest is the actual data
    let (data, hmac) = decoded_blob.split_at(decoded_blob.len() - 20);

    if hmac != hmac_result.as_slice() {
        return None; // HMAC verification failed
    }

    // Convert decrypted data to string
    match str::from_utf8(data) {
        Ok(text) => Some(text.to_string()),
        Err(_) => None,
    }
}
