use hmac::{Hmac, Mac, NewMac};
use sha1::Sha1;
use serde_json::Value;
use std::collections::HashMap;

type HmacSha1 = Hmac<Sha1>;

#[derive(Debug)]
struct Request {
    headers: HashMap<String, String>,
    body: String,
}

#[derive(Debug)]
struct Config {
    secret_key: String,
}

#[derive(Debug)]
struct Response {
    status_code: u16,
    message: String,
}

fn verify_request(request: Request, config: Config) -> Response {
    let header_value = request.headers.get("X-Signature").unwrap_or(&String::new());
    let mut mac = HmacSha1::new_from_slice(config.secret_key.as_bytes()).expect("HMAC can take key of any size");

    mac.update(request.body.as_bytes());

    let result = mac.finalize();
    let code_bytes = result.into_bytes();

    if hex::encode(code_bytes) != *header_value {
        return Response {
            status_code: 404,
            message: "Request body is invalid".to_string(),
        };
    }

    Response {
        status_code: 200,
        message: request.body,
    }
}
