        if compute_md5 {
            let mut hasher = Md5::new();
            hasher.update(&contents);
            let result = hasher.finalize();
            let hash = format!("{:x}", result);
            if display_status {
                println!("MD5 hash for {}: {}", file_path, hash);
            }
        }

        if display_status {
            println!("Processed file: {}", file_path);
        }
    }
    Ok(())
}
