use std::fs;
use std::io::{self, Write};
use std::process::Command;
use std::path::{Path, PathBuf};
use tempfile::NamedTempFile;

fn generate_fdset(protobuf_path: &str) -> io::Result<PathBuf> {
    // Create a temporary file
    let temp_file = NamedTempFile::new()?;
    let temp_path = temp_file.path().to_path_buf();

    // Write the protobuf file to the temporary file
    fs::copy(protobuf_path, &temp_path)?;

    // Define the output path for the fdset
    let fdset_path = temp_path.with_extension("fdset");

    // Run the protoc compiler on the temporary file
    let output = Command::new("protoc")
        .arg("--descriptor_set_out")
        .arg(&fdset_path)
        .arg(&temp_path)
        .output()?;

    // Check if the command was successful
    if !output.status.success() {
        return Err(io::Error::new(io::ErrorKind::Other, "protoc command failed"));
    }

    // Return the path to the fdset file
    Ok(fdset_path)
}
