fn print_process_info() {
    // Get the current executable name and its suffix
    let exe = env::current_exe().unwrap();
    let exe_suffix = exe.extension().unwrap_or_default().to_str().unwrap_or("");

    // Get the current directory
    let current_dir = env::current_dir().unwrap();

    // Get the home directory
    let home_dir = env::var("HOME").unwrap_or_else(|_| String::from("Not set"));

    // Get the operating system
