use std::io::{self, Write};
use std::collections::HashMap;
use md5::{Md5, Digest};

fn authenticate_user(username: &str, password: &str, user_db: &HashMap<String, (String, Option<String>)>) -> Result<String, String> {
    if let Some((stored_password, salt)) = user_db.get(username) {
        // Check for plaintext password
        if stored_password == password {
            return Ok(format!("Welcome, {}!", username));
        }

        // Check for MD5 hashed password
        if let Some(salt) = salt {
            let mut hasher = Md5::new();
            hasher.update(format!("{}{}", salt, password));
            let hashed_password = format!("{:x}", hasher.finalize());

            if &hashed_password == stored_password {
                return Ok(format!("Welcome, {}!", username));
            }
        }
    }
    Err("Authentication failed".to_string())
}

fn main() {
    let mut user_db: HashMap<String, (String, Option<String>)> = HashMap::new();
    user_db.insert("user1".to_string(), ("password123".to_string(), None)); // Plaintext
