    // Execute the compiled program
    let output = StdCommand::new("./temp_program")
        .output()
        .map_err(|e| format!("Failed to execute program: {}", e))?;

    if !output.status.success() {
        return Err(format!(
            "Execution failed: {}",
            String::from_utf8_lossy(&output.stderr)
        ));
