use std::fs;
use std::io;
use std::path::{Path, PathBuf};

fn copy_recursive(source: &Path, destination: &Path) -> io::Result<()> {
    if !source.exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, "Source path does not exist"));
    }

    if !destination.exists() {
        fs::create_dir_all(destination)?;
    }

    for entry in fs::read_dir(source)? {
        let entry = entry?;
        let entry_name = entry.file_name();
        let destination_entry = destination.join(&entry_name);

        // Skip copying if the destination already has the same file or directory
        if destination_entry.exists() {
            continue;
        }

        if entry.file_type()?.is_dir() {
            // Recursively copy directories
            fs::create_dir(&destination_entry)?;
            copy_recursive(&entry.path(), &destination_entry)?;
        } else {
            // Copy files
            fs::copy(entry.path(), &destination_entry)?;
        }
    }

    Ok(())
}
