pub async fn setup_db_connection(db_url: &str) -> Result<(Transaction<'static>, App, impl Fn(HttpRequest, Result<HttpResponse, Error>) -> Result<HttpResponse, Error>)> {
    // Run database migration command
    let migration_status = Command::new("migrate")
        .arg("up")
        .arg(db_url)
        .status()
        .expect("Failed to run migration command");

    if !migration_status.success() {
        return Err(Error::from(HttpResponse::InternalServerError()));
    }

    // Set up database connection pool
    let pool = PgPool::connect(db_url).await.map_err(|_| HttpResponse::InternalServerError())?;
    let transaction = pool.begin().await.map_err(|_| HttpResponse::InternalServerError())?;

    // Middleware function to commit transaction
    let middleware = move |req: HttpRequest, result: Result<HttpResponse, Error>| {
        match result {
            Ok(response) => {
                // Commit transaction if the request was successful
                let _ = req.extensions().get::<Transaction<'_>>().map(|tx| tx.commit());
                Ok(response)
            },
            Err(err) => {
                // Rollback transaction on error
                let _ = req.extensions().get::<Transaction<'_>>().map(|tx| tx.rollback());
                Err(err)
            }
        }
    };

    Ok((transaction, App::new(), middleware))
}
