use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

struct History {
    buffers: Vec<String>,
    max_size: usize,
}

impl History {
    fn new(max_size: usize) -> Self {
        History {
            buffers: Vec::new(),
            max_size,
        }
    }

    fn push(&mut self, buffer: String) {
        if self.buffers.len() < self.max_size {
            self.buffers.push(buffer);
        }
    }

    fn commit(&self, filename: &str) -> io::Result<usize> {
        let path = Path::new(filename);
        let mut file = File::create(&path)?;
        for buffer in &self.buffers {
            writeln!(file, "{}", buffer)?;
        }
        Ok(self.buffers.len())
    }
}

fn main() -> io::Result<()> {
    let max_size = 5;
    let mut history = History::new(max_size);

    for i in 0..max_size {
        history.push(format!("Buffer {}", i));
    }

    let committed_length = history.commit("history.txt")?;
    assert_eq!(committed_length, max_size);

    Ok(())
}
