#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

int create_temp_file_descriptors(int *read_fd, int *write_fd) {
    char template[] = "/tmp/tempfileXXXXXX";
    int fd = mkstemp(template);
    if (fd == -1) {
        return -1; // Error creating temporary file
    }

    *write_fd = fd; // File descriptor for writing

    // Create a new file descriptor for reading
    *read_fd = dup(fd);
    if (*read_fd == -1) {
        close(fd);
        return -2; // Error duplicating file descriptor
    }

    // Set the file descriptor flags
    if (fcntl(*read_fd, F_SETFD, FD_CLOEXEC) == -1) {
        close(fd);
        close(*read_fd);
        return -3; // Error setting flags
    }

    return 0; // Success
}
