use std::env;
use std::process::Command;

fn open_file_with_program(path: &str) -> Result<String, String> {
    // Check for the BROWSER environment variable
    if let Ok(browser) = env::var("BROWSER") {
        return Ok(browser);
    }

    // List of alternative programs to try
    let alternatives = vec!["xdg-open", "gnome-open", "kde-open"];
    for program in alternatives {
        let output = Command::new(program)
            .arg(path)
            .output();

        if let Ok(status) = output {
            if status.status.success() {
                return Ok(program.to_string());
            }
        }
    }

    // If none of the programs worked, return an error message
    let tried_methods = alternatives.join(", ");
    Err(format!("None of the programs worked. Tried: {}", tried_methods))
}
