#include <iostream>
#include <string>
#include <openssl/md4.h>
#include <iomanip>
#include <sstream>

std::string calculate_md4_hash(const std::string& input) {
    unsigned char digest[MD4_DIGEST_LENGTH];
    MD4(reinterpret_cast<const unsigned char*>(input.c_str()), input.size(), digest);

    std::ostringstream oss;
    for (int i = 0; i < MD4_DIGEST_LENGTH; ++i) {
        oss << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(digest[i]);
    }
    return oss.str();
}

int main() {
    struct TestCase {
        std::string input;
        std::string expected_hash;
    };

    std::vector<TestCase> test_cases = {
        {"hello", "bde52cb31de33e46245e05fb9d332ca3"},
        {"world", "d4f5e1c3c1c1c1c1c1c1c1c1c1c1c1c1"},
        {"test", "a94a8fe5ccb19ba61c4c0873d391e987982fbbd3"},
        {"cryptography", "f3c3c3c3c3c3c3c3c3c3c3c3c3c3c3c3"}
    };

    for (const auto& test_case : test_cases) {
        std::string hash = calculate_md4_hash(test_case.input);
        std::cout << "Input: " << test_case.input << ", Expected: " << test_case.expected_hash 
                  << ", Calculated: " << hash << std::endl;
    }

    return 0;
}
