use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn find_command(command: &str) -> Option<PathBuf> {
    let mut paths = vec![];

    // Get the current executable's directory
    if let Ok(current_exe) = env::current_exe() {
        let current_dir = current_exe.parent().unwrap_or_else(|| Path::new("."));
        paths.push(current_dir.to_path_buf());
    }

    // Get the parent directory of the current executable
    if let Some(parent_dir) = env::current_exe().ok().and_then(|p| p.parent()) {
        paths.push(parent_dir.to_path_buf());
    }

    // Get directories from the PATH environment variable
    if let Ok(path_var) = env::var("PATH") {
        for dir in path_var.split(':') {
            if let Ok(path) = fs::canonicalize(dir) {
                paths.push(path);
            }
        }
    }

    // Search for the command in the collected paths
    for dir in paths {
        let command_path = dir.join(command);
        if command_path.exists() && command_path.is_file() {
            return Some(command_path);
        }
    }

    None
}
