use std::env;
use std::process::Command;

struct Config {
    build_type: String,
    additional_args: Vec<String>,
}

impl Config {
    fn new(build_type: &str, additional_args: Vec<String>) -> Self {
        Config {
            build_type: build_type.to_string(),
            additional_args,
        }
    }
}

fn parse_args() -> Config {
    let args: Vec<String> = env::args().collect();
    let build_type = args.get(1).unwrap_or(&"debug".to_string()).clone();
    let additional_args = args[2..].to_vec();

    Config::new(&build_type, additional_args)
}

fn main() {
    let config = parse_args();

    let mut command = Command::new("cargo");
    command.arg("build").arg("--profile").arg(config.build_type);

    for arg in config.additional_args {
        command.arg(arg);
    }

    let status = command.status().expect("Failed to execute cargo build");

    if !status.success() {
        eprintln!("Cargo build failed with status: {}", status);
    }
}
