use std::path::{Path, PathBuf};
use std::process;
use signal_hook::iterator::Signals;
use textwrap::wrap;

fn print_binary_name(binary_path: &str) {
    // Mute SIGPIPE signal
    let signals = Signals::new(&[signal_hook::SIGPIPE]).unwrap();
    std::thread::spawn(move || {
        for _ in signals.forever() {}
    });

    let path = Path::new(binary_path);
    let file_stem = path.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unknown binary");

    let formatted_output = wrap(file_stem, 50); // Fixed width of 50 characters
    for line in formatted_output {
        println!("    {}", line); // Indentation
    }
}

fn main() {
    if let Some(arg) = std::env::args().nth(1) {
        print_binary_name(&arg);
    } else {
        eprintln!("Usage: <binary_path>");
        process::exit(1);
    }
}
