use std::fs;
use std::io::{self, Write};
use std::path::Path;
use serde_json::json;

#[derive(Serialize)]
struct Pact {
    consumer: String,
    provider: String,
    interactions: Vec<Interaction>,
}

#[derive(Serialize)]
struct Interaction {
    description: String,
    request: Request,
    response: Response,
}

#[derive(Serialize)]
struct Request {
    method: String,
    path: String,
    headers: Option<std::collections::HashMap<String, String>>,
    body: Option<serde_json::Value>,
}

#[derive(Serialize)]
struct Response {
    status: u16,
    headers: Option<std::collections::HashMap<String, String>>,
    body: Option<serde_json::Value>,
}

fn generate_pact_file(pact: Pact, dir: &str) -> io::Result<String> {
    let pact_json = json!(pact);
    let pact_file_path = Path::new(dir).join("pact.json");

    // Write the PACT file
    let mut file = fs::File::create(&pact_file_path)?;
    file.write_all(pact_json.to_string().as_bytes())?;

    // Remove the temporary directory
    fs::remove_dir_all(dir)?;

    Ok(pact_json.to_string())
}
