import os
import json

def create_genesis_transaction(node_transactions, pool_name, client_ip, client_port):
    # Create directory for the pool if it does not exist
    pool_directory = f"./{pool_name}"
    if not os.path.exists(pool_directory):
        os.makedirs(pool_directory)

    # Prepare the genesis transaction data
    genesis_transaction = {
        "client": {
            "ip": client_ip,
            "port": client_port
        },
        "nodes": []
    }

    for transaction in node_transactions:
        node_data = {
            "ip": transaction['node_ip'],
            "port": transaction['node_port'],
            "services": transaction['services']
        }
        genesis_transaction["nodes"].append(node_data)

    # Write the genesis transaction to a file
    genesis_file_path = os.path.join(pool_directory, f"{pool_name}.txn")
    with open(genesis_file_path, 'w') as genesis_file:
        json.dump(genesis_transaction, genesis_file, indent=4)

    return genesis_file_path
