use std::fs;
use std::io;
use std::path::PathBuf;

struct TempDir {
    path: PathBuf,
}

impl TempDir {
    pub fn new() -> io::Result<Self> {
        let temp_dir = env::temp_dir();
        let new_dir = temp_dir.join(format!("temp_dir_{}", rand::random::<u64>()));

        fs::create_dir(&new_dir)?;

        Ok(TempDir { path: new_dir })
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}
