pub fn create_secure_connection(
    host: &str,
    port: u16,
    verify: bool,
    nodelay: bool,
) -> io::Result<TlsStream<TcpStream>> {
    let addr = format!("{}:{}", host, port);
    let stream = TcpStream::connect(&addr)?;

    if nodelay {
        stream.set_nodelay(true)?;
    }

    let mut builder = TlsConnector::builder();
    builder.danger_accept_invalid_certs(!verify);
    builder.danger_accept_invalid_hostnames(!verify);

    let connector = Arc::new(builder.build()?);
    let secure_stream = connector.connect(host, stream)?;

    Ok(secure_stream)
}
